/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20201005-4","meetingId":"r02-c-settlement","date":"2020年10月5日","dateIso":"2020-10-05","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時２５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を192件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和元年度品川区一般会計歳入歳出決算","agenda":"令和元年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"西村委員","kind":"質問","question":"おはようあります。１７１ページ、品川音頭等普及経費、１８３ページ、地域振興経費の町会ホームページ運営支援等、町会・自治会加入促進支援、時間が許せば、１９１ページ、児童見守りシステム運営費について伺ってまいります。コロナ禍における区の文化支援について伺ってまいります。子どもから伺いましたら、給食時はおしゃべりしないようにみんなが注意をする中で、流れる音楽に癒されていた様子です。","respondent":"大澤広報広聴課長","answer":"品川音頭ですが、今年度は残念ながら区民まつりが開催できませんでしたので、８月の２週間、ＦＭラジオにおきまして、岩本公水さんが出演して、「岩本公水の盆踊りのわ！しながわ」ということで、品川音頭を含めて、いろいろな盆踊りの曲等をかけておりました。","voiceIndex":6,"id":"exchange-001"},{"speaker":"西村委員","kind":"質問","question":"しながわ文化プログラム推進事業として、一昨日、無事開催され、昨日、読売新聞等でも大きく掲載されました五反田リバーステーションでの「品川船楽」ですが、私も当日伺いまして、今年はコロナ禍ということで、担当課、主催団体のご準備は本当に大変だったと思っています。そのほかに、このコロナ禍において、区で文化芸術活動を行うアーティストの支援として取り組まれていることがあれば教えてください。","respondent":"古巻文化観光課長","answer":"各文化センターや総合区民会館等におきましても、コロナ禍におけます対策についてのガイドラインを設けて、それに沿って文化活動がしっかり継続できるような取り組みを行っております。","voiceIndex":10,"id":"exchange-002"},{"speaker":"西村委員","kind":"質問","question":"例えばですが、北海道函館市で面白い取り組みがありました。芸術文化活動を行う区内のアーティストの支援につきましても、引き続きよろしくお願いしたいと思います。次に、地域振興経費から、町会ホームページ運営支援等、町会・自治会加入促進支援について伺ってまいります。会派でも研究を重ねておりますが、町会ホームページの目的、町会のホームページ利用数を改めてお聞かせください。","respondent":"川島地域活動課長","answer":"区の支援で、今、２３町会がホームページを立ち上げまして運用していただいております。目的につきましては、若い方、それから、広く町会活動を知っていただくということで、そのきっかけになればというところも含めて、区のほうで支援をしているものです。","voiceIndex":12,"id":"exchange-003"},{"speaker":"西村委員","kind":"質問","question":"以前にも質問させていただいたことがありますが、ホームページ開設が町会・自治会加入促進のため、交流のためという目的でありましたら、閲覧数等が、なかなか達成されなければ、方法を見直す必要があると思います。担当課で何か新しく取り組まれていくこと、また、これから実施することがあればお聞かせください。","respondent":"川島地域活動課長","answer":"実際の町会のホームページの作成支援につきましては、明治大学の協力をいただきまして同様の形で続けていく予定ですが、今年度、品川区町会・自治会連合会のホームページを作成しまして、そちらに各町会の紹介のページをぶら下げて掲示していただくような形で今。","voiceIndex":14,"id":"exchange-004"},{"speaker":"西村委員","kind":"意見","question":"ホームページをわざわざ見に行くというスタイルがなかなか難しいのかなと思っておりまして、こちらも昨日ですが、地元町会が小さな防災スタンプラリーを開催していました。安全面に大変配慮しまして、スタンプラリーという形で人が集まらないように注意をしながらなのですが、本当に町会の方たちがうれしそうで、子どもたちも大勢集まっておりました。何かご意見がございましたら、お聞かせください。","respondent":"川島地域活動課長","answer":"実際に運営していくところの維持管理等をどうしていくかという課題があるというふうに認識しています。","voiceIndex":16,"id":"exchange-005"},{"speaker":"西村委員","kind":"質問・要望","question":"最後に、時間がなくなってきたのですが、まもるっちについて伺っていきたいと思っておりまして、また教育費で補いたいと思います。防犯ブザーが鳴ったら、どのような経路で誰に連絡がいくのか、日中と深夜帯でも同じなのか、まもるっちの使用に関して不明点が多過ぎるため、新入生の保護者たちが混乱している様子が伺えました。","respondent":"黛生活安全担当課長","answer":"しかしながら、分かりにくいというようなお声があるということにつきましては、ＫＤＤＩのほうに伝えさせていただいて、しっかり対応させていただきたいというふうに考えております。","voiceIndex":18,"id":"exchange-006"},{"speaker":"西村委員","kind":"質問","question":"防犯ブザーの部分ですので、オプションになるのでしょうか。その手前の部分の基本機能かと思うのですけれども、お聞かせください。","respondent":"黛生活安全担当課長","answer":"ご指摘のとおり、それは基本の部分になります。そちらにつきましても分かりやすい説明をするように、これからやっていきたいと考えております。","voiceIndex":20,"id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"私からは、成果報告書１０ページ、ＩＣＴ推進管理費、１７１ページ、情報システム運営費、１８９ページ、生活安全推進事業、２０３ページ、品川区独自ボランティア（しな助）の拡充を順不同で質問いたします。生活安全推進事業です。そこで、現在、品川区における犯罪率や防犯ボランティアの団体は幾つあるのか、分かる範囲で教えてください。","respondent":"黛生活安全担当課長","answer":"これは戦後最悪を記録しました約７,０００件から大幅な減少となっております。減少の大きな理由は、地域の皆様方の防犯パトロールをはじめとした各種防犯活動によるところが多いというふうに認識しております。","voiceIndex":23,"id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"品川区では、全国に先駆け８３運動もあり、防犯ボランティア意識は大変高いものと承知しております。先ほど、１７０団体の届出があるというお話がありました。１７０団体というのは、１つにまとまっているわけではなく、ばらばらの団体で、品川区は一括で管理しているということではないということでよろしいでしょうか。","respondent":"黛生活安全担当課長","answer":"ご指摘のとおり、全てを管理している状況にはございません。","voiceIndex":25,"id":"exchange-009"},{"speaker":"松澤委員","kind":"意見","question":"いろいろなところでばらばらにやる、これも大切だと考えていますが、まとまりをもってやるほうが、より効果的であり、情報も共有しやすいと考えます。戸越で起こった事件が戸越でしか分からないのではなく、戸越で起こった事件の情報がすぐ中延にいく、旗の台にいく、そういった連携をするためにも、やはり１つにまとまったチームが大切だと思いますけれども、お考えをもう一度よろしくお願いします。","respondent":"黛生活安全担当課長","answer":"正にご指摘のとおりというふうに認識をしています。今後、警察ともしっかり連携をしていきまして、こうした自主的防犯活動を行っている団体の方々にもしっかりとアプローチをしながら、協力をして治安維持に当たっていきたいというふうに考えております。","voiceIndex":27,"id":"exchange-010"},{"speaker":"松澤委員","kind":"意見","question":"草の根で活動している団体を把握して品川区で管理する、これを一からシステムを作るのは、大変難しいことだと私も思っております。品川区の社会福祉協議会の品川ボランティアセンターで管理すれば、スポーツ、防犯、防災、町会・自治会、見守りとボランティアレガシーを広げ、社会参加しやすい環境が整うと思いますが、ご見解をお聞かせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"区独自ボランティア「しな助」についてのご質問かと思います。委員ご指摘のとおり、しな助は、東京２０２０大会に向けて機運を醸成していきましょうということで募集をしたものでございまして、終了後は解散する予定です。","voiceIndex":29,"id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"ぜひ前向きにご検討いただきまして、ボランティアの拡充が地域問題解決の１つの策になることを願い、次の質問に移ります。続きまして、成果報告書のＩＣＴ推進管理費から、今回のしながわ活力応援給付金の問合せに対し、自動回答プログラム「チャットボット」が導入されています。そこで、特別定額給付金に関する問合せ電話数と、しながわ活力応援給付金の問合せ電話件数を教えてください。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"７月１日の開設から９月３０日現在で１万２,２４０件のお問合せがございました。特別定額給付金の件数についてですが、開設していた約５か月間で３万３,７０８件のお問合せがあったというふうに聞いております。","voiceIndex":31,"id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"そういうことで数が減少しているということですね。これはチャットボットの導入で電話での問合せ件数が減ったものではないでしょうか。そこで、このＬＩＮＥ、チャットボットの現在における登録数、問合せ件数を教えてください。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"ＬＩＮＥの登録数ですが、直近の数で４,２２１件の登録があります。チャットボットへのお問合せに関しましては、９月３０日現在で８万４,６６５件の閲覧件数がございました。そのうちＬＩＮＥを活用して閲覧している数は、そのうちおおむね３割という形になっております。","voiceIndex":33,"id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"実際にチャットボットやＬＩＮＥを導入している自治体も多くあります。チャットボットは業務の効率化や、区民にとっていつでも質問できるメリットなども多くあります。そこで、しながわ活力応援給付金から始まったこのＬＩＮＥ、チャットボットの今後の課題や拡充に対するお考え、これからの情報発信をＬＩＮＥで広げるなどのお考えはありますでしょうか。","respondent":"山本情報推進課長","answer":"そのためのＦＡＱデータの充実であったり、定期的な更新作業を行ってまいります。今後の拡充についてですが、今運用しておりますチャットボットの利用状況などを見ながら、一般的な内容の問合せが多い部署を中心にチャットボットの導入を検討していきたいと考えています。","voiceIndex":35,"id":"exchange-014"},{"speaker":"松澤委員","kind":"質問・要望","question":"定型作業を自動化することで、職員が本当にコミュニケーションを必要とする仕事に取り組めると考えています。利用者と職員双方にメリットのあるチャットボットの拡充を、そしてパソコンよりも普及している携帯電話への情報発信の拡充を要望して、次の質問に移ります。続きまして、ＩＣＴ推進管理費についてです。このような基本原則の中、品川区におけるデジタル化に対するお考えをお聞かせください。","respondent":"山本情報推進課長","answer":"それを加速化させるためにも、長期基本計画において、来庁不要サービスの実現を目指しています。今現在、新しい生活様式に対応した行政サービスが求められておりますので、そういった行政手続のオンライン化は今後積極的に進めていきたいというふうに考えてあります。","voiceIndex":37,"id":"exchange-015"},{"speaker":"松澤委員","kind":"質問・要望","question":"官民共にメリットがある取り組みだと考えられます。国からは、デジタルガバメントの推進基準ガイドラインを参考に、サービスのフロント部分ではなく、バックオフィスも含め、エンド・トゥー・エンドでデジタル化、業務改革の取り組み等、徹底することが求められております。こうした近隣自治体との連携も視野に含めていく方法も検討しなければならないと思いますが、ご見解をお聞かせください。","respondent":"山本情報推進課長","answer":"こちらにつきましては、システム開発であったり運用の部分、それから制度改正の対応等、業務負担の軽減が見込まれるというところ、それからコスト削減が期待されるというところで、区といたしましても、こういった活用可能性は今後検討していきたいと思ってあります。","voiceIndex":39,"id":"exchange-016"},{"speaker":"松澤委員","kind":"質問・要望","question":"このようなサービスを利用しながら、新庁舎に向けて庁舎機能を検討していただいておりますが、新庁舎に向けてだけではなく、今できることは何かを考えていただくよう要望して質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-017"},{"speaker":"新妻委員","kind":"質問・要望","question":"１６５ページ、長期基本計画策定経費、１７１ページ、区民相談経費、２０５ページ、証明交付等窓口業務委託等から質問をします。最近、持続可能なという意味の「Sustainable」という言葉や、「ＥＳＧ債」、「ＥＳＧ投資」という言葉をよく耳にするようになりました。併せて、ＥＳＧ投資やＥＳＧ債とは何かご説明いただきたいと思います。","respondent":"佐藤企画調整課長、中山会計管理者","answer":"区といたしましては、職員の意識醸成がまず重要というところで、昨年度末から継続的に研修をし、身近な我々の業務そのものがＳＤＧｓの実現につながるというところを周知しています。ＥＳＧ投資、ＥＳＧ債について、簡単にご説明いたします。ＥＳＧとは、環境、社会、企業統治の英語の略になります。ＳＤＧｓの考え方を持って産業活動をしている企業に対して応援をしていこうという世界全体の流れがあります。","voiceIndex":43,"id":"exchange-018"},{"speaker":"新妻委員","kind":"提案","question":"職員の意識啓発等が、進んでいることが確認されました。公明党はこれまで、区民の目に触れるよう、庁舎の各課の窓口にＳＤＧｓの１７の目標のロゴマークを掲示するなど求めてまいりました。改めて提案をいたしますが、いかがでしょうか。そして、ＥＳＧ債につきましては３種類あるということです。品川区では保有しているのかどうか、他区の状況と併せて教えてください。","respondent":"佐藤企画調整課長、中山会計管理者","answer":"私からは、各課の窓口でのＳＤＧｓの表示ですが、係ごとのパネルといいますか、組織の表示ごとに扱っているＳＤＧｓが分かれるところもありますので、他自治体での表示の内容等を確認しながら、様々検討していきたいと考えています。他区の債券の状況は、公表されていないので実際のところは分からないのですが、少なくとも２３区中５区はＥＳＧ債に対して投資表明をしておりますので、この５区につきましては積極的にＥＳＧ債を購入しているのではないかと思われます。","voiceIndex":46,"id":"exchange-019"},{"speaker":"新妻委員","kind":"質問","question":"積極的に進めていく自治体があるということです。品川区でも検討されているのか、お考えをお伺いしたいと思います。","respondent":"中山会計管理者","answer":"投資表明をすることで、品川区がＳＤＧｓの考え方に基づいて積極的に事業を行い、投資活動においてもそうした視点を持っていくということになるかと思います。","voiceIndex":49,"id":"exchange-020"},{"speaker":"新妻委員","kind":"質問・要望","question":"先ほど松澤委員からありましたが、ワンストップ化について関連してお伺いしてまいります。区民相談のところでお伺いいたします。しかし、こういうときにこそ、やはり相談窓口が大事であるというふうに思っておりまして、今後、この専門相談の窓口もお相手のあることですけれども、電話相談やオンラインでの相談ができるような検討をお願いしたいと思いますが、見解を伺います。","respondent":"大澤広報広聴課長","answer":"高齢の方の相談者が多いので、オンライン相談がどこまでできるかという課題もあります。これらの課題を踏まえまして、相談の在り方については今後も検討をしていきたいと考えています。","voiceIndex":51,"id":"exchange-021"},{"speaker":"新妻委員","kind":"質問・要望","question":"確かに今おっしゃっていただいたそういう課題も大きいかと思いますが、何ができるのかというところで、しっかりご検討いただければと思います。新庁舎の基本構想には、求められる庁舎機能の第一に、区民に開かれた庁舎として、ワンストップ窓口、ユニバーサルデザインへの配慮などが掲げられておりますが、戸籍住民課から他課へも広げ、現庁舎でもできることがあるのではと期待をいたします。見解を伺います。","respondent":"木村戸籍住民課長","answer":"こちらに関しましては、さらに書かせない、待たせないというような形のサービスをこれからも引き続き検討してまいりたいです。それから、新庁舎移転に向けましたワンストップサービスにつきまして、戸籍住民課で庁内の検討の取りまとめということで行っております。","voiceIndex":53,"id":"exchange-022"},{"speaker":"新妻委員","kind":"質問","question":"現在できることを積極的にご検討いただけるです。改めて詳しくお伺いしますが、先ほど、課題もお伺いしたいと思っておりまして、現在の窓口の課題をお知らせください。","respondent":"木村戸籍住民課長","answer":"現在の課題ですけれども、実際、機械を利用していただく方が、まだかなり少ないということでございまして、１日に１件、２件ぐらいという状況です。そちらに関しましても、周知、それからご案内をさらに進めてまいりたいというふうに考えております。","voiceIndex":57,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"１７７ページの男女共同参画推進事業、後半は、職員採用時の履歴書の性別記載について伺いたいと思います。初めに、「みんなのひろば」が予算化されておりますが、その後どうなったのかということです。当事者の交流や不安や悩みを共有できる場と期待しておりますが、コロナ禍でも何とか工夫ができないものか伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"最初のときと違っているところは、やはりコロナ禍ですので、予約制にする。氏名の報告に関しましては、ニックネームでも可とするというような流れで検討しているところでございまして、現在、今年度の予定といたしましては、１２月１２日と２月１３日を予定しています。","voiceIndex":60,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"感染症対策も含めぜひ様々工夫しながら進めていただきたいと考えています。今回は、ジェンダー平等の実現へ品川区も力を発揮していただきたいということです。マイセルフ品川プランでは、男女平等意識の教育と啓発が位置付けられています。ジェンダー差別を乗り越え自分らしさを発揮することができる社会へ、品川区もジェンダー平等社会の実現に力を注いでいただきたいと思いますが、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"具体的には、男女平等意識の醸成やマイノリティへの配慮に向けた理解促進と支援を一層進めてまいりたいと考えているところでございまして、性別や性的指向、性自認にかかわらない男女共同参画社会を進めていくことが、ジェンダー平等につながるのではないかと考えております。","voiceIndex":62,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"様々取り組みが進められているとのことでありますが、お伺いしたいことは、ジェンダー差別というのは、どうやって作られたのか、その克服には何が必要なのか、区の考えを伺いたいと思います。改めて品川区は、ジェンダー差別はどのように作られたのか、その克服には何が必要と考えるのかお伺いしたいと思います。","respondent":"島袋人権啓発課長","answer":"マイセルフ品川プランの中では、基本目標の中に確かに性別にとらわれない人権尊重、多様な生き方への配慮を掲げておるところです。今後、区民や地域の方々に理解を広げるためのパンフレット、啓発活動を一層進めてまいりたいと考えているところです。","voiceIndex":64,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"様々事業を進めていることは理解しているつもりなのですが、私が伺ったのは、ジェンダー差別がどうやって作られたのか、区のお考えを伺いたいと思います。ぜひ品川区もそうした捉え方、またそれに見合った事業の展開を期待したいと思いますけれども、改めていかがでしょうか。","respondent":"島袋人権啓発課長","answer":"様々な教育環境のもとで、やはり学校との連携が重要かと考えていますので、若年層に向けた意識啓発、教育の推進というところは、連携をとりながら重点施策として連携して実施してまいりたいと考えております。","voiceIndex":66,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜこういうジェンダー差別が作られたのか、その背景については、ぜひいろいろ認識していただきたいと思います。最後に、不必要な性別記載欄について、これまでも職員採用時の履歴書から性別記載の削除を求めてきました。２３区でも既に幾つかの自治体で性別欄をなくして職員採用を行っておりますが、こうした動きも受け、品川区も採用時の性別欄をなくしていただきたいと思いますが、いかがでしょうか。","respondent":"黒田人事課長","answer":"採用時の応募者から提出させる応募書類、履歴書やエントリーシートにつきましては、適正な応募用紙としてＪＩＳ規格の様式例に基づいた履歴書を使うようにということが、労働行政を管轄する厚生労働省のほうから示されておりまして。","voiceIndex":68,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回、職員採用時から性別記載を削除するということで、よかったと思います。今後とも必要のない性別記載の削除について、随時点検をして進めていっていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"私からは、１８９ページ、歩行喫煙防止推進経費、１９１ページ、生活安全サポート隊活動費、１７５ページ、新年賀詞交歓会経費、１８７ページ、区民保養所経費、１９１ページ、しながわ発見出会い事業に関連して質問します。今年４月１日より、東京都受動喫煙防止条例が成立いたしまして、これにより屋内の規制はかなり進んだかと思います。","respondent":"黛生活安全担当課長","answer":"対しまして、生活安全サポート隊につきましては、ご案内のとおり、取締りもできるという権限を持っているというような違いがあるところです。","voiceIndex":72,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"生活安全サポート隊の方は歩行喫煙防止以外にも特殊詐欺対策の活動などもやられているので、そうしたことになると、やはり活動がやや制限されてしまうのかと思っているのですけれども、この人数の体制で大丈夫なのかお聞きいたします。","respondent":"黛生活安全担当課長","answer":"したがいまして、現在の体制である程度の対応はできているのかというふうな認識を持っているところです。","voiceIndex":74,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。これは要望で終わります。正にそのとおりでありまして、しっかりと見直しを行っていただきたいと考えております。やはり見直しすべき対象として、新年賀詞交歓会と区民保養所が挙げられるのかと考えていますけれども、まず新年賀詞交歓会ですが、確認としまして、このコロナ禍において、そもそも来年２０２１年の開催はあるのでしょうか。","respondent":"立川総務課長","answer":"ただ、開催内容につきましては、飲食を提供しないとか、そういったことで、区内官公署および区と関わりの深い地域団体との親睦を図り、併せて新年を祝うためという本来目的に沿いまして実施をしていきたいというように考えているところです。","voiceIndex":76,"id":"exchange-032"},{"speaker":"筒井委員","kind":"提案","question":"今年度の予算特別委員会のご答弁によりますと、会費制の導入検討をしていただけるということなのですけれども、やはり税金を支出しての飲食の提供というのは、納税者たる区民感情からいって不適切であり、また、２３区中のほぼ半分はもうそうした会費制を導入しているという事実、そして今回のコロナ禍で区民生活も困窮しているという状況なので、こうした状況の中、飲食を伴うのでしたら。","respondent":"立川総務課長","answer":"将来的には、会費制の導入ということも考えていかなければいけないかというふうには現状思っているところです。","voiceIndex":78,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"区民保養所についてお伺いいたします。そうした中、区内の施策活性化には直接広くつながらない区外にある保養所を維持する必要があるのか甚だ疑問であります。そこで、これを機に区民保養所は売却し、区民に直接広くつながる福祉、防災、新型コロナウイルス感染症対策に充てるべきと考えますけれども、いかがお考えでしょうか。","respondent":"川島地域活動課長","answer":"経費についても、平成２４年度に業務委託から民間貸付へ変更しまして、年間三、四億円程度圧縮しているというようなところもございまして、当面は今のような形を継続していきたいというふうに考えてあります。","voiceIndex":80,"id":"exchange-034"},{"speaker":"筒井委員","kind":"質問","question":"分かりましたけれども、町会の皆さんが行くには、別に品川荘、光林荘でなくてもいいはずでして、今、コロナ禍で地方の宿泊施設、宿泊業者の方が困窮しているという状況の中、別に品川区がわざわざ保養所を持って、そこを利用させるということをしなくてもいいのではないかと考えておりますし、今、新型コロナウイルス感染症の影響で、集まっての利用が果たしてふさわしいのかどうか、そうしたことも踏まえて。","respondent":"川島地域活動課長","answer":"こちらは今ご指摘のありましたとおりですけれども、私どもとしては、引き続き今のような形で運営していきたいというふうに考えているところですが、５年間の貸付期間が令和３年度末に終了いたしますので、そこで契約の更新等の手続を要するです。","voiceIndex":82,"id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。本当に何が重点なのかを見定めていただいて、そうした保養所の売却ということも真剣に検討していただきたいと考えております。それで、品川区のしながわ発見出会い事業は、「ＴＯＫＹＯふたりＳＴＯＲＹ」という東京都の結婚支援事業のサイトに、品川区結婚支援事業と紹介されておりますけれども、内閣府の支援対象事業には当たらないのか、まず確認としてお聞きします。","respondent":"川島地域活動課長","answer":"内閣府の事業には、当たらないです。","voiceIndex":84,"id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。当たらないという理由は、これは品川区のしながわ発見出会い事業は結婚支援事業であるから、今回の内閣府の結婚新生活支援事業の対象にならないという理由なのでしょうか。","respondent":"川島地域活動課長","answer":"私のほうも報道をもとに調べたところです。こちらは国の事業に申請し、採択され指定されてその補助を実施しているというふうに聞いておりますので、ちょっとその形には当たらないのかです。","voiceIndex":86,"id":"exchange-037"},{"speaker":"筒井委員","kind":"質問","question":"現在の品川区のしながわ発見出会い事業は、参加定数が２０人ちょっとと対象が著しく限られています。家賃補助など新婚生活のランニングコスト、イニシャルコストを補助してあげる支援のほうが、対象者も広く増えますので、今回の内閣府の補助対象となる結婚新生活支援事業というものを品川区も行ったほうが、より少子化対策として効果的だと思うのですけれども、この点、いかがお考えでしょうか。","respondent":"佐藤企画調整課長","answer":"区では、これまで様々な少子化対策を行ってきたところです。委員ご提案の新婚の方に対する補助事業というところは、詳細がまだつかめていないところもありますので、今後、国や都等からの情報を収集しながら、今後の予算編成の中で考えていきたいと考えています。","voiceIndex":88,"id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"そうしたことの負担、不安が、いくらかでも除去されれば、安心して結婚しようかなということにもなると思いますので、品川区もこの結婚新生活支援事業を行っていくという検討をぜひお願いしたいと思います。これは決して東京除外とか、そういうことではないと思いますので、ぜひ前向きにお願いしたいと思いますけれども、いかがお考えでしょうか。","respondent":"佐藤企画調整課長","answer":"事業の詳細を確認して、様々検討していきたいと考えています。","voiceIndex":90,"id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"そこから質問します。それから、１７７ページの人権啓発費、男女共同参画推進事業、１６９ページの広報広聴費の中から、ホームページ等経費と、１７１ページの情報公開等経費について伺います。私からは、ピンポイントに１点だけです。これでは、意味がないと思うのですけれども、お考えを伺います。弁明書や再弁明書が出せないのであれば、速やかに審査会へつなげるべきと考えますが、いかがでしょうか。","respondent":"大澤広報広聴課長","answer":"手順としては適切に行われていると考えておりますが、今後はより迅速な対応と丁寧な説明に努めてまいります。","voiceIndex":93,"id":"exchange-040"},{"speaker":"吉田委員","kind":"質問","question":"ですから、パソコンが苦手な方にとっては、このパソコンの音声読み上げではない別の配慮が必要かというふうに思います。これはご検討ください。ワードかテキストにすべきと考えますが、いかがでしょうか。ワードはバージョンが変わってしまうと、パソコンを変えないと読み取れなくなるそうですので、ただ、最低限はワードにすべきと考えますが、いかがでしょうか。広報広聴課としての見解を伺います。","respondent":"大澤広報広聴課長","answer":"ご指摘のありましたＰＤＦファイルにつきましても、今後、なるべくそうでない形式で進めてまいりたいというふうに考えてあります。","voiceIndex":95,"id":"exchange-041"},{"speaker":"吉田委員","kind":"質問・要望","question":"情報公開のほうですけれども、１か月程度ということですけれども、そうしたら私たちのほうも１か月程度ですか。それであれば、そちらからも期限を切って１か月ということであれば１か月で出していただきたい。ぜひこの辺については、きちんと私たちはルールを守りますので、そちらもルールを決めて、それに従って同じように進めていただきたいと思いますが、いかがでしょうか。","respondent":"大澤広報広聴課長","answer":"ルールを守っていないということではございませんが、より分かりやすい説明には努めてまいります。","voiceIndex":97,"id":"exchange-042"},{"speaker":"吉田委員","kind":"質問","question":"先ほどのホームページ上の文書は、テキストになっていたり、ＰＤＦになっていたり各所管によって大分違うのです。その辺については、今後、ホームページに載せられる資料全体をテキスト化していくということでよろしいでしょうか。","respondent":"大澤広報広聴課長","answer":"各所管の作成する書類については、ＰＤＦが一番ふさわしいという形もありますので、全てをテキスト化するというお約束はできませんが、ホームページ作成の研修を毎年行っておりますので、その中でアクセシビリティについては、今後も各所管で努力していただくように。","voiceIndex":99,"id":"exchange-043"},{"speaker":"吉田委員","kind":"質問","question":"人権啓発費、１７７ページの男女共同参画推進事業について伺います。その結果から、品川区の課題が少し見えましたので、質問をいたします。ＤＶについて相談したいと思ったときの窓口は、男女共同参画センターと理解してよろしいでしょうか。そこで全部の対応ができるとは思えませんので、相談した後、どこにどのようにつなげるのか、相談者への支援の仕組みを伺います。","respondent":"島袋人権啓発課長","answer":"本日は、総務費の款ですので、私から答えします。ＤＶ相談の窓口に関するご質問ですが、男女共同参画センターでは、ＤＶに関する啓発や専門相談員によるＤＶかどうか分からない、どうしてよいか分からないといった問合せの総合相談としてのＤＶ相談を実施しています。","voiceIndex":101,"id":"exchange-044"},{"speaker":"吉田委員","kind":"質問","question":"窓口となる男女共同参画センターで、これは福祉事務所につなげるべき事例だというふうに思ったら、そこで共通のカルテのようなものを作成して、福祉事務所につなげていく、これは本当に事業的に所管を超える事業なので、しかるべき所管につなぐときには、何度も繰り返して同じようなことを説明しなくて済むようなカルテのようなものが必要だと思いますが、そのような仕組みはあるのかどうか伺います。","respondent":"島袋人権啓発課長","answer":"この配偶者暴力相談支援センターを機能させるということは、まず生活圏域ごとの連携推進、情報共有の場を持つ、その会議を７月７日に第１回目を顔合わせとして実施したところです。","voiceIndex":103,"id":"exchange-045"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。ぜひその方向で進めていただきたいと思います。それから、男女共同参画センターは、最初の窓口ということなのですけれども、性暴力被害者の相談に関わる場合には、ある程度の専門性が必要だと思いますが、そういう担当者にはどういう人材を充てておられるのか、または研修などによって人材を育成しているのか、研修をしている場合にはどのような研修か伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"私たちも職員の研修といたしまして、二次被害を防ぐための研修等々も人権啓発課が中心になりまして、年に一度、職員研修という形で進めているところです。今年度も形を変えて研修を実施すべく、ただいま検討中、準備をしています。","voiceIndex":105,"id":"exchange-046"},{"speaker":"吉田委員","kind":"質問","question":"研修されているということで、年１回で大丈夫かなというふうに思うのですけれども、研修は進められているということで、できたらどのような研修か伺いたいと思います。そういう方向の質問です。減価償却費について伺います。財務４表、今公表されているものに付け加えて、附属明細もしくは注記、呼び方は正確にはよく分からないのですけれども、そういう資料が必要と考えますが、見解を伺います。","respondent":"島袋人権啓発課長、中山会計管理者","answer":"男女共同参画センターで行っておりますＤＶに関する研修ですが、ただいま専門相談員として派遣をしていただいてる全国女性シェルターネットの方を講師にお招きして講座をする、あるいは。今回は決算書のところに財務４表という形で載せさせていただきましたが、この後、ホームページとかに載せるときには、少し皆さんに分かりやすい工夫ということと。","voiceIndex":107,"id":"exchange-047"},{"speaker":"吉田委員","kind":"確認","question":"中身を確認すると、随分それまでの公会計レポートと変わっているので、それで時間がかかったのかと思いますが、これ、もう少しいろいろな詳細が出ているので、本来は決算のときに一緒に提供されると、より決算状況が分かりやすくなるのかと思うのですが、せめて今の審議している内容が例年どおりぐらいの１２月にアップされるのか、本来は決算資料と一緒にアップされるといいなと思うのですけれども、その辺。","respondent":"品川財政課長","answer":"品川区公会計レポートの関係ですが、ちょうど財務会計システムの変更等がございまして、元年度についてはちょっと公表が遅れたということで、今年度以降、しっかりとやっていきたいと、このように考えております。","voiceIndex":110,"id":"exchange-048"},{"speaker":"吉田委員","kind":"質問","question":"ちょっとではないかと、いつもより９か月遅いですし、去年の決算特別委員会からちょうど１年後に出たのです。１２月でも遅いと思うのですけれども、今年度の今審議されている分は、せめて今までどおり１２月、今後はできたら一緒のタイミングというのは難しいのでしょうか。ぜひ、決算の読み方は大分詳しくできるようになると思うのですが、いかがでしょうか。","respondent":"品川財政課長","answer":"公表の方式等、いろいろ違う部分がありまして、区が持っているデータから、また再度変換をかけてというような形になりますので、おおむね例年１２月に出すということになっていますので、それに間に合うような形でしっかりとやっていきたいと、このように思っております。","voiceIndex":112,"id":"exchange-049"},{"speaker":"松本委員","kind":"質問","question":"私からは、１６９ページ、広報経費、あるいは１９３ページ、都市型観光プラン推進事業と、あと、１７７ページ、人権啓発事業、時間が間に合えば、１８９ページの国際友好都市交流事業まで伺えればと思っています。この新しい公衆便所、かなりデザイン性がすごいというか、かなり先進的なものになっているのではないかと思います。","respondent":"大澤広報広聴課長","answer":"大井町駅前公衆便所ですが、１つ雑誌には、カラーで何ページかにわたって掲載がありました。広報に関して今後も努力してまいりたいと考えております。","voiceIndex":115,"id":"exchange-050"},{"speaker":"松本委員","kind":"意見","question":"雑誌の件は私も存じ上げなかったので、よかったなと思います。次に、人権啓発事業で、その中でも憲法週間行事費ですけれども、成果報告書の１２ページに成果として掲載されています。こちらは憲法週間講演と映画のつどいと、人権週間講演と映画のつどいの取組実績として応募人数が挙げられているのですけれども、実際の参加人数はどうなのかもお願いいたします。","respondent":"島袋人権啓発課長","answer":"成果報告書１２ページです。憲法週間講演と映画のつどいの応募人数という形で今回は掲載していますが、きゅりあんの大ホールに入れる人数が１,１００名ですので、今のところ、この数を維持しているということで開催しています。","voiceIndex":117,"id":"exchange-051"},{"speaker":"松本委員","kind":"質問","question":"おっしゃるとおり、数を見ると１,１００名で、この１,１００名を超える応募があるということなのですけれども、超えた場合は、抽選とかどのように決定されているのでしょうか。","respondent":"島袋人権啓発課長","answer":"このところ抽選をしています。ただ、こちらはやはり区民の方が中心ですので、応募が例えば他府県からの方だとか、２名応募の場合、１名が区民の方、１名が他自治体の方という方も、申し訳ないのですけれども、品川区の方を中心に選出しているという状況です。","voiceIndex":119,"id":"exchange-052"},{"speaker":"松本委員","kind":"質問","question":"分かりました。他区の人もいるというのは少しびっくりしたところですけれども、そのようにされているということで理解いたしました。憲法週間のほうなのですけれども、令和元年度の応募人数が平成２９年から１,０００名減っているわけです。１,０００名減るというのは結構大きなことかと思いますが、この原因としてはどういったことを考えていらっしゃいますでしょうか。","respondent":"島袋人権啓発課長","answer":"実際のところは、人権や平和のことをしっかりと考えて区民の方に周知していただくということを目的にしておりますが、知名度があり、他区でも実績のある方をお呼びしている関係上、たまたまこのときはこのようになった結果だと承知していただければと思っているところです。","voiceIndex":121,"id":"exchange-053"},{"speaker":"松本委員","kind":"意見","question":"舞の海さんのときは、ご出身の地方からということで、そこなのです。本件を取り上げた理由が、そもそも憲法週間講演の目的の部分が大事かなというふうに思っていまして、今少しお話がありましたけれども、憲法週間講演と映画のつどいのほうに絞って、この趣旨、目的について、もう一度お願いいたします。","respondent":"島袋人権啓発課長","answer":"テーマですが、人権、平和、憲法１１条の基本的人権、１４条の法の下の平等、差別されない権利や人間らしく生きる権利について、しっかりと考えていただくということをテーマに行っているものです。","voiceIndex":123,"id":"exchange-054"},{"speaker":"松本委員","kind":"質問","question":"先ほどは平成３０年の話でしたけれども、昨年のものを少し具体的に取り上げると、昨年の講演者は露木茂さんですか、ニュースキャスターの方かと思いますけれども、こちらはテーマが「“伝える”ということ～～日本を揺るがすニュースの“現場中継”に学ぶ～」ということなのですけれども、今、条文数が挙がった中で、こういう方だったら、２１条の関係なのかと思うのですけれども。","respondent":"島袋人権啓発課長","answer":"確かにきちんとテーマを設定しますと、やはり区民の方には、ある程度、知名度のある方をお呼びしたところで、例えば品川区におきましては、２３区で初めて「人権尊重都市品川宣言」を宣言しておりますし、こちらの周知も高めなければいけないということを考えますと。","voiceIndex":125,"id":"exchange-055"},{"speaker":"松本委員","kind":"質問","question":"一方で、もう１つの映画のほうなのですけれども、「家族はつらいよ２」ということになっているのですけれども、こちらはどういった理由で選ばれたのでしょうか。","respondent":"島袋人権啓発課長","answer":"こちらは家族が一番身近な存在であるし、家族のことを知るということ、こちらを今のところの人権の考えの中ではテーマにしています。ですので、「家族はつらいよ２」の前には、「家族はつらいよ」を上映させていただいているところです。","voiceIndex":127,"id":"exchange-056"},{"speaker":"松本委員","kind":"質問","question":"一方で、映画を見たからといって、すぐ憲法とか人権が頭に浮かぶかと言ったら、そうではなくて、例えば、関わってくるとしたら、２４条とか１４条とか、そういうところだと思うので、例えばこの映画が終わった後に少し解説を入れるとか、そういったことも考えられるのではないかと思うのですが、どうでしょうか。","respondent":"島袋人権啓発課長","answer":"今後、このコロナ禍ですので、こちらの講演と映画のつどいの開催方法もしっかりと時代に合わせて対応していかなければと考えているところですので、そのような考え方もしっかりと１つの視点として捉えていきたいと考えております。","voiceIndex":129,"id":"exchange-057"},{"speaker":"松本委員","kind":"質問・要望","question":"もう最後なので要望ですけれども、やっぱりこういったイベントは、どうしても年数をやっていくと、ある意味、ぐだぐだ感が出てくるところもあると思うので、そこの部分は、この機にしっかりとまた再検討していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-058"},{"speaker":"芹澤委員","kind":"質問","question":"私からは、１７１ページ、ＩＣＴ推進管理費に関連して、様々な行政のＩＣＴ化についてお伺いしていきます。菅新総理もデジタル庁の新設等を明言していますけれども、このデジタル化、行政のデジタル化の流れが、私は逆行することはなく、これからどんどん進んでいくのだろうと思っていますけれども、まず、品川区として、この流れが今後どうなっていくと思っていらっしゃるのかをお聞かせください。","respondent":"山本情報推進課長","answer":"区の考えですが、区といたしましては、これまでどおり区民サービスのデジタル化、それから区政運営のデジタル化というところを推進していきたいというふうに考えてあります。","voiceIndex":133,"id":"exchange-059"},{"speaker":"芹澤委員","kind":"質問・要望","question":"以前、品川区としても、組織の改編を行って、情報システム課から情報推進課になったというふうにも伺っています。当時、課名を変えたことの目的、変更前と変更後の人数、あとは、今現在、情報推進課の人数がどれほどなのかをお聞かせいただきたいと思います。情報推進課には３つの担当があると思いますが、どういった業務の振り分けをされているのかもお聞かせください。","respondent":"山本情報推進課長","answer":"平成２７年４月より情報システム課から情報推進課へ課名の変更をしたところです。その目的ですが、システムの運用管理だけではなく、今後もＩＣＴの推進を図っていこうというところが意味合いです。","voiceIndex":135,"id":"exchange-060"},{"speaker":"芹澤委員","kind":"質問","question":"役割としては、システムの運用、デジタル推進、セキュリティ、マイナンバーと、大体４つぐらいになるのかというふうに理解をしています。都庁のほうでも、今、人材の育成と雇用に取り組んでおりまして、外部から２年任期での新しい課長の雇用を始めたと伺っています。品川区として、内部でしっかりとＩＣＴに理解のある方の雇用、そして育成が必要だと思っていますけれども、そのお考えをお聞かせください。","respondent":"山本情報推進課長","answer":"ただ、ほかの自治体等の事例を見ますと、情報政策の支援などを行うＣＩＯ補佐官の任用だったり、委託を行っている自治体が増えてきておりますので、区といたしましても、そういったものの活用ができるかどうかというところは検討していきたいというふうに思っているところです。","voiceIndex":137,"id":"exchange-061"},{"speaker":"芹澤委員","kind":"意見","question":"実際、長期基本計画の中を見てみますと、３つの柱があって、その中に２１項目ぐらいの各論の項目があるのですけれども、その中には１つもＩＣＴに特化したお話が残念ながらありません。品川区は、調べてみますと、ＩＣＴに特化したＩＣＴ推進計画であったりとか、基本計画というものがまだできていないように思われるのですけれども、作ってもいいのかと思っていますけれども、そのお考えをお聞かせください。","respondent":"山本情報推進課長","answer":"区といたしましても、こういった大きな変化に対応していくために、様々な分野でのデジタル化を推進していくためにも、区全体としてのデジタルビジョンといいますか、そういったＩＣＴ計画の策定も今後考えていきたいというふうに思ってあります。","voiceIndex":139,"id":"exchange-062"},{"speaker":"芹澤委員","kind":"質問","question":"行政手続のデジタル化について関連して伺っていきたいと思います。努力義務ということではありますけれども、全庁的に企画部情報推進課として取り組まれていく中で、例えばペーパーレス化を、いろいろやってみてくださいと、多分、各部署にお話ししていただいていると思うのですが、できないというところをどういうふうに把握していらっしゃるのかをお聞かせいただければと思います。","respondent":"山本情報推進課長","answer":"文書の決裁につきましても、電子決裁の推進を以前から進めてきているところです。できていない場合への対応というところですけれども、特にそちらのほうでできていない箇所への個別の対応は行っていない状況です。","voiceIndex":141,"id":"exchange-063"},{"speaker":"芹澤委員","kind":"質問","question":"続けて、情報発信についてお伺いしたいと思います。私個人の話で言えば、スマートフォンのメールはなかなか見ません。そういった場合に、ＬＩＮＥのほうが、例えばリアルタイムであったりとか、あとは位置の情報の特定というのもありますので、そういった意味で、児童の安全を守るという意味でも、ＬＩＮＥの導入が必要なのかと思っていますけれども、そういったお考えもお聞かせいただければと思います。","respondent":"黛生活安全担当課長","answer":"今、委員のほうからご意見をいただきましたＬＩＮＥの活用ですが、現行のシステムにつきましては、令和４年度までの契約でございまして、この中で基本的な部分をいじっていくというのは非常に難しいところですが、新しいシステムを導入する際につきましては。","voiceIndex":143,"id":"exchange-064"},{"speaker":"芹澤委員","kind":"質問・要望","question":"茨城県では、これは業者の方々ではありませんけれども、全ての県民の方々が知事への手紙というような場所を作って、情報の発信、品川区とすれば情報の集約ができるようなシステムを使っているというふうに伺っていますけれども、情報推進課で、高度なアプリを使ったメール等ではなく、民間のアプリを使った情報の発信、情報の集約について、これからどう取り組まれるのかをお聞かせください。","respondent":"山本情報推進課長","answer":"情報発信に限らず、ほかの自治体の事例等も見ながら、具体的な運用方法はこれから考えていきたいと思います。ご案内いただきました幾つか具体的な事例等も、関係各課と共に検討してまいります。","voiceIndex":145,"id":"exchange-065"},{"speaker":"芹澤委員","kind":"質問","question":"区からの情報発信というところで言えば、今少しお話しさせていただきましたけれども、防犯と防災が非常に大きな鍵になると思っています。その地域に特化した情報を送る。ＬＩＮＥで言えば、子どもがいるかいないかで属性を分けて、子育て世帯には子育てに特化した情報を送るということもできるというふうに伺っています。質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-066"},{"speaker":"せお委員","kind":"質問・要望","question":"今年の７月にウーマンシフトという女性議員の団体から総務大臣に要望書が提出されました。その１週間後には、総務省からの通知で、旧姓の通称申請があった場合には、戸籍の謄本または抄本を確認すれば、証明書類を求めることなく通称認定して差し支えないと示されました。こちらに関しても、今後どのように品川区で取り組んでいくのか、見解を伺います。","respondent":"秋山選挙管理委員会事務局長","answer":"現状としては、選挙の記録を選挙管理委員会で作っておりまして、今回の都知事選挙からその告示に沿った形で対応をしていきたいというふうに考えているものです。","voiceIndex":149,"id":"exchange-067"},{"speaker":"せお委員","kind":"質問・要望","question":"女性に限らず、多様な方が選挙に立候補しやすくなることを望んでいますので、そちらも併せて要望いたします。次へ移ります。１７９ページ、庁舎管理費です。そこで、現在の庁舎に対する庁舎管理費ですが、新庁舎に移ることで、どのくらい費用を抑えられるのかということと、どの部分で抑えられるのかという、まだ検討の段階ですので想定される範囲でお答えいただけたらと思います。","respondent":"濱中庁舎計画担当課長","answer":"庁舎機能検討委員会におきましては、今後、維持管理コストを低減する設備であったり、また、老朽化した設備を更新しやすいような計画といったものを今後検討してまいる所存です。","voiceIndex":151,"id":"exchange-068"},{"speaker":"せお委員","kind":"質問・要望","question":"それが必然的に環境配慮へもつながることが多いですので、様々な好事例を参考に検討していただきたいと思います。これは要望で終わります。ただ、国が今、いろいろな委員からもお話がありますが、ＩＣＴの活用を進めていて、新庁舎が完成する頃には、どこにいても情報収集でき、要望も伝わり、議論でき、あとは連携がとれるという世の中になっていきます。","respondent":"濱中庁舎計画担当課長","answer":"委員にご指摘いただきました機能分散化による分かりにくさの点ですが、ご指摘のとおり、窓口の分かりやすさであったりですとか、周辺に施設が配置されているというところで、まずは庁舎機能としまして、区民の利便性向上につながるような窓口の在り方、また、部署の配置の仕方。","voiceIndex":153,"id":"exchange-069"},{"speaker":"せお委員","kind":"質問・要望","question":"ＩＣＴ化を必ず想定していただいた上で、新庁舎の機能を検討していただいて、さらに品川区に足りないものとか、そういったことを調査研究していただきたいと要望して私からは終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-070"},{"speaker":"つる委員","kind":"提案","question":"斎場運営費については、墓地関係、多分時間がないと思いますが、伺っていければと思います。ＬＧＷＡＮを活用することでセキュリティについても高いシステムであるというふうに理解しているのと、予算については１,６００万円程度だというところなのですが、総務委員会等ではまだ報告がないので、現状がどうなっているのか、まずそこの確認を教えてください。","respondent":"山本情報推進課長","answer":"こちらにつきましては、当初、１０月から予定していたところですが、緊急事態宣言等を受けまして、今、３か月遅れで準備を進めているところです。状況ですが、８月末に簡易型プロポーザルを実施いたしまして業者の選定をしたところで、今、契約準備等を行っているところです。","voiceIndex":158,"id":"exchange-071"},{"speaker":"つる委員","kind":"質問","question":"この間、一般質問、また予算特別委員会でも質疑をしていますが、これは全職員の方の利用と、区民向けサービスということの両方、大きくはその２つで活用していくというところと、区民の方が活用いただく際には、アプリ等での活用、スマートフォンを活用して利用できるようにするというようなご答弁もいただいております。","respondent":"山本情報推進課長","answer":"区民向けの対応ですが、どういった地図データ、レイヤーを作成して、それを公開していくかというところは、各所管が判断していくことになるかと思いますが、業務上、支障が出ない範囲で公開は進めていければというふうに考えてあります。","voiceIndex":160,"id":"exchange-072"},{"speaker":"つる委員","kind":"提案","question":"各課でそうした全てのシステムを活用されるというふうに理解しました。要は、先ほど、何か防犯的なことがあれば、まもるっちを経由した情報提供をという提案もありましたけれども、子どもたちへの活用というところでは、リアルタイム情報については、ＬＧＷＡＮを活用したクラウド型の地図アプリというのは、そういう活用はできるのかどうか教えてください。","respondent":"山本情報推進課長","answer":"地図アプリのリアルタイムの運用ですが、基本的には事前にこちらが指定して公開したデータを活用いただくということになりますので、リアルデータというところは、ちょっと運用が難しいのかなというふうに考えているところです。","voiceIndex":162,"id":"exchange-073"},{"speaker":"つる委員","kind":"提案","question":"取っ手があるから、人間はそれを自然に手に持って引いてドアを開ける。これはアフォーダンス理論という部分でありますけれども、ついついそういうふうにしてしまう、そうした正に仕掛け作りをやっていくことになるのかと思いますし、また、一般質問では、区民に対してそうしたステッカー等も配布したらいいのではないかというふうに提案しましたので、併せて現在の検討状況とか検討案を教えてください。","respondent":"東野経理課長","answer":"それから考えますと、かなり多くの来庁者の方に浸透しているのではないかと思われます。委員からご提案いただきましたナッジの考え方を取り入れました対応につきましては、さらなる来庁者の手指消毒の効果を上げるため、早速対応させていただいたところです。","voiceIndex":164,"id":"exchange-074"},{"speaker":"つる委員","kind":"提案","question":"今いろいろな共同墓地ですとか、いろいろな遺骨に対する考え方があるわけでありますが、例えば、交流協定を結んでいる自治体、そうしたところに公営の墓地を展開して、日常の交流、お盆の季節にしっかりとそうした交流も図れるような、そういう考え方を今後また機会を見つけて提案していきたいと思いますので、そのときに質疑したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":166,"id":"exchange-075"},{"speaker":"くにば委員","kind":"質問","question":"１６９ページより、ケーブルテレビとコミュニティＦＭ、あと、外国語版ラジオ広報番組、１７１ページより、デジタルサイネージについて伺います。区提供番組の制作費と予算は年間約９,８００万円に上るのですが、メインの品川区広報番組「しながわホットほっと」について伺います。こちら、当該番組の視聴率、推計視聴世帯数、または視聴人数等を教えてください。","respondent":"大澤広報広聴課長","answer":"広報番組の評価につきましては、「わ！しながわニュース」、また区からのお知らせ等、毎週配信しているところですが、やはり視聴世帯が多いということで、ケーブルテレビから情報を得る方は多いということで、一定の広報効果があるというふうに認識しています。","voiceIndex":168,"id":"exchange-076"},{"speaker":"くにば委員","kind":"質問","question":"データはないけれども、視聴している方は多いと、ちょっとその多いというのがどれぐらいか分からないのですけれども、私の中では多いというのがちょっと意外でした。ツイッターやフェイスブックで番組について触れることは現在まれ、年間１億円近い予算を割いているのですから、品川区の施策としてケーブルテレビの広報番組へもっと誘導したほうがいいのではないでしょうか。お考えをお聞かせください。","respondent":"大澤広報広聴課長","answer":"ホームページでは、ケーブルテレビで放映した番組につきましては、「しながわネットＴＶ」ということでＹｏｕＴｕｂｅで配信をしておりますので、そちらのほうを見ていただけると、例えばケーブルテレビが視聴できない家庭ですとか。","voiceIndex":170,"id":"exchange-077"},{"speaker":"くにば委員","kind":"意見","question":"更新されている情報が、１日に多数アップされているのですけれども、私は、直近でもいろいろなジャンルの動画がアップされているのを見たのですが、あれは正直、非常に分かりづらいです。という中で、やっぱりテレビに誘導するというのが、先ほど申し上げたカバー率等を考えたら非常に重要ではないかというふうに思うのですけれども、そのテレビの誘導について、もう一度ご答弁ください。","respondent":"大澤広報広聴課長","answer":"ホームページからテレビへの誘導ですが、今年、ホームページのトップページのリニューアル等を予定しておりますので、ただいまいただいたご意見も参考にしながらリニューアルについて検討していきたいと考えています。","voiceIndex":172,"id":"exchange-078"},{"speaker":"くにば委員","kind":"質問","question":"ぜひともケーブルテレビを、まだまだ現在以上にポテンシャルがあると思いますので、そこに関してはぜひよろしくお願いします。ＦＭしながわは、想定サービスエリアは品川区の６２.２％、約１４万世帯。こちらは、品川区広報番組「ほっとラジオしながわ」がメインなのですけれども、この聴取率、推定聴取世帯数や人数等を教えてください。令和元年度の総括評価、課題や今後の方針をお知らせください。","respondent":"大澤広報広聴課長","answer":"この１０月から番組をリニューアルしまして、区の情報をより的確に周知できますように、生放送の日にちも増やして対応しています。","voiceIndex":174,"id":"exchange-079"},{"speaker":"くにば委員","kind":"質問・要望","question":"今おっしゃった形で、ＦＭしながわの聴取人数がどんどん増えているということで、こちらも今以上に、昨年度まで以上にどんどん活用をぜひともしていっていただきたいと思います。もう１点、外国版ラジオ広報番組として、今、ＩｎｔｅｒＦＭの「Shinagawa Info.（しながわインフォ）」が５か国語で放送されています。ご見解をお聞かせください。","respondent":"大澤広報広聴課長","answer":"ＩｎｔｅｒＦＭにつきましては、今、ホームページで見られるようになっておりまして、そちらへのアクセス数も年々増加しています。こちらの活用につきましても、今後、検討課題とさせていただきたいと思います。","voiceIndex":176,"id":"exchange-080"},{"speaker":"くにば委員","kind":"意見","question":"最後に、デジタルサイネージについてです。こちらは昨年度までは区有施設のみに２９か所設置されていたと思うのですけれども、今回、主な新規の設置箇所についてお聞かせください。","respondent":"大澤広報広聴課長","answer":"令和元年度の新規設置は、戸越体育館、品川保健センター、荏原保健センターということで、３台、令和元年度中に新規で設置をしております。","voiceIndex":178,"id":"exchange-081"},{"speaker":"くにば委員","kind":"提案","question":"今回ご提案したいのが、区有施設のみではなくて、五反田駅、大井町駅、目黒駅とか、乗降客数が多い区内主要駅に設置すると情報到達対象が一気に増えて効果的だと考えますけれども、駅構内の独自の設置についてお考えをお聞かせください。","respondent":"大澤広報広聴課長","answer":"区有施設以外の設置につきましては、まだ区有施設に入れて効果検証している最中ですので、それを踏まえてまた今後の検討をしていきたいと考えています。","voiceIndex":180,"id":"exchange-082"},{"speaker":"くにば委員","kind":"質問・要望","question":"様々ある先ほど申し上げた区の広報媒体について、ぜひともきちんと予算効率とか、あとは広報効果を高めるために、戦略的に実際に広報的な効果をきちんと把握しながら、ぜひとも今後も活用の場を広げていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-083"},{"speaker":"おくの委員","kind":"質問","question":"私からは、２０７ページ、個人番号カード経費に関連してマイナンバーカードについてお伺いいたします。５月には特別定額給付金の給付に絡んでマイナンバーカードの申請が増えましたけれども、この９月からのマイナポイントの開始、またそれに先立つ７月からの申込の受付によって、マイナンバーカードの申請が増えていると聞いております。そこで、念のためにお伺いしておきます。","respondent":"木村戸籍住民課長、山本情報推進課長","answer":"カードの発行枚数です。現在、８月末現在ですけれども、累計で８万３,５１１枚ということで、区民の方の２０.４７％がお持ちだという形です。全国の状況につきましては、２０.１％とほぼ一緒の普及率になっているところです。マイナポイント事業のお尋ねです。マイキーＩＤ設定者の数ですけれども、国、それから品川区の数はこちらのほうで把握はしてございません。","voiceIndex":184,"id":"exchange-084"},{"speaker":"おくの委員","kind":"質問","question":"先ほど述べましたように、私が報道で知り得た限りでは、マイキーＩＤまで取得してマイナポイントを申請できたという方は、７月ないし８月の段階で３７７万人という数字なのだそうです。２割弱というのは、政府の見込みの数４,０００万人と比べての数なのですけれども、ですから、２,０００億円という予算に比べて全然少ないわけです。そこら辺のことをお考えをお聞かせください。","respondent":"山本情報推進課長","answer":"お持ちでない方を対象に、区では地域センターと第二庁舎３階のマイナンバーカードの交付特設会場でマイナポイントの予約申込の支援をまた別途行っているところです。","voiceIndex":187,"id":"exchange-085"},{"speaker":"おくの委員","kind":"質問","question":"マイナンバーカード自体の普及率は、先ほど、２０.４７％ということでしたけれども、結局、５年間やって２０.４７％ということなのです。今回、かなり品川区でも増えたと思うのです。たしか以前に区民委員会で伺ったと思うのですけれども、品川区でも一六、七％だったと思うのです。その点に関して、品川区としてどのようにお考えになっているか、お考えをお聞かせください。","respondent":"山本情報推進課長","answer":"来年３月から保険証での利用等も予定されているところです。それ以外にも様々カードの利活用というところを、今、国のほうで計画をしていますので、区といたしましては、引き続き、マイナンバー制度の安全性や利便性を周知しながらカードの普及に努めていきたいと考えています。","voiceIndex":189,"id":"exchange-086"},{"speaker":"小芝委員","kind":"質問","question":"私からは、１８５ページの補助２６号線開通記念事業について、また同じページの町会・自治会館建設等補助について、１８９ページの国際交流について、最後に１７５ページ、外国人学校児童生徒等保護者補助金についてお伺いいたします。記念事業をしました補助２６号線の今後の開通に向けた動き、スケジュールが、分かりましたら教えてもらえますでしょうか。","respondent":"川島地域活動課長","answer":"私ども地域活動課で把握していますが、車道部分の開通は令和３年３月頃の見込みでしたが、さらに延びる見込みというふうに聞いてあります。","voiceIndex":192,"id":"exchange-087"},{"speaker":"小芝委員","kind":"質問","question":"昨年の事業についてお聞きいたします。この事業に対する区の支出が３,５００万円余、その内訳でおよそ２,５００万円余が神輿連合渡御に充当されたと聞いております。２,５００万円余という額が神輿の渡御に支出されたというのは大変大きい額であると思います。今回、２６号線の開通がまだ先という中で、この２,５００万円余の額を投じたことへの評価をお聞かせください。","respondent":"川島地域活動課長","answer":"今の補助金の２,５００万円ですけれども、こちらは大変大きな規模のイベントであるということ、それから準備にも大変時間がかかったということで、延べ参加者ですと４,０００名、それから観客も５万人いたということで、非常に周到な準備のもとに。","voiceIndex":194,"id":"exchange-088"},{"speaker":"小芝委員","kind":"質問","question":"それを踏まえまして、補助２６号線の開通がされたとき、品川区として、行事といいますか、セレモニーをなされるという考えは今のところあるのでしょうか。何もしないわけにはいかないと思う一方で、既に記念事業は済んでおりますので、どのようにお考えか教えてください。","respondent":"川島地域活動課長","answer":"今回のイベントにつきましては、補助２６号線の開通前ということではありますが、機運醸成、お祝いという意味では、１回区切りをつけたものであるというふうに認識しております。","voiceIndex":196,"id":"exchange-089"},{"speaker":"小芝委員","kind":"質問","question":"続きまして、１８９ページの国際交流についてお伺いいたします。昨年度の決算ですので、事業としての影響は少なかったのかもしれませんが、新型コロナウイルス感染症は１月中旬に中国湖北省武漢市を封鎖しましたが、その後、全世界で急速に拡大していきました。３月までの間で、この品川区におけます国際交流にどのような影響がありましたでしょうか。","respondent":"宮澤協働・国際担当課長","answer":"ジュネーヴ市、オークランド市への青少年の派遣ができているところです。ただ、今年度につきましては、新型コロナウイルス感染症の影響を受けまして、オークランド市からの語学研修派遣および青少年のホームステイの受入が中止になったところです。","voiceIndex":198,"id":"exchange-090"},{"speaker":"小芝委員","kind":"意見","question":"行動が限られた中でこそ、全く新しい試みが生まれ、そして距離が離れていてもリモートでリアルタイムの交流が可能でもあります。まだまだ対面式の海外交流が難しい中で、希望となる道筋であると考えますが、区のこれからの国際交流に向けた姿勢、見解をお示しいただければと思います。","respondent":"宮澤協働・国際担当課長","answer":"この考え方、実際、現地に赴いてホームステイをする中で、異文化交流を深めてコミュニケーションをとることが重要だと考えておりますので、この考え方は引き続き同じです。","voiceIndex":200,"id":"exchange-091"},{"speaker":"小芝委員","kind":"質問","question":"ピンチはチャンスという言葉があります。対面での交流ができないからこそ、リモートで交流できる機会が増えてきたわけです。新たな姉妹都市の交流に向けて、民間同士のつながり、絆が深まれば、姉妹都市交流が実現される可能性はあるのでしょうか。アジアではまだ姉妹都市交流がなされていないことから、その一歩を踏み込むための積極的なご答弁をお願いいたします。","respondent":"宮澤協働・国際担当課長","answer":"この間、国際交流の在り方として、教育や福祉、また産業といった分野に特化した交流といった形もあろうかと思いますので、そういったところを含めて検討していきたいと思っています。","voiceIndex":202,"id":"exchange-092"},{"speaker":"小芝委員","kind":"質問","question":"続きまして、１８５ページ、町会・自治会館建設等補助についてお伺いいたします。この文書を見まして、私は強い懸念を覚えました。そういう中で、年度の予測を立てることは難しいと考えるのですが、例えば町会や自治会に会館建設に関するアンケート、またヒアリングを事前に行ったりして、おおよその件数を把握した上で予算計上するのでしょうか。","respondent":"川島地域活動課長","answer":"町会・自治会館の整備の支援につきましては、まず事前相談等、地域センターの所長を通じて、もしくは地域支援係のほうに直接お話をあらかじめいただいているところが多いので、そのような状況に基づきまして、今まで予算編成をしてきたところです。","voiceIndex":204,"id":"exchange-093"},{"speaker":"小芝委員","kind":"質問・要望","question":"町会からの申請といいますか、手を挙げるというのも変動的であったりもしますので、私としては、やはり地域社会の中枢といえます会館の建設補助については、十分に補助を出していただきたいと考えております。各会計決算審査意見書には執行率の低い事業については再考されたいとの意見が付されておりますが、この建設等補助についてもやはり同様に考えておられるのでしょうか。","respondent":"川島地域活動課長","answer":"そうは申しましても、やはりこちらは実績見合いで予算編成するということも必要だと思いますが、必要なときに町会の方が困らないような形でしっかりリサーチをしながら進めていきたいと思います。","voiceIndex":206,"id":"exchange-094"},{"speaker":"小芝委員","kind":"質問","question":"最後に、１７５ページ、外国人学校児童生徒等保護者補助金についてお伺いいたします。毎年、外国人学校に通います児童生徒等の保護者の負担を軽くするために、品川区から補助金が出されています。補助金を出す対象の外国人学校を中国、韓国、北朝鮮に限定しているわけですが、数ある外国人学校の中で、なぜ３か国に絞っているのか、目的と補助に至った経緯を教えてください。","respondent":"立川総務課長","answer":"現在、朝鮮、韓国、中国、この３か国の外国人学校に在籍する児童生徒等の保護者に対して補助金を出していますが、そもそも経緯ですけれども、昭和５０年代に朝鮮人学校等保護者補助金というものを創設いたしまして、その後。","voiceIndex":208,"id":"exchange-095"},{"speaker":"小芝委員","kind":"意見","question":"その後、２３区の多くで中華学校、韓国学校にも拡大してきたとの情報は受けております。一方で、１９９７年に北朝鮮による拉致事件が国会で取り上げられ、東京都は２０１０年に朝鮮学校への運営補助金を凍結した経緯があります。この補助金と東京都の平成２２年から今日に至るまで運営補助金を不交付としている判断との整合性をどのように捉えているかお答えを願います。","respondent":"立川総務課長","answer":"区の補助目的についてお話ししたいと思います。こちらは保護者への補助金です。一方で、東京都は、いわゆる学校の運営等、そういった観点から補助していると聞いております。そういった補助目的が異なるということで、保護者に対する補助金を継続しています。","voiceIndex":210,"id":"exchange-096"},{"speaker":"小芝委員","kind":"質問","question":"目的が違うという話もされました。そういうところで、やはり整合性をとるべきであるのかとは私は思います。とりわけいまだに拉致された日本人の同胞を帰さない国に対する補助金の支出に強い疑念を覚えましたことから質問をさせていただきました。終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-097"},{"speaker":"横山委員","kind":"質問","question":"私からは、１６９ページ、広報経費、１７３ページ、モバイルワーク検証経費、１７５ページ、危機管理経費、１８５ページ、地域活動基盤整備補助、１９５ページ、文化活動支援事業についてお伺いいたします。１点目に、非常時における情報発信の在り方についてお伺いいたします。２点目には、モバイルワーク検証経費についてお伺いいたします。３点目もいきます。","respondent":"大澤広報広聴課長、山本情報推進課長、古巻文化観光課長","answer":"デジタルサイネージにつきましては、４言語に対応しておりますので、緊急の情報を掲示いたします。スケジュールにつきましては、国のガイドラインが正式に出されてから具体的に検討していきたいと考えています。そういった文化、表現をしていただく方々への支援におきましては、例えば区民芸術祭において、毎年。","voiceIndex":214,"id":"exchange-098"},{"speaker":"横山委員","kind":"質問・要望","question":"情報発信のところですけれども、私は、５月２２日にPublic Labの勉強会で、「ニューヨークの新型コロナウイルス事情～行政の役割とアフターに向けて」をテーマに、ニューヨーク市都市計画局シニアプランナーの山崎清志さんのお話を伺いました。経過措置を設けることができない場合など、非常時におけるインターネット時代の発表の仕方として参考になると考えていますが、いかがでしょうか。","respondent":"大澤広報広聴課長、立川総務課長、川島地域活動課長","answer":"区民からは、区長の声を直接聞くと大変説得力があるというようなお声も届いておりますので。危機管理の観点からのニューヨーク市の事例ですが、情報収集に努めてまいります。ご指摘の点は大変重要であると認識しております。と同時に、区として適切な予算編成を行い執行率を高めていく努力も欠かせないものであるという認識です。","voiceIndex":218,"id":"exchange-099"},{"speaker":"横山委員","kind":"意見","question":"緊急時の情報発信についてですけれども、様々な新しいいろいろな手法もあると思いますので、その時々の情報の内容によって手段を組み合わせながら、様々研究、情報収集していただけたらというふうに思っております。補助金のほうも執行率というのも大変大切だということを、私自身、認識しております。その辺り、いろいろ周知ですとか工夫をしていただけたらと考えています。以上で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":222,"id":"exchange-100"},{"speaker":"塚本委員","kind":"質問・要望","question":"私からは、質問順に、２０７ページ、個人番号カード経費、１９５ページ、文化活動支援事業あるいは文化コミュニティ施設経費、この辺全般について、それから、時間がありましたら１８１ページの契約関係事務費、これは主にプロポーザルについてお伺いしたいと思います。","respondent":"木村戸籍住民課長","answer":"現在、時間の短縮に向けまして、先ほどおっしゃっていただきました補正での対応、それから今月ですけれども、平日も夜間、水曜日を除いてですけれども、夜の７時近くまで受け付けるというような形、それから、先月の下旬でございましたけれども、土曜日を。","voiceIndex":224,"id":"exchange-101"},{"speaker":"塚本委員","kind":"質問・要望","question":"マイナンバーカードに併せて、行政のＩＣＴ化みたいなところも含めて質疑をさせていただきたいのですが、このマイナンバーカード、行政のＩＣＴ化、デジタル化ということに関しては、個人認証を行う、リモートで誰が申請しているのかということを、なりすましを防止するため、本人確認する上で使えるツールというか、そういう意味では非常にデジタル化とか、いろいろなオンライン化とかという中で。","respondent":"山本情報推進課長","answer":"マイナポータルという専用のサイトから電子申請をして給付金の申請ができるというものでございましたが、実際に申請いただいた内容と、区が持っている情報、それを突合していく手段がなかったので、どうしても人間が入るというところで。","voiceIndex":226,"id":"exchange-102"},{"speaker":"塚本委員","kind":"質問","question":"この行政の縦割りの打破と言うと、どこかの言葉みたいなのですけれども、縦割りの弊害を解消していくということが非常にこれから問われてくるというか、大事なポイントになってくるのだと思うのですけれども、この前、そういった１つの事例として、区民の方から、保育園への医療証の提出ということに関わって、医療証を９月３０日ぐらいまでに出してほしいと言われたのだけれども。","respondent":"山本情報推進課長","answer":"その中でそういった部分、部署間の連携、データの連携というところは非常に重要になってくるかと思いますので、具体的に今、方向性というところはないのですけれども、今後、国のほうから各業務システムの標準化の仕様等が出される予定になってありますので。","voiceIndex":228,"id":"exchange-103"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは一朝一夕にはなかなかできない問題であるし、やり方を間違えて、もっと不便になったりしてもいけませんので、本当にしっかりと検討していただいて、全庁的に縦割りの解消につながる、区民サービスの向上につながるデジタル化を今後とも進めていっていただきたいというふうに要望させていただきたいと思います。次に、文化活動支援事業、文化コミュニティ施設経費です。","respondent":"古巻文化観光課長","answer":"文化施設等につきましても同様で、休館をしていた時期もありますけれども、休館以降、徐々に活動は戻ってきておりますが、まだ２割、３割といったような状況で、大きなホールですとかはそのような状況ですけれども、諸室につきましては、文化センターなどにおきましても。","voiceIndex":230,"id":"exchange-104"},{"speaker":"塚本委員","kind":"質問","question":"もしそうであったとすれば、そういったことをもう少し強く区内にも周知していく、発信していく、それで活動をもう少し、安全対策が可能な範囲で十分に広げていくということも対応として必要なのかと思うのですが、いかがでしょうか。","respondent":"古巻文化観光課長","answer":"まだちょっと心配な部分が多いので、安全に安全にということで、ご案内もそういう形の方向性になりがちですけれども、活動を行う中でのしっかりした感染症対策をしていただけるような周知をしっかり進めていきたいというふうに考えます。","voiceIndex":232,"id":"exchange-105"},{"speaker":"塚本委員","kind":"質問・要望","question":"時間があまりなくなってきたので、プロポーザルのことですけれども、中でも指定管理のところでお伺いしたいと思っていたのですが、品川区には品川区指定管理者制度活用に係る基本方針というところで、公募が原則だけれども、特別な理由がある場合には特定の事業者を選定できるというふうになっているのですが、その特別な理由には、どういうものがあるのか、時間がないのですが。","respondent":"佐藤企画調整課長","answer":"指定管理者選定に係る特別な理由ですが、指定管理者の実績等を評価いたしまして、引き続き指定することが合理的である場合、また、高齢者福祉施設や保育施設のように、区民サービスの継続性等を考えてその運営者に連続性が要求される場合は。","voiceIndex":234,"id":"exchange-106"},{"speaker":"木村委員","kind":"質問・要望","question":"私からは、１６９ページの一番下にありますシティプロモーション推進経費から質問をしたいと思いますが、本区には、「わ！しながわ」というキャッチコピーがありますけれども、単純な質問なのですが、なぜ「わ！しながわ」になったのでしょうか。例えば、「あ！しながわ」、「え！しながわ」とか、またほかには「さあ！しながわ」、「やあ！しながわ」に決定した経緯を教えていただきたいと思います。","respondent":"大澤広報広聴課長","answer":"「わ！しながわ」は、合い言葉になっていますけれども、これは「わ！しながわ」の後に続く言葉を区民の方が自由な発想で思い描けるようにということで、区民の投票を通してこのキャッチコピーに決まったものです。","voiceIndex":237,"id":"exchange-107"},{"speaker":"木村委員","kind":"質問","question":"いろいろ「わ！」という言葉、品川の「わ」かと最初は思ったのですけれども、新しいとか、懐かしいと、いろいろ「わ！ほかの市区町村から見て、「わ！」と声が上がるほど魅力のある住みたい、また住んでみたい、住み続けたいと思えるまちづくりとは、どのようなまちを想定しているのでしょうか。お聞かせください。","respondent":"大澤広報広聴課長","answer":"住み続けたいということで、やはり区民の方が区に愛着を持って、ここに住んでよかったと思える中で助け合いの精神も生まれてくると思ってありますので、そういう観点でシティプロモーションを進めてあります。","voiceIndex":239,"id":"exchange-108"},{"speaker":"木村委員","kind":"質問","question":"それだけ親しみのあるまちなのであろうと考えていますけれども、「とっておきの品川」という「とっておき」という言葉です、この「とっておき」とは、例えば大事にしまっておくとかという特別という意味だろうとも思いますけれども、ちょっと屁理屈的に聞こえるかもしれませんけれども、この「とっておきの品川」の言葉にどのような思いが込められているのでしょうか。これもお聞かせください。","respondent":"大澤広報広聴課長","answer":"じまん」では、その人その人が思っているとっておきの場所などを投稿していただいて、日に１０件程度の投稿があるのですけれども、そのような中で区民同士のコミュニケーションが図られていますので。","voiceIndex":241,"id":"exchange-109"},{"speaker":"木村委員","kind":"質問","question":"現在でも本当に品川区というところは住み続けていきたいという魅力のあるまちだとは思いますけれども、大都会の品川区ではなくて、今以上に人情味あふれるまち、住んでいてよかったなと思えるようなまちになるべきだと思いますが、近い将来の品川区の姿とは、どのような都市を想定しているのでしょうか。お聞かせください。","respondent":"大澤広報広聴課長","answer":"シティプロモーションの観点から、どういうまちですけれども、やはり区民の方が品川区を愛し、魅力を感じ、それを皆さんに自慢できるようなまちということで進めていければと考えています。","voiceIndex":243,"id":"exchange-110"},{"speaker":"木村委員","kind":"質問・要望","question":"区政モニターとは、モニター集会などに出席をしたり、区政に意見や要望を出していただき、各施設の見学に参加していただくこととあります。全ての要望を形に変えることは無理ですけれども、１つでも多くの声を形に変えるために、一人ひとりの発案や意見はどのように扱われているのでしょうか。そして、その声はどれぐらいの割合で形に変わっていくのでしょうか。分かる範囲でお答えください。","respondent":"大澤広報広聴課長","answer":"割合というのは、いろいろなご意見があり、取り入れられるもの、取り入れられないものありますが、できる範囲で施策に反映するように各所管にも意見はお返ししたりしています。","voiceIndex":245,"id":"exchange-111"},{"speaker":"木村委員","kind":"質問","question":"２行下にありますけれども、しながわ未来トーク、６万７,０００円余からの質問ですけれども、ホームページには、しながわ未来トークとは、「区内在学の学生と区が品川のまちづくりについて意見交換を行い、魅力ある品川区や協働社会の実現を目指すことを目的に実施しています」と紹介されていました。区政モニターと大きく違う点は、どのようなところでしょうか。もし分かればお聞かせください。","respondent":"大澤広報広聴課長","answer":"令和元年度は、区内の大学に行きまして、学生が健康への地域貢献として何ができるかというテーマに、区長とカフェ形式でざっくばらんな意見交換をしたところです。","voiceIndex":247,"id":"exchange-112"},{"speaker":"木村委員","kind":"提案","question":"区政モニターは、区政に対して提案などをお寄せいただくことによって、区民との活発なコミュニケーションを図り、よりよい品川区づくりに役立てることを目的にしています。区政モニターは年齢層の幅が広く、区全体の現状を話合い、しながわ未来トークは、またこれからの新しい品川をつくるグループと考えてよろしいのでしょうか。","respondent":"大澤広報広聴課長","answer":"しながわ未来トークと区政モニターの違いですけれども、委員おっしゃるように、区政モニターはより幅広い年齢層、しながわ未来トークは若い世代を対象として意見を聞くという位置付けでよろしいと考えています。","voiceIndex":249,"id":"exchange-113"},{"speaker":"木村委員","kind":"質問・要望","question":"そう考えますと、しながわ未来トークでは、我々にはない若い発想で斬新な意見やアイデアが飛び出すそうですが、形になった意見や、またアイデアがあれば、差し支えのない範囲でお知らせいただきたいと思います。","respondent":"大澤広報広聴課長","answer":"斬新な意見としては、養護教諭との連携というような側面からのご意見もいただきました。学生からは、区長と話をしたことで、学習へのモチベーションが上がり、就職後に地域貢献としてできることを自分たちで考えていきたいというような意見も出たところです。","voiceIndex":251,"id":"exchange-114"},{"speaker":"木村委員","kind":"質問","question":"１７５ページの上から５行目、非核平和都市品川宣言事業の４行下、非核平和都市品川宣言３５周年記念事業２１４万９,０００円余から、１点だけの質問です。この使節団に参加された子どもたちは、原爆ドームや資料館を目にし、耳にしたことで、少年少女の心にはどのように映り、未来の自分に、またその次の世代に伝える役目として、どのように成長していくとお考えでしょうか。","respondent":"立川総務課長","answer":"広島への中学生の派遣ですが、こちらは毎年、各中学から１人ずつ出していただきまして、また、広島に行った成果を各学校に持ち寄っていただきまして、行かなかった生徒に関しましても、平和教育といった側面から多大な成果を上げている事業だというふうに認識しています。","voiceIndex":253,"id":"exchange-115"},{"speaker":"木村委員","kind":"質問","question":"無残な姿の広島を見ることで、二度と戦争を起こしてはいけないとか、核兵器を使用する戦争を起こしてはいけない、世界の平和を願って子どもたちは成長してほしいと思います。次に、１８７ページの下にあります区民保養所経費からの質問です。現在の利用状況はどのようになっているのでしょうか。お聞かせください。","respondent":"川島地域活動課長","answer":"区民保養所の再開に際しましては、宿泊業団体による対応のガイドラインがあるそうですが、そちらに準じて定員の半分程度を上限としてお客様を受け入れている状況です。","voiceIndex":255,"id":"exchange-116"},{"speaker":"木村委員","kind":"質問","question":"もちろん新型コロナウイルス感染症が収束し、落ち着いてからの話ですけれども、元の活気ある保養所に、すぐに戻ることは難しいと思いますけれども、区のお考えでは、どれぐらいの時間がかかり、どれぐらいの対策が必要とお考えでしょうか。最後にお願いします。","respondent":"川島地域活動課長","answer":"春までにある程度収束の見込みが立ちまして、令和３年度中には元気な保養所が蘇ってくれればいいなというふうに私どもは願っているところです。","voiceIndex":257,"id":"exchange-117"},{"speaker":"のだて委員","kind":"質問","question":"私からは、１６５ページの公有地活用等検討経費に関わって、荏原第四中学校跡地について質問します。公有地活用等検討経費では、約１,４００万円かかっていますが、場所や、何か所行ったのかなど、どういう検討を行ってきたのか伺います。この間の荏原第四中学校跡地活用について、何のために、何年間、暫定活用してきたのか伺います。","respondent":"佐藤企画調整課長、中元スポーツ推進課長","answer":"その後、委員からご紹介がありましたけれども、現在の状況になりますが、平成３０年に工事を行いまして、暫定保育園や仮設保育園、地域利用等で暫定利用をしておりまして、令和５年度までの５年間、使う予定です。荏原第四中学校跡地の活用の中で、体育館と校庭につきましては、私どもの課のほうで、地域の方を中心に地域利用として区民の方に貸し出しており、様々活用していただいているところです。","voiceIndex":260,"id":"exchange-118"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまで約１０年間ぐらいにわたり、暫定的に活用されてきたということです。やはりもう本格活用してほしいとの声が上がっています。区のスケジュールどおり、令和５年度までとすると、その後の活用が予定されているということだと思いますが、どのように活用方法を検討していくのか、また、広く住民が参加でき、意見を聞く場として、住民に開かれた検討会を行っていくべきだと考えますが、いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"１点目の昨年度の公有地活用等検討の中では、旧荏原第四中学校に関しましては、経費を使った検討はしておりません。様々な跡地や用地がありますので、それは企画調整課内部で職員が検討を進めているところです。","voiceIndex":263,"id":"exchange-119"},{"speaker":"のだて委員","kind":"質問","question":"３年半あるということですけれども、これはいつ頃示されてくるのでしょうか。いろいろ検討をしっかり行っていこうと思うと、時間もかかってまいりますので、いつ住民に意見を聞く場が設けられるのか、そういったスケジュール感を伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"跡地活用の具体的な案の提示時期ですけれども、まだたたき台を検討している段階ですので、具体的な時期がいつになりますという答弁はできませんけれども、行財政改革特別委員会でも調査項目になっておりますので。","voiceIndex":265,"id":"exchange-120"},{"speaker":"のだて委員","kind":"質問・要望","question":"この意見が反映されて特養ホームなどが作られました。やはりより幅広い方々から意見を聞けば、１年くらいはかかるということになりますので、そうすると、基本設計、実施設計などで２年ぐらいかかるとすると、そろそろ検討を始めていないと間に合いませんので、住民に広く意見を聞いていくという前提でスケジュールを組んでいくことを求めますが、いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"これまでの答弁と重なる部分がありますけれども、あと３年と６か月あるというところと、内部で一定のたたき台といいますか、方針といいますか、あと近隣のデータ等を整理したほうが議論も進むと思いますので、そういったものを今、整理をしています。","voiceIndex":267,"id":"exchange-121"},{"speaker":"のだて委員","kind":"質問","question":"やはり検討段階から住民参加を推進していくということが重要だと思っています。特に荏原第四中学校跡地、学校として地域に親しまれてきた土地の跡地活用を考えていく場合、やはり地域の声を反映していくことが、その後できた施設がより利用され親しまれていくことになると考えますが、いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"検討段階をいつからと判断するかにもよると思われますけれども、区として一定のたたき台といいますか、先ほどの答弁と重なりますけれども、近隣の要望等、また近隣施設にどういった公共施設があるかとか、中長期的なニーズとか、様々ありますので、その辺は今。","voiceIndex":269,"id":"exchange-122"},{"speaker":"のだて委員","kind":"質問","question":"やはりよく利用するということになると、地域住民の方が利用されることになると思います。そして、その方が利用されなければ無駄になってしまうということになりますし、地域の理解を得て進めていくということが必要だと思いますので、そのためにやはり住民参加を位置付けていくということが必要だと思いますけれども、いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"私どもも地域に受け入れていただける施設を当然作りたいといつも考えているところです。区政協等でも様々な意見ももう既にいただいておりますので、そういったものも総合的に見ながら、今、様々な情報等を分析してたたき台を作っているところです。","voiceIndex":271,"id":"exchange-123"},{"speaker":"のだて委員","kind":"質問・要望","question":"意見も聞いているということですが、さらに広く意見を聞いていただきたいと思うのですけれども、少し前に私が行った住民アンケートでは、開かれた検討会を設置すべきだと答えた方が７５％いらっしゃいました。住民意見を広く聞き反映していくことが求められていると考えますが、いかがでしょうか。開かれた検討会がもしできないということであれば、なぜできないのか、その課題が何なのか伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"区といたしましては、そういった検討会をどうするかというのは、また今後、様々検討していきたいと考えておりますので、まずはたたき台をつくっていきたいというふうに考えております。","voiceIndex":273,"id":"exchange-124"},{"speaker":"のだて委員","kind":"質問・要望","question":"近くの戸越公園駅周辺では再開発なども計画されておりますが、こういった再開発、超高層ビルの促進ではなく、特養ホームや、災害時には避難所になる区民集会所、障害者施設などの住民要望を反映した施設を求めますが、いかがでしょうか。区として、用途など住民要望を広く聞くためにアンケートなども行っていただきたいと思いますが、いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"私どもといたしましては、中長期的なニーズであったり、地元に受け入れられる施設、地域の特性等を考えて、今後、適切なたたき台を作って、また様々ご報告をしていきたいと考えています。","voiceIndex":275,"id":"exchange-125"},{"speaker":"あべ委員","kind":"確認","question":"時々聞いているのですけれども、これ、ページ数がどこになるのでしょうか、今、品川区で女性管理職の割合を教えてください。それから、１７１ページ、情報推進課の関係ですけれども、先ほどから議論になっております全庁の情報化を担っているとのことですけれども、その範囲は、出先も含めてということなのでしょうか。確認をさせてください。","respondent":"黒田人事課長、山本情報推進課長、東野経理課長、木村戸籍住民課長","answer":"区の女性管理職の割合ですが、部長級、課長級合わせまして２１％というような状況です。デジタル化の範囲は、出先も含めて全庁ということになります。第二庁舎は日立造船株式会社から再生可能エネルギーを入れておりまして、こちらの単価が１９.１１ｋＷｈという形になっております。未成年の子がいる割合というところですが、大変申し訳ございません、詳細はつかんでおりません。","voiceIndex":278,"id":"exchange-126"},{"speaker":"あべ委員","kind":"質問・要望","question":"品川区の職員人事の中で、管理職への女性の登用は、もう少し努力が足りないのではないか、これでいいと思ってしまっているのではないかと思いますが、今後の考え方も含めて伺いたいと思います。ぜひそちらは力を入れていただきたいと思うのですけれども、所管としてお考えを教えてください。これ、以前伺ったときには数字が出てきて、そのときには、数年前ですけれども６７％ぐらいということでした。","respondent":"黒田人事課長、山本情報推進課長、東野経理課長、木村戸籍住民課長","answer":"施策としましては、女性活躍セミナーを人事課主催で年に１回、民間企業等で活躍されているような方のお話をお伺いするような機会も設けておりますし。保健センター等出先施設のデジタル化ですが、特に保健センターは相談事業等のデジタル化のニーズは大きいと考えていますので、外。本庁舎につきましては、まだ再生エネルギーというような形での契約は行ってございませんが、今、契約を結んでおります東京電力におきましても。養育に関する取決めの割合です。","voiceIndex":283,"id":"exchange-127"},{"speaker":"あべ委員","kind":"提案","question":"こうやって接していても能力的に劣るとは全く思いませんので、ぜひそこを勘案していただければと思います。戸籍事務のほうです。ぜひこうしたことに関心を持っていただきたいのです。取決めをしていない場合、どのような働きかけをしていくべきなのかということも含めて、ぜひそうした数字が、あるいはそうした人たちに接することができる大切な部署ですから、ぜひ意識を持っていただきたいと思います。","respondent":"木村戸籍住民課長","answer":"基本的には、委任状をお持ちで、その委任状をお持ちの方のご本人確認ができるものがあればお渡しはしております。そういう考えです。","voiceIndex":288,"id":"exchange-128"},{"speaker":"あべ委員","kind":"質問","question":"現場で徹底していただければと思います。最後に暗証番号の設定をする端末も１台しかないというのも混雑の原因かと思うのですけれども、そこは改善の可能性はありますでしょうか。","respondent":"木村戸籍住民課長","answer":"改善を検討してまいります。","voiceIndex":290,"id":"exchange-129"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、１７５ページ、成人式経費、１７７ページ、災害対策職員待機寮管理費、１８９ページ、生活安全推進事業、この３点をお伺いしたいと思います。順不同でお伺いいたします。災害対策職員待機寮についてお伺いしたいと思います。そこでまず、入居状況をお尋ねしたいのですけれども、まず、建設型のほうです。品川区近隣とは、どの辺のエリアまでを差すのでしょうか。","respondent":"黒田人事課長","answer":"借上型住宅ですが、戸数の考え方としましては、４０戸を目安に予算を編成しておりまして、１戸当たりの民間の家賃９万円程度の物件を目安に考えているところです。品川区近隣ですけれども、現在、借り上げている住宅は全て品川区内にあるところです。","voiceIndex":293,"id":"exchange-130"},{"speaker":"こんの委員","kind":"質問","question":"現状が分かりました。次に、料金をお聞きしようと思って、今、課長にお答えをいただきましたけれども、借上型のほうは、そうすると、おおよそ９万円を目安に借り上げているということで理解いたしました。それから、借上型のほうは、そうすると、先ほども申し上げましたが、９万円を目安ですが、その９万円の半分、いわゆる５０％に相当する金額を補助している、それが賃料という理解でよろしいでしょうか。","respondent":"黒田人事課長","answer":"待機寮の使用料の設定の考え方ですが、かつては東京都の職員住宅の使用料の考え方を少し参考にして見直ししていたところがありますけれども、基本的には、現在、単身型の部屋ですと、大体月３万円程度、これは広さも若干違いますし、建物の新しい、古いということもありますので。","voiceIndex":295,"id":"exchange-131"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこで、この規則には優先入居があると思いますけれども、優先的に入居できる方の要件として、無線従事者免許を有する者、それから日本赤十字社救急法救急員である者、それから災害対策上必要な技術関係者とありますけれども、いわゆる災害対策のための職員待機寮であるので、こうした要件を付けていらっしゃるのだなと、これは大変にいいことだなというふうに思うのですが、この要件は。","respondent":"黒田人事課長","answer":"優先入居の考え方ですが、無線従事者、赤十字社救急法救急員は、かつて、大分前ですけれども、寮の無線機が第三級陸上特殊無線技士の免許がないと使えないような無線機が設置されていた関係で、そういった無線を持っている方ということでありますとか。","voiceIndex":297,"id":"exchange-132"},{"speaker":"こんの委員","kind":"質問・要望","question":"もう１つ、加えてお聞きすると、災害時の初動についてですけれども、昨年の台風第１５号、第１９号、自主避難所を開設したあのとき、この待機寮の職員の方はどのような対応をされていたのでしょうか。水害だけではなくて震災のとき、水害はある程度来ることが予測されるので体制がとりやすいですけれども、震災は突然来る。お願いします。","respondent":"黒田人事課長","answer":"災害時におきましては、待機寮の職員については、基本的に水害ですと、ご指摘のとおり予測できるところがありますので、一定程度、当番制をとって待機しているというふうになっているものでございまして、あと。","voiceIndex":301,"id":"exchange-133"},{"speaker":"こんの委員","kind":"質問","question":"そういう状況だということが分かりました。次にまいります。ちょっと漏れている部分もありますけれども、そうした件数でした。その中で、特に女子児童の被害が多くて、発生時間は４時頃が多かった。パトロールをしてくださっているのですけれども、こうした警視庁のメールの情報をもとにパトロールの強化、地域の方との連携、協力が必要と思いますけれども、いかがでしょうか。","respondent":"黛生活安全担当課長","answer":"そういうところを改めまして一生懸命やっていくことによりまして、安全安心を肌で感じていただけるように努めてまいりたいと思います。","voiceIndex":303,"id":"exchange-134"},{"speaker":"こんの委員","kind":"質問・要望","question":"連携をとってやっていただきたいと思います。特に大通りではなくて生活道路で起きております。人通りの少ないそうしたところで起きておりますので、そうなると、パトロール車が入れないようなところでも起きておりますので、しっかり警察と連携をとってパトロールの強化、防犯対策の強化をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":305,"id":"exchange-135"},{"speaker":"鈴木（真）委員","kind":"確認","question":"私は、１７１ページ、広報広聴費の中から区民相談経費、１７７ページ、人権啓発費、同じく人事管理費、１８９ページ、地域活動費の中の地域支え愛活動を時間の限り質問します。男女共同参画センター、これは、確認です。それから、人事管理費です。平成３１年度として１４３名、約１６億４,８００万円です。それだけ若い人が辞めているという傾向と見たのですが、この辺についてどうお考えか教えてください。","respondent":"島袋人権啓発課長、黒田人事課長","answer":"利用者の方、登録団体の皆様には、時期を見据えつつ、区報やホームページなどで周知していく予定です。退職手当の令和元年度と平成３０年度との比較ですけれども、退職者のうち定年退職者が平成３０年度は８１名おりましたが、令和元年度は６４名ということで、定年退職者が少なかったことが退職手当が低くなっている要因です。","voiceIndex":307,"id":"exchange-136"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"男女共同参画センターのほうは、利用者に早く周知してあげて、これからも活用できるように十分にやっていただきたいと、要望にしておきます。退職の関係ですが、定年退職者は２０人弱の減ですね。ですから、若い人に積極的にやっていただくためにも、ぜひその辺をこれからも進めてもらいたいと思うのですが、まず、早期退職者４８人をどのように分析をしているか教えてください。","respondent":"黒田人事課長","answer":"そういった意味で言いますと、採用試験のときに志望動機などは必ず確認しておりますが、実際に配属になった職場で、自分が思っていた公務員の仕事と、実際に従事する仕事にギャップがあるというのは確かだろうというふうに思うのですが、そういった意味では。","voiceIndex":310,"id":"exchange-137"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"分かりました。ですから、ご本人の希望が違うのであれば、ほかの部署に移っていただいて、その中で生かしていただければと、これは要望させていただきたいと思います。どうしてもこの待機寮を公費で直すというと、お金の問題も出てくると思うのですが、その辺も、何かお考えがあれば教えてください。","respondent":"黒田人事課長","answer":"災害対策職員待機寮につきましては、平成の初頭に建ったものが多くございまして、築３０年を超えるというようなところが数多くありますので、先ほどのご質問にもありました初動体制を確保するという意味では、建設型の待機寮をどのぐらい維持するかにつきましては。","voiceIndex":312,"id":"exchange-138"},{"speaker":"鈴木（真）委員","kind":"確認","question":"分かりました。次に、犯罪被害者支援についてお聞きします。費用として３万１,０００円しか出ていないのですが、これは予算の事項別を確認していくと、啓発については人権啓発課、警察署との連絡窓口については地域活動課生活安全担当の３課連携で支援するということになっているのですが、どのような活動がされているのか、区にこういう相談がどのぐらい来ているのか、その辺について教えてください。","respondent":"大澤広報広聴課長","answer":"犯罪被害者支援の現在の区の取り組みですが、まず、定期的な庁舎内の連絡会議を開催しております。実際に被害のあった場合には、具体的な支援を検討するために、緊急で連絡会議を開催いたします。","voiceIndex":314,"id":"exchange-139"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"東京都も東京都犯罪被害者等の支援に関する条例を今年の４月から施行しているので、そちらに任せてしまうという意味なのか、区としてはもうちょっと積極的にやってもいいのではないかというところを感じているのですけれども、殊に最近ですと、ＳＮＳの被害とか、かなり大きな問題も出ていると思いますし、もうちょっと身近な自治体としての対応を考えるべきではないかと。","respondent":"大澤広報広聴課長","answer":"区としましては、都の条例や制度、また被害者支援都民センターの役割を踏まえまして、今後、区の役割を明確にして、やるべきことが何なのかということを検討してまいりたいと考えております。","voiceIndex":316,"id":"exchange-140"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"直接ではないですけれども、そういうところとの連携もとりながら、犯罪被害者支援にもう少し取り組んでいただければということをここで要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":318,"id":"exchange-141"},{"speaker":"西本委員","kind":"質問","question":"１６５ページの基金積立金についてお聞きしたいと思います。その脇に喫煙所があります。クレームをたくさんいただいております。所管が違うと言われればそれまでかもしれませんが、トイレの改修のときに、もう少し考えた形で、移設であったりとか、全体的な考えで整備をしていただきたかったと思うのですが、この喫煙所の在り方、考え方、これからどういうふうにされていくのかお考えをお聞きします。","respondent":"品川財政課長、大澤広報広聴課長、小林施設整備課長、黛生活安全担当課長","answer":"そういう状況に応じて、基本的には今後の状況を見て積み立てているというような状況です。区民の方からいただいたご意見です。代表的なものになりますが、同じような区民の声が来た場合は、抜粋してホームページ等で公開しております。区有施設、学校施設等を含めまして、改築や大規模改修を予定している施設を除きまして。このことによりまして、多くのご意見を、私どものところでもいただいているところではありますが、私どもといたしましては。","voiceIndex":321,"id":"exchange-142"},{"speaker":"西本委員","kind":"提案","question":"その考え方です。その考え方をお聞きしたいと思います。いろいろな要望が来ていると思います。喫煙所については、要望はかなり出ているのです。私はずっと、そこについてはここがいいのではないですかという提案もしましたので、それを含めて早急に考えていただいて、共存するためには早急にこういう考え方でやっていこうというものを出していただきたいと思いますので、その考え方をお聞きします。","respondent":"品川財政課長、大澤広報広聴課長、小林施設整備課長、黛生活安全担当課長","answer":"基金の積み立て方ですけれども、毎年決算の状況に応じまして、また当然、公共施設、学校改築等。いただいたご意見に対するご回答等ですけれども、ご意見、ご要望というところから出しているのですが、ホームページのネーミングについては。ＬＥＤ化の進め方ですが、やはりどういった方法で、どういった順番でやっていくか、その辺につきましては。喫煙所につきましては、適地への移設、また受動喫煙防止、喫煙所の過密状態を解消できる新しい技術やアイデア。","voiceIndex":326,"id":"exchange-143"},{"speaker":"西本委員","kind":"質問・要望","question":"最後に一言、喫煙所については、本当に最近、見方が厳しくなっております。なので、考え方を公表していただきたいと思いますので、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":331,"id":"exchange-144"},{"speaker":"大倉委員","kind":"提案","question":"初めに、プラネタリウムですが、以前、質問で聴覚障害をお持ちの方がプラネタリウムを利用する際に、どういった取り組みがありますかということで、今年度予算では、移動式の磁気ループみたいなものを文化センターに入れていくということで、これが使えるのかと思うのですが、あと、できれば、字幕付きのプラネタリウムにしていただいたほうが、より分かりやすいということで。","respondent":"古巻文化観光課長","answer":"これは字幕等にも対応しているのですが、プラネタリウムでどう使えるかということはありますけれども、より幅広く活用が進められるのではないかというふうに期待をしています。","voiceIndex":333,"id":"exchange-145"},{"speaker":"大倉委員","kind":"質問・要望","question":"地域資源活性化事業の補助金ですが、今のお話だと、例えば４年間支給される中で、今年、事業が新型コロナウイルス感染症によって実施ができなかった場合、例えば３年目であれば、来年も３年目の扱いで、実際には事業はやっておらず、年次も４年目になるけれども、実際の事業実施年数で見ると３年だから３年目にあたる補助金を出せるように、今、検討していただいているということでよろしいでしょうか。","respondent":"古巻文化観光課長","answer":"今、委員からご説明のあったとおりです。中止になった事業につきましては、補助金の部分については来年度に充当する、そういった形での運用を考えております。","voiceIndex":335,"id":"exchange-146"},{"speaker":"大倉委員","kind":"質問・要望","question":"分かりました。もうもらえないのだと、勘違いして、たしか６年目は、もうもらえなくなりますので、その辺はぜひ事業をしている団体のほうに周知をしていただきたいと思うので、周知の方法について教えてください。","respondent":"古巻文化観光課長","answer":"先ほども申し上げたとおり、助成の対象が、今年度、１０件です。個別周知は可能かと思いますので、漏れのないように周知を進めていきたいと思います。","voiceIndex":337,"id":"exchange-147"},{"speaker":"大倉委員","kind":"質問・要望","question":"庁舎管理費についてですが、今現在、新型コロナウイルス感染症対策の取り組みとして、手指消毒液やアクリルパネル等を使って感染拡大を防止されていると思いますが、その中でも職員もテレワークで人数を減らしたり、予約システムを入れて密にならないようにしたりしていると思いますが、今現在の取り組みを改めて教えていただきたいと思います。","respondent":"東野経理課長","answer":"そのほか、こちらにありますようないろいろなパネルですとか、手指消毒液ですとか、そういったものは総務課と連携しながら、各課に設置という形で行っているところです。例えば給付金事務にあたって、時間延長とかも見込まれております。","voiceIndex":339,"id":"exchange-148"},{"speaker":"大倉委員","kind":"質問","question":"区民が安心して区役所を利用できるような取り組み、それを目指さなければいけないのと、区民の健康をしっかり守っていくということが大事だと思うので、それで今、様々取り組みをされていると思うのですが、さらなる取り組みとして、ほかの区では、例えばサーモグラフィーによる体温測定も実施されているところがありますし、そういったサーモグラフィー等による体温測定について。","respondent":"東野経理課長","answer":"庁舎におきましては、入口がたくさんあるというような状況も踏まえまして、なかなか運用の面、管理の面で難しいところがあります。今後どういう対応ができるかにつきましては、改めて検討していきたいと考えています。","voiceIndex":341,"id":"exchange-149"},{"speaker":"大倉委員","kind":"提案","question":"もしそうした取り組みをしたときに、安心して利用できますよというような区からの広報、見せ方について提案なのですが、区民の皆様には、マスクを着けてください、手指消毒をしてくださいというお願いがされていると思うので、区でもこれだけこういう感染予防の対策をしていますので安心してくださいというようなお知らせをしていくのもいいのかと思うのですが、その辺のお考えを教えていただきたいのと。","respondent":"東野経理課長","answer":"区民へのお知らせですが、各窓口等で取り組んでいるところにつきましては、もう既に区民の目に触れているというところで、かなり周知については進んでいるかと思ってあります。","voiceIndex":343,"id":"exchange-150"},{"speaker":"大倉委員","kind":"提案","question":"エレベーターも同じく、ボタンを押す際に必ず触れるところなので、そういったところも当然消毒もされていますし、清掃もされているけれども、ちゃんと抗菌シートを貼っていますと見える化するというところでは、いいかなと思って提案をさせていただきましたので、いろいろな業者もいると思いますので、研究していただければと思います。","respondent":"東野経理課長","answer":"委員が言われた観点は、大変重要なことだと思います。区民の安全安心につきましても、十分考えた上で取り組みをしていきたいと思います。","voiceIndex":345,"id":"exchange-151"},{"speaker":"大倉委員","kind":"意見","question":"区役所はどうしても来なければいけない施設でありますので、また不特定多数の人が出入りするというところでは、より区民の方に向けて安心な場所で、安心して来てください、そういったアピールをしていただくことがいいかなと思いますので、ぜひよろしくお願いします。以上で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":347,"id":"exchange-152"},{"speaker":"若林委員","kind":"質問","question":"不用額の内容についてお聞きしたいと思います。１６９ページのイメージアップ運動経費、３８３万円余ということで、６２.６％の執行率にとどまった事業。それからもう１つ、１７９ページの職員研修費、これが１,９７３万円余の決算で、当初予算は２,６４５万円余でしたけれども、それぞれの不用額について理由をお聞きいたします。","respondent":"大澤広報広聴課長、黒田人事課長","answer":"イメージアップ運動経費の不用額ですが、デザインアドバイスの部分の件数が予定よりも減ったことが大きな要因となっています。職員研修費の主な不用額につきましては、各所管で職場派遣研修ということで有料の研修に派遣するでありますとか、講師を招いてという費用を予算計上しておりますが。","voiceIndex":349,"id":"exchange-153"},{"speaker":"若林委員","kind":"質問","question":"ちょっと話が変わりますけれども、現在のコロナ禍で、公共工事、また民間事業に関わらず、様々なところで工事が進められております。こういったときに、例えば、こういったトラブルがあった後の職員の方の住民の方に対する説明、この態度は、どのような態度を示すべきなのか、これをまず全体的ですけれどもお聞きしていきたい。","respondent":"小林施設整備課長","answer":"工事の説明に関するご質問ですので、工事を所管します施設整備課よりお答えいたします。新型コロナウイルス感染症の関係で説明会がなかなか開催できなかったという事例は、確かに委員ご指摘のとおり、１件だけございました。","voiceIndex":352,"id":"exchange-154"},{"speaker":"若林委員","kind":"質問","question":"イメージアップ運動の中で、今は公益財団ですか、実務技能検定協会のサービス接遇検定、当時は３級ですけれども、数年前、やっていますということがホームページに載っておりまして、現在これは行っていらっしゃるのでしょうか。","respondent":"大澤広報広聴課長","answer":"同じものを新人研修の中で使っておりまして、聞く姿勢ですとか、分かりやすい広報についても研修を行っているところです。","voiceIndex":354,"id":"exchange-155"},{"speaker":"若林委員","kind":"質問・要望","question":"こういうことをしっかりと心に留めて区民の方に接していく、こういうこれからのアフターコロナというか、ウィズコロナにおける職員が、苦しんでいる、ダメージを受けている区民と接するときの接し方ということについて、ちょっと話がまとまりませんけれども、思いを汲み取っていただいて、今後、区職員全体として、研修、イメージアップとかの取り組み方、これをお聞かせいただきたいと思います。","respondent":"黒田人事課長","answer":"特別区の職員研修所の主催で、コミュニケーションのスキルアップでありますとか、説明力の向上という研修があります。今ご指摘あったところは新人だけが受ければいいということではありませんので、広く検討してまいりたいと考えています。","voiceIndex":356,"id":"exchange-156"},{"speaker":"高橋（し）委員","kind":"確認","question":"８月１９日に総務委員会で報告があったと伺っています。確認を含めてお伺いします。この区の雑部金にマイナスがあって、それを埋めていったということだと思うのですが、まず、雑部金というのはどのような性格のものなのでしょうか。そしてもう１つは、今のお金の動き、処理になりますが、決算書や何らかの会計等にあらわれてくるのでしょうか。お願いします。","respondent":"中山会計管理者","answer":"４月３０日に起こりました会計事故の金銭の処理の関係についてのご質問です。区の予算にひも付いた現金と、それから、預り金のような、例えば税金ですと、都税も合わせて一緒に収入しておりますので、そういった都税の預り金とかそういうものがあります。","voiceIndex":359,"id":"exchange-157"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、決算書やほかのいろいろなところには出てこないということでよろしいですか。例月出納検査の中の雑部金という項目の中に金額としてだけ出てくるのでしょうか。ということで、雑部金以外に方法がなかったのでしょうか。雑部金を今回みたいなお金の使い方でしょうか、事故のとき、どの部署がどう判断して、この雑部金から仮払いしようというふうに決めるのでしょうか。","respondent":"中山会計管理者","answer":"このお金の処理につきましては、会計管理者の一存でできることではありませんので、区長部局とも相談をさせていただきながら、こういう処理をさせていただいたところです。","voiceIndex":361,"id":"exchange-158"},{"speaker":"高橋（し）委員","kind":"質問","question":"銀行間の振込取消を組み戻しというふうに言うと伺っていますが、みずほ銀行が振り込んだ先の銀行、そこからみずほ銀行に返金をするわけですけれども、そのときに手数料等が発生するのでしょうか。もしそうするとしたら、相手側の銀行に手数料が発生してみずほ銀行に戻すわけなので、その手数料はどこが負担するのか、それともなかったのでしょうか。","respondent":"中山会計管理者","answer":"今回は、５０７件のデータ送付で、３０４件ほどの債権者がいらしたのですが、その３０４件の中には組戻処理ではやはり対応できないという企業もございましたので、そういったところには、納付書ですとか振込ですとか、ほかのご案内をさせていただきました。","voiceIndex":363,"id":"exchange-159"},{"speaker":"高橋（し）委員","kind":"質問","question":"その２万３,７９６円は、品川区が負担したということでよろしいですか。","respondent":"中山会計管理者","answer":"すみません。それは公金手数料の中から支払わせていただいております。","voiceIndex":365,"id":"exchange-160"},{"speaker":"高橋（し）委員","kind":"質問","question":"それを品川区が相手に請求しなかった理由を簡単にお伺いします。","respondent":"中山会計管理者","answer":"もともと銀行間の組戻処理には約束事がございまして、仕向銀行は、その元の銀行が手数料を負担するということになっておりますので、最終的には指定金融機関のほうに区のほうから支払ったことになっております。","voiceIndex":367,"id":"exchange-161"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"区民の方には、現在こういうことが起きて、現在調査中だという表現でもいいので、ホームページに発表をするべきだったと思います。決算審査意見書の付帯意見のところでも、監査委員のほうから再発防止ということが求められているので、そういった観点からもこういった事故がないようによろしくお願いいたします。最後、時間がないのですが１つだけ。人口が９月にマイナスになりました。","respondent":"佐藤企画調整課長","answer":"この傾向は東京都２３区でも起きておりまして、新型コロナウイルス感染症の影響もあると思いますが、今後、推移を見ながら適正な人口の管理をやっていきたいと思います。","voiceIndex":371,"id":"exchange-162"},{"speaker":"藤原委員","kind":"質問・要望","question":"経費を伺ったら３,０００万円だというのです。最後、１９５ページ、品川文化振興事業団助成ですけれども、きゅりあんの指定管理と荏原スクエアの指定管理、こみゅにてぃぷらざ八潮の指定管理、３か所合わせると５億３,０００万円ぐらい払われているのですが、またそれ以外に品川文化振興事業団には約３億円の助成金が繰り返し払われているのですけれども、これはどういう中身の助成金なのでしょうか。","respondent":"立川総務課長、黛生活安全担当課長、大澤広報広聴課長、黒田人事課長、中山会計管理者、佐藤企画調整課長、古巻文化観光課長","answer":"基本的な考え方としましては、感染防止対策と経済社会活動の両立ということですので、一番重要なことは。その意味で、委員からもお話のございました点から線、線から面というところを着実に進めていくために、区の防犯カメラの補助制度につきまして。心理学的にも名前を知れば好感度は上がるという実験結果がありますので、効果を数値として図ることは難しいとは思いますけれども。昨年度は１６１事業所の分析を行いまして、執行額は「等」が入っているので金額が大きくなっているのですが、この経営分析自体は。","voiceIndex":375,"id":"exchange-163"},{"speaker":"藤原委員","kind":"確認","question":"防犯カメラは上のほうから品川区を網羅するという形なのですが、地上で、私は消極的なのですけれども、わんわんパトロールは、まだやっていこうと思っていらっしゃるのか確認します。やっぱりもうシティプロモーションという形でやれば結構施策が通るという考えではなくて、もう１つ１つを確認、検証していかないといけないと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"黛生活安全担当課長、中山会計管理者、大澤広報広聴課長","answer":"わんわんパトロールにつきましては、品川区は８３運動という他の区にも誇ります強力な地域の見守り活動を実施していただいているところですが。こういう経営分析があることで、逆に職員の勉強にもなっているところもありますので、引き続き、会計管理室で対応していきたいと考えております。シティプロモーションですが、ほかの施策と同じように、効果を検証しながら事業を展開していくべきだと考えておりますので。","voiceIndex":383,"id":"exchange-164"},{"speaker":"藤原委員","kind":"質問・要望","question":"わんわんパトロールは、以前、伺ったときに、バッグを変えるとおっしゃっていましたね。わんわんパトロールだけお答弁いただけますか。","respondent":"黛生活安全担当課長","answer":"これを積極的に活用してまいりたいと考えております。","voiceIndex":387,"id":"exchange-165"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、１７８ページの庁舎等管理費で、庁舎の建て替えについて伺いたいと思います。ですので、やはり不要不急の事業を見直して、コロナ対策の財源に充てていくべきと私たち共産党はずっと求めているわけですけれども、そうした中、庁舎建て替えの計画は進んでいるわけですけれども、現庁舎は、あと１６年耐用年数があります。","respondent":"濱中庁舎計画担当課長","answer":"新庁舎の建設費用に関するご質問に対してお答えしたいと考えています。建設費用につきましては、建物の規模や導入する機能により変動いたします。費用や財源につきましては、今後の検討項目です。","voiceIndex":390,"id":"exchange-166"},{"speaker":"石田（ち）委員","kind":"質問","question":"今年度は、庁舎の機能検討をして、そして来年度、令和３年度は、基本構想、そして令和４年度は基本設計というふうに進んでいくわけですけれども、おおよその見込みはあるのではないかと思うのです。そういうものを考えるのは当然ではないかと思うのですけれども、そういった大枠でも決まっていないということでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"引き続き新庁舎の概算費用についてのご質問かと思いますが、概算につきましても、今、機能と規模を検討している段階ですので、これぐらいといったものはお示しできないところです。","voiceIndex":392,"id":"exchange-167"},{"speaker":"石田（ち）委員","kind":"質問","question":"大枠というか、概算も今はないと、それなしで、基本設計まであと２年です。それで、今、建設費がまだ決まっていないという状況なのであれば、コロナ禍ですから、一旦、今、止めていくべきではないかと思うのです。現庁舎は、あと１６年使えるわけですから、まずはコロナ禍で苦しむ事業者の営業と区民の暮らしを守ることに使っていく、収束してから考えても遅くないと思いますけれども、いかがでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"建物本体の設備も老朽化が進んでおります。区を取り巻く環境も変わっていく、また行政需要も変わっていく、そうした中で変わっていく需要等に対して対応できる区役所を検討していくことが必要であるかと考えています。","voiceIndex":394,"id":"exchange-168"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうは言っても、１６年もつというふうに議会の中でも答弁があるわけです。環境も変わっていく。正に今、コロナ禍で環境が変わっている状況ですので、立ち止まって考えていくという必要があると思いますし、不要不急の事業を見直していく、そしてコロナ対策の財源に充てていくということが必要なのではないかと思うのですけれども、いかがでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"耐用年数ですが、免震や耐震の工事といったものは進めてきましたが、建物自体の老朽化や設備の老朽化が進んでおります。そうしたものに対応していくため、防災拠点としても、行政の拠点としても、新庁舎の整備計画は着実に進めていく必要があると認識しております。","voiceIndex":396,"id":"exchange-169"},{"speaker":"石田（ち）委員","kind":"質問","question":"区民のための庁舎ですから、その庁舎の建設費は、まず区民の暮らし、そして営業を守るということに使っていくべきだと改めて述べたいと思います。それで、やっぱり区がこの計画を急ぐ理由は、広町の開発と一体だからですよね。なので、そうした広町の開発と切り離して区の新庁舎の建設を考えるべきと思いますけれども、いかがでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"広町地区のまちづくりとの関連性についてお答えしたいと思います。広町地区のまちづくりは、都市環境部のほうでしっかりと進めていきますので、そうした意味では、広町地区とのまちづくりの連携は必要かと考えています。","voiceIndex":398,"id":"exchange-170"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それが開発と一体なので区はこの機を逃すなということで進めているわけですから、１６年もつ庁舎を一旦立ち止まって考え直しても、しっかりと時間はありますので、開発と切り離して考えていただきたいと強く求めたいと思います。そのにぎわいゾーンのところにはアリーナ等ということも示されていますけれども、このアリーナ等は、どの部署で検討されることになるのか伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"にぎわいゾーンということで、大井町エリアのにぎわいを向上させるような多目的な施設ということで検討を進めておりますが、具体的には未定です。どこの部署で検討していくかということにつきましても、現段階では検討段階です。","voiceIndex":400,"id":"exchange-171"},{"speaker":"石田（ち）委員","kind":"質問","question":"来年が基本構想に入るわけですので、そうした現庁舎の跡地、区有地をどうしていくかということも一体に考えていくべきだと思うので、そこはもう今、考えがあってもいいのではないかと思うのですけれども、区有地なので、区有地の跡地活用ということになってくるのか、広町のまちづくりと連携してというふうにおっしゃっていますので、そうした開発と一体した検討になってくるのか。","respondent":"佐藤企画調整課長","answer":"令和２年９月２３日の建設委員会でもご説明していますが、広町地区におけるまちづくりの検討状況というところで、ＪＲ広町社宅跡地および区有地から成る広町地区のまちづくりについては、ＪＲ東日本と平成３０年７月に協定を締結し検討を重ねているというところです。","voiceIndex":402,"id":"exchange-172"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、この現庁舎跡地もＪＲとの協定という部分に入ってくるのでしょうか。要は、どういう方向性で検討されるのか、検討中なのは分かるのですけれども、方向性を知りたいのです。なので、まちづくりとの関連ということで、ＪＲとの協定というところに現庁舎跡地も入っているということでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"現庁舎の跡地活用につきましては、都市環境部のほうでＪＲ東日本との協議を進めておりまして、東側のほうに都市機能を集積していく、また、現庁舎がある西側は行政機能や防災機能を集約していく、また、にぎわいといったものを創出していくというところで計画を進めておりまして。","voiceIndex":404,"id":"exchange-173"},{"speaker":"石田（ち）委員","kind":"質問","question":"現庁舎の跡地活用も、ＪＲとの協定における検討項目の中に入っているのかということを伺ったのですが、もう一度お願いします。","respondent":"濱中庁舎計画担当課長、あくつ委員長","answer":"ＪＲとの協定に関するご質問がありましたが、都市環境部のほうでしっかりと進めていっているということで、オフィシャルの回答は控えさせていただければと考えています。所管が違うというところで、ぎりぎりのところでお答えいただいていると思うので、そこら辺は配慮してください。","voiceIndex":406,"id":"exchange-174"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"いずれにしても現庁舎はあと１６年使えるわけです。区民が望んでいながら足りていない、先ほどもありましたけれども、そうした施設を建設していくべきだと私は思います。障害者施設、高齢者施設、子育て支援施設、そして公営住宅等々、区民が求めていながら足りな過ぎる施設がたくさんこの品川にはあるのです。ですので、そうしたものにしっかりと使っていただきたいと思いますけれども、いかがでしょうか。","respondent":"濱中庁舎計画担当課長","answer":"庁内の検討や他自治体の先進事例、そして庁舎機能検討委員会のお声をしっかりと聞きながら、新庁舎整備計画を着実に進めていきたいと考えています。","voiceIndex":409,"id":"exchange-175"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"広く区民の声を聞いていただきたいのですけれども、今、庁舎機能検討委員会をやられて公募区民も入っていますけれども、さらに広くアンケートをとっていただきたいと思うのですけれども、そうした場面は、もしやろうとするならいつぐらいにできるのか、やる考えはあるのか伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"そうした手法をまず研究いたしまして、また、何もないところで皆様から意見を賜るのもなかなか難しいかと思いますので、庁舎機能のまとめができた段階ですとか、そういったたたき台ができた段階で。","voiceIndex":411,"id":"exchange-176"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"何を聞いても、検討、検討ということで、今の段階ではっきりしたことが分からない状況ですけれども、庁舎建設は開発と切り離して、そして住民参加、情報公開を徹底して進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":413,"id":"exchange-177"},{"speaker":"たけうち委員","kind":"質問","question":"１７９ページの食堂厨房機器購入等、それから働き方改革推進事業をお伺いします。食堂厨房機器購入等ですけれども、どのような内容かということと、それから、今、新型コロナウイルス感染症の影響で食堂の利用状況がどうなっているか。","respondent":"黒田人事課長","answer":"働き方改革推進事業の中で、今年度、コロナ禍において対応しているところにつきましては、通勤時間をずらすことによって感染防止に努めるということで、シフト勤務の活用をして、そのような対応で職員の感染防止に努めているところです。","voiceIndex":415,"id":"exchange-178"},{"speaker":"たけうち委員","kind":"質問","question":"食堂については分かりました。働き方改革につきましても分かったのですが、お聞きしたいのが、両方に関連してくるのですが、例えば今、職員の方のお昼休みの時間帯のとり方、戸籍住民課みたいな窓口は、交代でとるのでしょうけれども、そうではない内勤でやっていらっしゃる区民と対応されていない方のお昼休みの時間設定は、今、どのようにされているのでしょうか。","respondent":"黒田人事課長","answer":"この場合は、一律に時間をずらすことも考えられますが、職場の状況に応じて適宜休憩時間を分散化してとるようにということで人事課から通知も出しておりますので、職場の窓口の混雑状況等に応じて分散して適宜昼休みをとるような状況になってあります。","voiceIndex":417,"id":"exchange-179"},{"speaker":"たけうち委員","kind":"質問","question":"食堂もしかりなのですけれども、そう考えると、分からないですけれども、例えば、今、働き方改革ですけれども、お昼休みの時間帯は、ある意味、戦略的に区のほうでずらしていく、無理せずできる方はですけれども、そうすると、職員の方もある程度ゆっくりできる、また近隣にもいい影響が出るのかなと思うのですけれども、考え方としてはいかがでしょうか。","respondent":"黒田人事課長","answer":"今ご指摘いただいたとおり、できる限り休憩を分散化してとるようにということで通知はしているところなのですが、ただ、戦略的にというところまではいってございませんで、今後もコロナ対策も含めて分散するような形が進められるどうかについては。","voiceIndex":419,"id":"exchange-180"},{"speaker":"たけうち委員","kind":"質問","question":"それでまたお弁当も、多分区役所のそれぞれの部署の方とかが有志でお弁当を、いろいろな業者からとっていらっしゃるのだと思うのです。そこについてどうのこうのというのではないのですが、食堂もやっているぐらいですから、コロナ禍で非常に厳しいときに、区内の飲食店の方がお弁当配達をやり出しているところもあるかと思うのです。","respondent":"黒田人事課長","answer":"ただいまご指摘ありましたとおり、商業・ものづくり課のほうで商店街の中の飲食店のお弁当について、庁内でコロナ禍の対策ということで、案内があって注文するというような取り組みもありましたので、そこのところについても。","voiceIndex":421,"id":"exchange-181"},{"speaker":"たけうち委員","kind":"質問","question":"時間があるので、さっきちょっと聞き漏らしたというか、食堂で令和元年度にやった中で、違っていたら言ってください、今まで大人数で相席になっていたところを、１人で来た職員なり区民の方が、相席だと嫌だと言って帰ってしまうので１人用の単独席もつくろうという、何かそのような改修もされたように書類を見るとなっているのですけれども、これは新型コロナウイルス感染症の前の対応だったのですが。","respondent":"黒田人事課長","answer":"今年度はコロナ対策としまして、中にあるテーブルの真ん中に衝立を立てまして、向かい合って食事をするときに飛沫の防止ということで対応をとっているです。","voiceIndex":423,"id":"exchange-182"},{"speaker":"たけうち委員","kind":"意見","question":"これから新しい庁舎の計画が行なわれる中で、今、食堂をどうするかというのは、まだこれから検討されてくるかと思いますが、またそうした様々なことも踏まえて、ぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":425,"id":"exchange-183"},{"speaker":"大沢委員","kind":"質問・要望","question":"お願いします。１８５ページ、町会について、そして１９３ページ、観光について、２点聞かせていただきますが、まず、１９３ページの観光のほうからお尋ねさせていただきたいと思います。都市型観光ということで、もう既に皆さん、十分に都市型観光とは何ぞやということで認識しているとは思うのですけれども、まず都市型観光について改めてどのようなものか聞かせてください。","respondent":"古巻文化観光課長","answer":"「都市型観光」という言葉ですけれども、都市型観光プランを策定していますが、品川区におけます観光の考え方としまして、商店街であったりとか、そういった部分を使って観光事業を推進していく、都市の特性を生かした観光事業ということで。","voiceIndex":427,"id":"exchange-184"},{"speaker":"大沢委員","kind":"意見","question":"今、商店街を生かしたとか、あとグルメ、食もあるでしょうし、商店街のみならず、いろいろな部分があるとは思うのですけれども、今、あえて課長が「商店街」というふうな文言を出していただいたのでお尋ねしますけれども、都市型観光、これはあくまでも日本人であったり、外国の方であったりということで、主に区の仕掛けとしては、インバウンドを対象にこの事業をしていると思います。","respondent":"古巻文化観光課長","answer":"外国人の来訪者数は、なかなか数えづらいものがあって、東京都全体でというような数字は幾つか目にしたことはあるのですけれども、品川区固有のそういった数字はとっていないものですから、今後、そういった部分を含めて統計調査等はしていきたいと考えておりますけれども。","voiceIndex":429,"id":"exchange-185"},{"speaker":"大沢委員","kind":"意見","question":"そうなると、やはり事業として、もう１回考えて工夫を１つ２つ行う必要があるとは思うのですけれども、どういうふうにお考えになりますか。","respondent":"古巻文化観光課長","answer":"品川区におきましても、近隣の方、地域の方がより身近な商店街に来訪したりとか、また、区内におきましても、西部のほうから東の水辺のほうへいらしたりとか、区内の往来も観光の１つの目的ということで。","voiceIndex":431,"id":"exchange-186"},{"speaker":"大沢委員","kind":"意見","question":"そこで、さっきお話しした名だたる観光地はコロナ禍で大きな影響を受けておりまして、やはり観光というのは水物なところがあるわけでありますが、内需ということで、今、課長からお話をいただいた。その観光という考え方というよりも、むしろ散歩という切り口で観光施策を進めていったらいかがかと思うのですけれども、どのようにお考えになりますか。","respondent":"古巻文化観光課長","answer":"今、委員からご指摘のあった「散歩」という表現なのかどうかはありますけれども、区内の方が区内を訪れる、もしくは近隣の方が品川区を訪れていただくような、そのような身近な場所としての品川区の魅力を発信していく。","voiceIndex":433,"id":"exchange-187"},{"speaker":"大沢委員","kind":"質問","question":"９月に東京国際クルーズターミナルができました。ここに大型クルーズ船が入ってくるとなると、それこそ先ほどのインバウンドではないですけれども、場所が比較的近いわけですから、外国のお客さんもどんどん増えていくと思うのですけれども、それに対しての戦略についてどういうふうにお考えになっているか教えてください。","respondent":"古巻文化観光課長","answer":"国際クルーズターミナルに関しましては、本来ですと、オリンピック期間中、例えばクルーズターミナルのほうから区内といいましょうか、天王洲を結ぶ舟運を予定していたりとか。","voiceIndex":435,"id":"exchange-188"},{"speaker":"大沢委員","kind":"質問・要望","question":"ぜひとも外からの、労せずして回遊というか、観光客が来るわけですから、そこのところは大きく捉えていただいて、何かの仕掛けをぜひともしていただきたいと考えています。これについては終わります。町会・自治会についてですけれども、町会というのは、そもそも行政組織なのでしょうか。それとも自治組織なのでしょうか。どのようにお考えか、地域活動課長の見解をお伺いいたします。","respondent":"川島地域活動課長","answer":"町会につきましては、法律的な根拠を持たない任意の地縁組織であるというふうになってあります。","voiceIndex":437,"id":"exchange-189"},{"speaker":"大沢委員","kind":"意見","question":"令和の町会を考えた場合に、イメージアップはしているのは分かるのですけれども、やっぱり平成から令和に変わったので、さらに脱皮をしながら町会のイメージをかもし出すような取り組みが必要だと思うのですけれども、どういうふうにお考えになりますか。","respondent":"川島地域活動課長","answer":"今、大きな問題で言うと、実際の町会・自治会のほうで、そういったものの担い手の方がなかなかいないというようなところで、実際は区で支援をしましても、それは維持管理ですとか、更新だとかというようなところができないということをよく聞くところですので。","voiceIndex":439,"id":"exchange-190"},{"speaker":"石田（秀）委員","kind":"提案","question":"私は、依命通達が出された中の１６５ページ、長期基本計画策定経費に基づいた部分と、１８５ページ、クラウドファンディング活用支援、それから、今、話が出ましたけれども、１８３ページ、それから１８５ページ、地域コミュニティの活性化ということで、町会については、私は地域コミュニティの中心的な役割を担っていると考えていますので、それについて２点ほど、お話を伺いたいと思います。","respondent":"黒田人事課長、川島地域活動課長","answer":"研修では、平成２８年度から、主任昇任者を対象に、グループごとに課題解決のために自分たちで施策を検討し、所管する課長などにプレゼンテーションした後に。そちらの活用をしながら、町会活動がどれだけ区にとって寄与しているかというところも訴えるところも必要ですので、今後、地域センターの所長と連携しながら対応していきたいと考えています。","voiceIndex":442,"id":"exchange-191"},{"speaker":"石田（秀）委員","kind":"意見","question":"私がたくさんしゃべってしまったのですけれども、言いたいことはたくさんありますが、また改めて言います。ただ、政策形成研修は、こうやってどうやっていこうというぐらいは私も分かっているけれども、現実に何かやったかというとなかなかやっていない。終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":445,"id":"exchange-192"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1486#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":117087,"voices":446}},{"id":"r02-20201006-4","meetingId":"r02-c-settlement","date":"2020年10月6日","dateIso":"2020-10-06","committee":"決算特別委員会","time":"午前１０時００分～午後 ６時０５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を178件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"芹澤委員","kind":"質問・要望","question":"私からは、２２１ページ、品川介護福祉専門学校運営助成、２４７ページ、ひとり親家庭支援事業、２２９ページ、障害者の就労移行支援等の項目で、順不同でお伺いしていきます。我々の会派からも、養育費不払いの問題について、何とか品川区で解消できないかというような要望も出していますけれど、今の品川区の養育費の保証などの考え方について、まずお聞かせください。","respondent":"三ッ橋子育て応援課長","answer":"区といたしましては、やはり養育費は生活費にも密着しているという部分を大きく思っておりますので、様々検討していきたいと考えています。","voiceIndex":6,"id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問","question":"前向きなお答えだと考えています。ただ、やはり予算の中では回数や量に限りが出てくる中で、ある意味、本来もらわれるべき養育費の保証をしていくというのは、ひとり親家庭の方々からすれば非常に大きな支えになるのかなと思っていますので、積極的に取り組んでいただければと思います。続いて、障害者の就労移行支援等についてお伺いいたします。","respondent":"松山障害者福祉課長","answer":"テレワークにつきましては、やはり障害特性等々、個人の特性により、非常に適している面があります。新たな生活様式あるいは働き方改革、世の中の流れを踏まえまして、今後、テレワーク等の研究をしてまいります。","voiceIndex":8,"id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問","question":"それで、コロナ禍の中でテレワーク支援というものを区も進めてまいりましたけれども、大変好評だったと伺っております。それで、今後の方向性の話になりますが、障害者雇用と例えばテレワーク。今お話しいただいたように、障害者の方々にも様々な障害がありますけれど、障害者雇用とテレワークというものを合体させた支援策というのもご検討いただければと思いますが、ご見解をお聞かせください。","respondent":"松山障害者福祉課長","answer":"様々な工夫がされております。そういった中で、知見や経験を積み重ねて、就労移行支援事業所の連絡会がありますので、その中で皆さんで論議をしながら、よりよい支援という形で積み重ねていければと考えています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"最後に品川介護福祉専門学校についてお伺いいたします。昨年度になりますけれども、予算特別委員会だったと思いますけれど、介護福祉専門学校の募集がなかなか定数に満たないという中で、私から外国人材の活用について、石田秀男委員からは営業職を雇ったほうがいいのではないかというようなお話をさせていただきました。その検討状況に進捗があればお聞かせください。","respondent":"宮尾高齢者福祉課長","answer":"一方で、委員からご提案のありました外国人材、それから営業職の導入につきましては、結論から申し上げますと、まだ実現には至っていないですが、これからも様々なＰＲを施策の一環として、導入に向けて検討を進めてまいりたいです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問","question":"少し厳しいお話をすれば、４０人の定数だったと理解していますので、その中で半分に満たないというのは、なかなか、しかもそのような状況が続いているので、少し危機感を持って大きな改革をしていく必要があるのかなと思っています。引き続き伺っていきますけれど、コロナ禍の中で、各学校は休校したわけでありますけれど、介護福祉専門学校に関しては、どのような対応を取られたのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"一方で、授業の質はしっかりと確保する必要がありますので、オンライン授業を取り入れたり、あるいは通常だったら２学年一緒にやっていた授業を、カリキュラムを工夫することによって、学年を別々にして行うといった工夫をさせていただきながら、通常のやり方を変えながら。","voiceIndex":14,"id":"exchange-005"},{"speaker":"芹澤委員","kind":"意見","question":"今、厳しいお話もさせていただきましたけれども、事業者は大変、介護福祉専門学校の卒業生に対して、本当に喉から手が出るほどいい人材だというのも理解していますので、引き続きぜひ前向きに取り組んでいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-006"},{"speaker":"せお委員","kind":"質問","question":"２６１ページ、私立幼稚園費、次に２３５ページ、戸越ルーム、あと障害者訓練センター運営費についてお聞きします。は私立幼稚園費です。決算にあります私立幼稚園協会補助金、私立幼稚園振興費等補助金などは、品川区独自の補助金だと認識しております。はこれらの補助金が出されるようになった経緯といいますか、目的も含めて教えてください。","respondent":"若生保育支援課長","answer":"私立幼稚園振興費等の補助ですけれども、こちらにつきましても、運営において必要とする経費の一部を助成することにより、幼稚園の経営の安定と、保護者にかかる経費の負担軽減を図るといったことを目的として、これは、経緯としましては、昭和４０年から実施しているものです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"せお委員","kind":"意見","question":"背景として、私立幼稚園は財政状況が少し厳しくて人材が足りないという状況がありますが、一方で３歳から幼稚園に通わせたいという保護者の思いがあることも理解しています。ただ、特別な配慮が必要なお子さんを、入園時に定員割れしているのにお断りしたり、在園しているお子さんでも途中で障害などが判明したら退園するように促したりということが度々起きています。","respondent":"若生保育支援課長","answer":"私立幼稚園経費のうちの心身障害児教育事業費補助金のお尋ねですが、まずこちらの申請方法につきましては、私立幼稚園各園の中で、障害をお持ちのお子様の入園を受け入れた場合に、この補助金の様式、区の様式をこちらにご提出いただいて、それに基づいて区が審査を行いまして。","voiceIndex":20,"id":"exchange-008"},{"speaker":"せお委員","kind":"質問・要望","question":"この心身障害児教育事業費補助金なのですが、合理的配慮のできる金額を検討していただきたいと思っていますが、現状、障害児１人を受入れると、どの程度の補助が必要なのかなどの調査をした上での試算というのは出ていますでしょうか。先ほど８園とご答弁がありましたが、心身障害児教育事業費補助金があることを幼稚園はご存じなのでしょうか。","respondent":"若生保育支援課長","answer":"そういったところで、区独自で障害児の費用が幾らかかるのかというところの調査は特段行っていないところではありますけれども、そういった都の補助も合わせた上で、適正なというか、こちらでも補助を上乗せして行っているということで。","voiceIndex":22,"id":"exchange-009"},{"speaker":"せお委員","kind":"質問","question":"私立幼稚園はそれができる場所だと思っています。やはり前提として、品川区民の大切なお金を園にお渡ししているのであれば、品川区のどのお子さんも入園できる、退園させられない私立幼稚園であってほしいです。そこで、品川区が私立幼稚園を定期的に状況調査し、もしも不適切なことがあれば助言・指導などをするといった対策を取るべきかと考えますが、見解を伺います。","respondent":"若生保育支援課長","answer":"もしそういった不適切な事例があった場合には、当然、区でも指導してまいりますけれども、現状そういった事例は見られていないところです。","voiceIndex":24,"id":"exchange-010"},{"speaker":"せお委員","kind":"質問","question":"幼稚園を退園させられた保護者には、自分たちのことは言わないでほしいという方もいらっしゃいます。次に移ります。２３５ページ、戸越ルームです。そこで質問なのですが、設計に関してです。どのようなレイアウトといいますか、部屋の配置なのでしょうか。そして、インクルーシブな環境で一緒に遊べる場というのは、具体的にはどのような場所なのでしょうか。お聞かせください。","respondent":"松山障害者福祉課長","answer":"レイアウトについてですけれども、今のレイアウトを大幅に変更するということではなく、内装を工夫しながら、医療的ケアが必要なお子さんに対応できるようバリアフリー化をする予定です。","voiceIndex":26,"id":"exchange-011"},{"speaker":"せお委員","kind":"質問","question":"部屋の配置をお聞きしたのは、医療的ケア児の保護者はレスパイトの機会がほとんどないということです。事業概要の２番目に親子の交流とあります。私もそうで、息子がもう６歳になりますが、そうなった今でも、同じ境遇の方々と同じ時間を共有するということは、気持ちが落ち着いて、またこれからも頑張ろうと思える大切な時間です。子どもが幾つになっても、ライフステージによって、不安や悩みは変わります。","respondent":"松山障害者福祉課長","answer":"レスパイトおよび在宅支援についてのご質問ですが、レスパイトにつきましては、現在の戸越ルームが適切なのか、あるいは場所の確保等は別にしたほうがいいのか等々、様々な方法はありますけれども。","voiceIndex":28,"id":"exchange-012"},{"speaker":"せお委員","kind":"質問・要望","question":"今回の戸越ルームの活用は本当に喜ばしいことですので、ニーズに応えられる内容をぎりぎりまで検討していただきたいと要望いたします。そこでお聞きしますが、近藤先生が掲げる超短時間雇用というモデルを導入して、障害者雇用の促進に力を入れていただきたいのですが、障害者雇用の今後について品川区の見解を伺います。まだこのモデルが導入されない理由もお聞かせください。","respondent":"松山障害者福祉課長","answer":"委員ご提案のとおり、働きたいけれども長時間働けないという障害者の特性や状況によって、就労の機会がつくれない方がいらっしゃいます。そのため、超短時間雇用というのは、障害者雇用を突破する大きな手法の一つであると認識はしております。","voiceIndex":30,"id":"exchange-013"},{"speaker":"せお委員","kind":"意見","question":"日本で初めてこのモデルを導入した川崎市ですが、先ほどもご答弁がありましたが、まず市内に就労援助センターが３か所あって、そちらに所属している障害者の方を紹介したり情報提供したりする。もし品川区で超短時間雇用というモデルを導入するとしたら、このようなシステムがスムーズにいくかと思うのですが、このシステムについて品川区ではどのように考えているか、お聞かせください。","respondent":"松山障害者福祉課長","answer":"今、近藤先生に相談をしながら、ご助言を頂きまして、障害者就労全般について研究をしている段階です。今後、連携が図れるところがあれば、ぜひ積極的に図っていきたいと考えています。","voiceIndex":32,"id":"exchange-014"},{"speaker":"せお委員","kind":"質問・要望","question":"川崎市を見に行かれたということで、ぜひ参考にしていただいて進めていただきたいと思っています。さらに、超短時間雇用を進めていくにあたって、障害の当事者やご家族のニーズというのは把握されていますでしょうか。障害がない方、特に雇用する企業側へ、多様な人と共に過ごすということへの普及啓発といったものはどのように行っていくのか、その２点についてお聞かせください。","respondent":"松山障害者福祉課長","answer":"企業に対しましては、現段階では、障害者就労支援センターのげんき品川が、複数の企業と連絡会を持ち、周知を行っている段階ですが、まだ区内全体のシステムというところにまではなっておりませんので、今後とも連携先というものを、区側でも、区の内外を問わず増やしていって。","voiceIndex":34,"id":"exchange-015"},{"speaker":"新妻委員","kind":"質問","question":"２６１ページ、オアシスルーム・ポップンルームの運営、２１７ページ、成年後見センター運営助成ということで伺ってまいります。在宅子育て支援ということで伺います。コロナ禍の影響で、誰もが先行きの見えない不安、そして仕事・収入の減の中で生活への不安を抱えている中で、どういう方にとっても生活と離れたところで息抜きをする居場所というのは大事だと思います。子育て支援の取組みが大変に重要です。","respondent":"廣田子ども育成課長","answer":"現在、地域の活動と行政がよい距離感でどう取り組めるか、また区としてどういう後方支援が必要かということを考えていきたいと思っておりまして、まず手始めといたしましては、現在、子育て支援をしている方々のお声を聞きまして。","voiceIndex":37,"id":"exchange-016"},{"speaker":"新妻委員","kind":"質問・要望","question":"続きまして、オアシスルームについて伺います。オアシスルーム、度重ねて、地域、品川区全体への展開を求めてまいりました。八潮・勝島地域への設置を求め続けておりますが、なかなか実現いたしません。勝島地域は若い世代が本当に多いです。併せて、これまで利用率や安全性に課題がありました、ものづくり創造センター内のオアシスルームの利用状況をお知らせいただきたいと思います。","respondent":"若生保育支援課長","answer":"ただ、これは全く候補がないわけではなく、具体的に検討は進めているところです。現時点では、なかなかこちらのオアシスルームについて開設するというところの具体的なお話ができるものではございませんけれども、引き続き検討を進めていきたいと考えています。","voiceIndex":39,"id":"exchange-017"},{"speaker":"新妻委員","kind":"確認","question":"分かりました。引き続き取組みをお願いいたします。ものづくり創造センター内のオアシスルームの状況も確認できました。続いて、成年後見センター運営助成から、現在こちらで行っていただいております任意後見制度「あんしんの３点セット」の利用状況を伺いたいと思います。いつから始まって、これまでの延べ利用数をそれぞれお伺いしたいと思います。","respondent":"寺嶋福祉計画課長","answer":"社会福祉協議会が実施しております「あんしんの３点セット」、任意後見契約の件ですが、開始は成年後見センターの開設当初からということで、平成１４年からの開始になっております。","voiceIndex":41,"id":"exchange-018"},{"speaker":"新妻委員","kind":"質問","question":"それぞれのサービスの中で、任意後見契約、あんしんサービス契約、公正証書遺言作成支援とありますが、これはそれぞれで契約ができるのか、もしそれぞれの契約ができるのであれば詳細も教えていただければと思います。","respondent":"寺嶋福祉計画課長","answer":"基本的に３点セットということなので、３つセットで契約ということになりますけれども、例えば公正証書遺言の作成等につきましては、時期等々もございまして、契約後すぐに作るものでもないということなので、その部分につきまして、公正証書遺言を作成した方は。","voiceIndex":43,"id":"exchange-019"},{"speaker":"新妻委員","kind":"質問・要望","question":"分かりました。最近、ご相談の中で立て続けに、孤独死に関わることや、死んだ後のお墓のことなどでご相談を受けました。今回の「あんしんの３点セット」、平成１４年からということです。民生委員をはじめ、また社会福祉協議会も、年１回のエンディングノート等の作成の研修も進めていると言われておりますが、今後何かもう少し知らせていけるためのことがありましたらお知らせいただきたいと思います。","respondent":"寺嶋福祉計画課長","answer":"今、来年度に向けて、成年後見制度の利用促進計画というものの作成が始まるところです。その中で、ＰＲにつきましてもしっかりと検討を進めていきたいと考えております。","voiceIndex":45,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"２４３ページ、奨学金貸付事業、後半は待機児童対策について伺います。自ら貸与型の奨学金を借りて学んでいる区内在住の大学生の方から、区の給付型奨学金を大学生まで広げてほしいという請願が署名つきで出されまして、先の文教委員会で審査が行われました。歳入のときに、のだて委員も質問したのですけれども、引き続き、大学生の給付型奨学金実施に踏み出すよう求めて質問したいと思います。伺います。","respondent":"三ッ橋子育て応援課長","answer":"これを踏まえて、品川区といたしましては、昭和３５年から実施しております奨学金制度について、平成３０年度から返還免除制度を実施しております。返還免除というものを実施したというのが、区として本当に大きな試みでございました。","voiceIndex":48,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"要するに、高校生への給付制度を始めたばかりだからということだと思うのですけれど、どうしてそれで、まさに今困っている大学生が待たなくてはいけないのか。高校生と大学生を対立させる必要はないと思います。高校生にやっていることが、なぜ大学生にやらない理由になるのか、伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"大学生までにさらに拡大するためには、非常に多くの検証が必要となっております。今、この高校生の返還免除制度に関して検証している段階であり、大学生までの拡大は、現在のところ実施いたすことは考えておりません。","voiceIndex":50,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"品川区は１５人ですから桁が違うのです。文教委員会でも、先ほどの決算特別委員会でも、区は、大学まで拡大しない理由について、国がもう始めていますとか、あるいは平成３０年度から大きな改革に踏み出したばかりで日も経っていないので検証が必要だと言いますけれど、伺いますが、国の制度があるから区の支援が必要ないとどうして言えるのでしょうか。伺いたいと思います。なぜやらないのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"委員ご紹介のように、大学生を対象としました奨学金制度ですが、国が授業料減免や奨学金拡大を行う高等教育無償化法案を閣議決定しておりますし、東京都や大学をはじめ、様々な事業者が奨学金制度を設けておりますので。","voiceIndex":52,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"非常に機械的な答弁だと私は思います。先ほど紹介しましたように、検証と言うのだったら、区内の学生がどういう状況にあるということはもちろんつかんでいただきたいですし、今紹介したような制度で、品川区内の学生がきちんと救済されるのか、支援が受けられるのかということをきちんとつかむことが必要だと思います。ぜひその検証が必要だと思いますが、いかがでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"先ほど申し上げましたように、高校生の返還免除制度、平成３０年度から実施しておりますものを、まずは検証してまいります。","voiceIndex":54,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほど私が紹介しましたような検証も含めてやっていただきたい。ぜひ早急に、検証ももちろん必要ですが、給付型奨学金を大学生まで拡大するよう求めて次の質問に移りたいと思います。１つだけ伺いたいのですが、「求職活動を休止している者」。これは具体的にどういう定義なのでしょうか。これを国が待機児童に含めないとして品川区も同調していることに合理性はあるのでしょうか。伺いたいと思います。","respondent":"立木保育課長","answer":"ハローワークに通っている等の書類になりますが、こちらのご提出を頂けなかった方、また４月入園は申込みをされましたが５月以降の申込みをされなかった方ということで定義されているものです。こちらは国が定義しているものです。","voiceIndex":56,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいと思いますけれど、さきの「求職活動を休止している者」９２人も加えて、これらの合計は４６７人になるのです。少なくともこれらは待機児童として捉えるべきではないでしょうか。いかがでしょうか。１点目です。２点目は、毎年の文教委員会で、待機児童等が報告されているのですが、不承諾数と待機児童数だけでなく、こういう内訳についても発表することを求めますけれども、いかがでしょうか。","respondent":"若生保育支援課長、立木保育課長","answer":"不承諾数から、待機児童から除く数については、国の基準に基づいて適正に算出しているものです。数値が独り歩きしますと混乱するというところもありますので、区としては、より分かりやすく、利用調整基準や入園内定者の最下指数を公表しておりまして、そちらのほうが利用者にとりまして有用だという形で公表しています。","voiceIndex":58,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"私からは、２１９ページ、認知症高齢者支援事業と、２６７ページ、生活困窮者自立支援事業、暮らし・しごと応援センターについて、２６５ページ、生活保護費についてお伺いいたします。そうしたことで高齢者が認知症になる、症状が悪化するといった研究成果や専門医の見解が示されております。既に認知症の方の症状が悪化したということは増えているのか。状況とご認識を教えてください。","respondent":"宮尾高齢者福祉課長","answer":"それにつきましては、これまで以上にきめ細かなサービス提供、例えばケアマネジャーによるサービス提供といったものがより重要になってこようかです。","voiceIndex":62,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。今のところ横ばいか、やや増えているかぐらいの認識だということですけれども、やはりこれから新型コロナウイルスの感染拡大が長引くと、微増がもう少し増えていくのかと。今、認知症ではない人がなってしまう可能性もありますので、今、幾つか対策のようなことをおっしゃられましたけれども、そうした認知症患者の増加や悪化を防ぐ対策というのは、具体的に今何かお考えなのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"残念ながら、コロナ禍前のやり方がなかなか難しいというものにつきましては、例えば直接、対面によらずにできることはないかですとか、あるいは開催のやり方を工夫することによって、少しでも新型コロナウイルス感染症の影響を。","voiceIndex":64,"id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"暮らし・しごと応援センターについてお伺いいたしますけれども、これまで国や都、品川区では、雇用の維持・確保の重要な受皿として、持続化給付金や雇用調整助成金、貸付融資などで、企業や事業者向けの支援を行ってきたかと思います。現時点で既にご相談者が増えてきていると伺っておりますが、現在の対応状況をお聞かせください。","respondent":"櫻木生活福祉課長","answer":"暮らし・しごと応援センターの状況です。今年度、令和２年４月から８月においては、住居確保給付金を中心とする相談が６,２３５件です。前年度につきましては、おおむね３,０００件程度だです。","voiceIndex":66,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"もう既に、現時点で前年度の倍あたりになっているということだと思うのですけれども、非常にすごいスピード、ペースで増えているということです。８月時点での完全失業率は３.０％、有効求人倍率は１.０４倍であり、再就職先が見つからない、働きたくても働き先がない、雇用の受皿がないという状況ですが、そうした状況の中、どのような支援を行っていくおつもりでしょうか。２点お伺いします。","respondent":"櫻木生活福祉課長","answer":"今後の支援という点につきましては、これまでの相談等で経験を蓄積しているところと、あとは相談体制を、対応できる相談員数を増やしていくということで、仮に急増した場合においても十分なご相談に応じられるような体制を取ってまいりたいと考えています。","voiceIndex":68,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。続いて生活保護費に移りますけれども、今後、どうしてもそうした就労支援も成果が出ず、生活保護を受けられる方が増えてくるのかと考えておりますけれども、この生活保護は外国人の方も受給しているかと思いますけれども、その人数と国籍別の内訳を教えてください。受給できる外国人は誰でもよいのか、もしくは在住者や永住者など特別な資格を有することが必要なのかどうかも教えてください。","respondent":"櫻木生活福祉課長","answer":"現在の外国人の受給者ですが、令和２年９月末現在で１４３名となっております。国籍としましては、アジア系の方が８９名で、残りはそのほかという形になっております。","voiceIndex":72,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。外国人の生活保護の受給に法律上の根拠というのはあるのでしょうか。","respondent":"櫻木生活福祉課長","answer":"外国人の受給につきましては、生活保護法の適用ではございませんで、行政等の通達等に基づく行政措置として、事業として実施しているです。","voiceIndex":74,"id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"この事実上の保護の根拠が、昭和２９年、１９５４年の厚生省の通知です。このように、日本人が、外国に行ったら日本と同様の生存権保障制度を受けられるのかといった相互主義の有無などを考慮して、法的安定性、行政執行の安定性が保てる、日本国民が納得する法整備を行うべきと、現状の見直しをしていただきたいと国に求めるべきだと私は考えるのですけれども、区のご見解はいかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"外国人の受給に関しては、様々な議論等があるのは承知しております。生活保護に関しましては、第一号法定受託事務ということで、一義的には国の指針・方針・法律にのっとって行っていくところですので、現時点ではそのような対応をしてまいりたいと考えています。","voiceIndex":76,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"そもそも最高裁判所判決の２０１４年からもう既に６年が経っておりまして、国がこの問題を放置しているまま、６６年前の厚生省通知のまま、それに頼って運用というのは非常におかしなことだと思いますので、品川区としてもしっかりと、葛飾区や埼玉県に倣って、国に対して問題提起というものを行っていただきたいのですけれども、それについてご見解はいかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"委員ご指摘のような点も含めて、国において様々な議論があることは承知しております。そのような議論も踏まえて、国の議論の方向を確認しつつ対応してまいりたいと考えています。","voiceIndex":78,"id":"exchange-034"},{"speaker":"筒井委員","kind":"質問","question":"現場の職員も大変かと考えていますが、少しいびつな状況かと考えていますので、引き続き私も注視して、この問題を追っていきたいと思います。ぜひ品川区も国の動向もしくはご自身の見解を固めていただいて、ご対応をよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"２４７ページ、２項児童福祉費、３目児童保育費、２５１ページ、のびしなプロフェッショナルスクール、２５４ページ、４目保育支援費、２４３ページ、児童相談所移管推進事業、２３９ページ、しながわネウボラネットワーク事業について伺います。その観点から引き続き質問します。区は、公設民営保育園の保育従事職員人件費割合の差を確認しているのでしょうか。その結果をどう評価しているのか、伺います。","respondent":"吉田保育施設調整担当課長","answer":"人件費割合につきましては、東京都の財務情報等の公表においても公表されておりませんので、区も財務情報の公表につきましては、同様に特にホームページ等で公開しているところではございません。","voiceIndex":82,"id":"exchange-036"},{"speaker":"田中委員","kind":"確認","question":"すみません。保育従事職員人件費割合を確認しているかどうかです。","respondent":"吉田保育施設調整担当課長","answer":"大変失礼いたしました。公設民営保育園の保育従事職員人件費割合については確認しておりません。","voiceIndex":85,"id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"保育従事職員人件費割合を確認していないということで残念でした。そのため、保育従事職員人件費割合も記入して区に提出しているので、ぜひ確認していただきたいと思います。それで、財務情報の確認は、保育の質の確保のために重要だと考えますが、見解を伺います。次に、認可保育園について伺います。確認した結果を改めてお知らせください。","respondent":"若生保育支援課長、吉田保育施設調整担当課長","answer":"その結果ですけれども、事業者から、これは他区の事例ではあったのですが、国の通知に基づいて対応してきましたというところと、国が通知の中で若干解釈を変更してきた部分がございまして、国が最終的に６月に出した通知は。東京都のキャリアアップ補助金に基づいて公表しているところでありますので、今後も公表している資料につきましては、都の様式に合わせて対応していくところです。","voiceIndex":87,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"公設民営園の保育従事職員人件費割合に認識を持っていただきたいということですので、どうぞお願いします。それで、私立保育園です。内容は、問題になった事業者と保育園長との会話です。２,０００万円の利益という事業者の発言について、区としてどのように受止めているのでしょうか。この情報を受けた後、区はどのような調査を行ったのか、伺います。","respondent":"若生保育支援課長","answer":"ご指摘のありました件ですけれども、こちらはその法人の内部のやり取りですので、私どもとしましては、そういった音声データは入手しているところではございませんので、事実としてどうかというところは確認できていないものです。","voiceIndex":90,"id":"exchange-039"},{"speaker":"田中委員","kind":"確認","question":"記録については、音声と音声を文字に起こしたものが区へ情報提供されています。今回の情報提供から、事業者に事実確認をする必要があり、都や他自治体と情報共有する必要があったと生活者ネットワークは考えますが、いかがでしょうか。","respondent":"立木保育課長","answer":"指導検査に関しましては保育課が担当しておりますので、お答えいたします。指導検査に関しましては定期的に入っておりまして、こちらのいわゆる法人関係の書類・会計部門のチェックといったこともやってあります。特段、問題は見受けられないという形で済んでおります。","voiceIndex":92,"id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"その低さを指摘して理由を聞いたりしていれば、区の指導検査実施要綱の基本方針の運営の適正を欠いている状態であるということを、ある程度、伺えたのではないかと考えます。区としての監督責任をどのようにお考えか、伺います。この基本方針では、法令等に違反していることを前提としていますが、運営が疑わしいときに調査・検査をしてこそ法令違反が分かるのではないでしょうか。伺います。","respondent":"立木保育課長","answer":"個別監査等、例えば命に重大な危険がある等におきましては、すぐさま対応しています。区としてやるべきことを検査として行っているところです。","voiceIndex":94,"id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、区内園でも補助金の不適切な運営がされているのではないかと情報提供があった際に、流用等を疑って、区としてすばやく調査・追及すべきだったと考えます。先ほどの私立幼稚園での質疑の中でも、補助金等の区のチェックを求められていました。問題意識はこの保育園でも一緒です。ですので、ぜひ確認してほしいと思います。区の責任は重大ではないかと改めて見解を伺います。","respondent":"立木保育課長","answer":"区が検査権限を持ってあります。指導権限は非常に強いものです。これは、法人運営にも非常に影響が大きいものです。したがいまして、ルールにのっとりまして、厳正・公正に実施しています。","voiceIndex":96,"id":"exchange-042"},{"speaker":"田中委員","kind":"確認","question":"のびしなプロフェッショナルスクールです。保育の質の向上のために様々行われていると確認しましたが、認可園からは、研修に積極的に参加したくても、その分の保育士を補填することが難しいと意見が寄せられています。研修への参加を促すためにも、研修時に減ってしまう保育士の補填について区がフォローすべきと考えますが、いかがでしょうか。そして、今年度の５歳児、年長についてです。","respondent":"立木保育課長","answer":"参加する場合の人的補償に関しましては、私立保育園公定価格の中に、研修参加の際の人的補償というものが含まれております。こちらには、年間で保育士１人当たり３日分が補償されておりますので、そちらで対応できていると考えております。","voiceIndex":98,"id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"次の質問にいきます。子どもが窮地に陥るような造りでないことを具体的に確認させてください。例えば、一時保護所が上階となっていますが、取り返しに来た保護者が勝手に上階に上がれない設計になっているのでしょうか。伺います。２０１９年の決算特別委員会で、生活者ネットワークは子どもの権利擁護の仕組みを求め、（当時の）児童相談所移管担当課長は仕組みを考えていきたいと答弁をされました。","respondent":"加島児童相談所移管担当課長","answer":"あわせまして、子どもの権利に関する検討状況ですが、まず児童相談所においては、子どもの最善の利益に資することを目的に行われるものですので、一時保護した子どもをはじめ、施設入所、里親委託等の措置をした子どもに係る権利擁護の取組みについて。","voiceIndex":100,"id":"exchange-044"},{"speaker":"田中委員","kind":"確認","question":"児童相談所の建設について伺います。今回、基本設計と実施設計を請負った建設事業者についてです。特別区議会議員講演会で、自治体の設計資料を確認すると、児童相談所の実態をつかめていない設計になってしまっている事例があるという講師の話がありました。区としても児童相談所に適した設計となっているのかを判断すると思いますが、どういった知見を基に判断するのか、伺います。","respondent":"加島児童相談所移管担当課長","answer":"それから職員の配置につきましては、こちらは現在、常勤を中心に検討を行っておりますが、必要に応じて会計年度任用職員等の雇用も考えてまいりたいと考えています。","voiceIndex":102,"id":"exchange-045"},{"speaker":"松本委員","kind":"質問","question":"私からは、２６１ページ、認可外居宅訪問型保育、これに絡んで２４３ページ、奨学金貸付事業について、２２３ページ、高齢者社会参加促進事業について、間に合わないかもしれませんが２６７ページ、進学支援給付金について伺いたいと思います。どうすれば区民が安全にベビーシッター事業を利用できるのか、区としても対策を講ずべきと考えますが、ご見解を伺います。","respondent":"若生保育支援課長","answer":"そういった意味で、東京都のほうの基準は、必要な研修を受けるですとか、必要な資格といったものも審査している部分ですので、そういったところで適切な審査が行われた上で、質の確保というのは一定行われていると認識しています。","voiceIndex":105,"id":"exchange-046"},{"speaker":"松本委員","kind":"質問","question":"それだけだったら、やはり区としては無責任になるのではないかと思います。例えば、区在住の学生と連携してみてはどうかと考えるのです。それで、もちろんこれは研修をしっかりとやらないといけないと思うのですが、こう言うと、これはあくまでアイデアベースですけれども、こういったいろいろな方策で、区としても独自にベビーシッターの事業を考えていくべきではないかと考えますが、ご見解を伺います。","respondent":"若生保育支援課長","answer":"ベビーシッターの性犯罪ということで社会問題になっているということは認識しています。こちらは先ほど申し上げましたが、都のスキームを利用している事業ですが、委員ご案内の地域の人材といったところの地域貢献ともつなげていく。","voiceIndex":107,"id":"exchange-047"},{"speaker":"松本委員","kind":"提案","question":"かなり無理やりな提案になりましたけれども、本当に区民の安全ですので、ぜひ引き続きご検討をお願いできればと思います。そういった中で、重症化リスクの高いシニア世代のグループでのカラオケを勧めている本事業なのですけれども、これを継続している理由と、感染症対策という意味で区としてはどういう方策を取られているのか、お願いいたします。","respondent":"菅野高齢者地域支援課長","answer":"グループの実施ということは、やはり人との交流といったことが大事ということで、グループでの利用を優先として対象者を登録していただくような事業となっております。","voiceIndex":109,"id":"exchange-048"},{"speaker":"松本委員","kind":"意見","question":"利用者がいないというところで分かりました。どういうふうにシニア世代の皆さんの交流を促進するかというところは、これまでのやり方とは違うところを考えないといけなくて、例えばカラオケも自宅でＺｏｏｍなどを使いながらやるというような、いろいろな方策がありますので、ぜひ引き続き、新しい事業も含めて検討していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-049"},{"speaker":"西村委員","kind":"確認","question":"２３９ページ、地域子育て支援拠点事業費、家庭あんしんセンター運営費、児童センター運営費、間に合えば関連して在宅子育て支援について伺えたらと思います。順不同で伺ってまいります。区内の子育て支援施設につきまして、改めて確認します。以前にも質問させていただきました、平塚にある家庭あんしんセンターの中に子育て支援センターがあります。改めて、今申し上げた施設について教えてください。","respondent":"崎村子ども家庭支援センター長、廣田子ども育成課長","answer":"今、委員からご紹介がありました、子育て支援センターですけれども、今年度から、虐待相談、養育困難の相談について、新設しました子ども家庭支援センターで一元的に受理対応しておりまして、現在、子育て支援センターでは、子育て相談。その他施設については、委員ご案内のとおりです。","voiceIndex":114,"id":"exchange-050"},{"speaker":"西村委員","kind":"質問・要望","question":"そのほかの、今申し上げた子育て世代の方向けの施設を、区民の方により分かりやすく整理していただきたいと考えています。虐待に関しては子ども家庭支援センターということですので、やはり分かりづらく、こうして確認させていただいている中でも少々混乱してまいります。は呼び名、相談できる施設はどこなのか、施設内容が分かるようにご検討いただければと思うのですが、いかがでしょうか。","respondent":"崎村子ども家庭支援センター長","answer":"今年度、課として子ども家庭支援センターを新設いたしまして、区立児童相談所の開設を見据えて虐待相談等の相談機能を一元化したところです。名称等につきましては、今後の区立児童相談所の開設を見据えて、相談機能の在り方とともに検討してまいりたいと考えております。","voiceIndex":117,"id":"exchange-051"},{"speaker":"西村委員","kind":"質問・要望","question":"子どもがほかのご家庭に助けを求めてくるなど、コロナ禍に私にも数件問合せがありました。虐待なのかどうかが分からない場合、母親が子育てがつらい場合、どこに問合わせてよいのか聞かれることが度々あります。警察に問合わせればいいのか、児童相談所なのか、子ども家庭支援センターなのか、その辺りもなかなか周知が難しいところだとは思いますが、より分かりやすく工夫をしていただきたいと考えています。","respondent":"廣田子ども育成課長","answer":"乳幼児親子の方々につきましては、特にコロナ禍におきまして孤立している、ご主人が家にいるので電話では相談ができないというようなお声を頂いておりまして、３月・４月については事業を全部中止しておりましたが、６月以降につきましては。","voiceIndex":119,"id":"exchange-052"},{"speaker":"西村委員","kind":"質問・要望","question":"ネウボラ相談の電話に関しては、家族がいると家の中でなかなか話せないという声は私にも届いておりました。今後、高齢者の方を優先、どのタイミングで子育て世帯がまた戻ってこられるのかというのは難しい判断ではありますが、ほかの方法での乳幼児親子の支援を早急にご検討いただきたいと思います。現状、ご検討されていることがあればお聞かせください。","respondent":"廣田子ども育成課長","answer":"現在のところ、ゆうゆうプラザについては高齢者優先ということで、使うことができない状態になってあります。現在は、地域センターの中の集会所や町会会館などをお借りしましてやっているところです。","voiceIndex":121,"id":"exchange-053"},{"speaker":"西村委員","kind":"質問・要望","question":"ぜひ資源を生かしていただきたいと思います。ＬＩＮＥなら、深夜帯でも、子どもが寝ているときでも、家族が起きていても相談しやすく、このＬＩＮＥ相談「子ゴコロ・親ゴコロ相談＠東京」に相談が来た場合、例えば子ども家庭支援センターなどとどのように連携しているのでしょうか。教えていただける範囲で教えてください。","respondent":"崎村子ども家庭支援センター長","answer":"今、委員からご紹介がありました、東京都のＬＩＮＥ相談ですけれども、これは東京都の本局で対応しているものでございまして、その相談の中で、例えば重篤なケース、虐待が疑われるようなケースにつきましては、児童相談所に連絡が行くようになっております。","voiceIndex":123,"id":"exchange-054"},{"speaker":"西村委員","kind":"質問","question":"細かく地域のことを把握しておりますのは、在宅子育ての支援をしてくださっている団体や個人の方であったりもしますので、うまく連携しているといいなと思いまして質問させていただきました。次の質問に移らせていただきます。児童センターの利用なのですが、今後の利用について伺ってまいります。子どもたちがほぼ来られなかったこのコロナ禍の間にどのような業務をしてくださっていたのでしょうか。","respondent":"廣田子ども育成課長","answer":"９月・１０月からは、各館で親子のひろばを、定員を設けて少数の人数で、感染予防に気をつけながら来られるように工夫しています。オンラインにつきましては、双方向ということについて課題があるのですけれども、今後については取り組んでいきたいと考えています。","voiceIndex":125,"id":"exchange-055"},{"speaker":"西村委員","kind":"質問","question":"今、児童センターに、人数を制限しながら少しずつ戻ってこられているということですが、子どもたちはどれぐらい戻ってきているのでしょうか。教えてください。","respondent":"廣田子ども育成課長","answer":"館によってばらつきがあるのですけれども、通常時の半分ぐらいは利用されているという状況です。","voiceIndex":127,"id":"exchange-056"},{"speaker":"松澤委員","kind":"質問","question":"私からは、２１９ページ、認知症高齢者支援事業、２２１ページ、福祉人材確保・定着事業について質問いたします。私事になりますが、先月、介護職員初任者研修の資格を取得してまいりました。そこで、昨年の一般質問でも質問しましたが、認知症サポーター養成講座についてお聞きいたします。この認知症サポーター養成講座の内容はどのようなもので、講師の方はどのような人がやっているのか、教えてください。","respondent":"宮尾高齢者福祉課長","answer":"認知症サポーター養成講座は、認知症になってもその人らしく地域で暮らし続けるために、認知症の正しい理解者、応援者であるサポーターを養成しようということで、これを養成することにより、本人やご家族を地域で支えることができる。","voiceIndex":131,"id":"exchange-057"},{"speaker":"松澤委員","kind":"質問・要望","question":"要介護状態の方を、治らない患者ではなく、自分なりの人生、生活を一生懸命に生きる人であり、その人を生活の主人公としての立場から理解し、それを側面から支える介護職員の気持ちなど、それぞれの思いを伝えていただきたいと考えています。こうした中、品川区では、在宅介護支援センターのケアマネジャーに対して、そういった認識を広げる意味で、講師に対してどういったお願いをしているのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"認知症サポーター養成講座を受けた方々が、受け終わった後に地域で、どのようなサポート、支援ができるか。こういったことを２つの大きなテーマとして教材に使用させていただいているところです。","voiceIndex":133,"id":"exchange-058"},{"speaker":"松澤委員","kind":"質問","question":"認知症サポーターが今後どのような支援をという部分で、認知症サポーターの方々に、それ以降、行政から、これをやってくださいというものがなかったり、地域からもお声がないという話があるのです。そういった部分で、品川区から、受講したら終わりではなくて、サポーターの方たちと何か一緒にやれるような取組みというお考えはありますでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"例えばサポーターの方の１つの役目として、サポーターの講座が終わったら、次はキャラバン・メイトになっていただく。このようなことも１つ、策としてあるのではないかと考えております。","voiceIndex":135,"id":"exchange-059"},{"speaker":"松澤委員","kind":"意見","question":"実際には重複者がいるので正確な数字とは言えません。やはりここでしっかりと把握して、地域包括部分では必要になることであって、要は、もっといろいろなところに、「こういう制度がありますよ」とか、「小規模多機能型だったら、実はここは入れるんですよ」といった、区民の知らないサービスをもっと教えられるのではないかと思うのですけれども、待機者を減らす道という部分でご見解をお聞かせください。","respondent":"宮尾高齢者福祉課長","answer":"今、委員からご提案いただきましたように、施設の状況、それから例えば定員の充足状況ですとか、しっかりとそういったものの把握に努めるということはとても大事なことだと考えています。","voiceIndex":139,"id":"exchange-060"},{"speaker":"松澤委員","kind":"質問","question":"引き続き、いろいろとご努力をよろしくお願いします。次に、福祉人材確保について少し質問させてください。午前中、芹澤委員からも質問がありました。品川介護福祉専門学校、人数が足りていないという話でしたが、これは、全国で唯一、地域で活躍する福祉人材の育成を目指して社会福祉協議会が設置している専門学校です。その部分だけ少し教えてください。","respondent":"宮尾高齢者福祉課長","answer":"品川介護福祉専門学校に関するお尋ねです。品川介護福祉専門学校は、どちらかというと、今、委員がお話しいただいた後者のほうに近い、介護人材を安定的に区内の施設に供給したいというところからスタートしたものだと認識しております。","voiceIndex":141,"id":"exchange-061"},{"speaker":"つる委員","kind":"提案","question":"今日は民生費の款ですので、そのうちの移動経費補助や多胎ピアサポート事業は衛生費の款だと理解しています。あえて言えば、今年度から利用することもできたわけでありますが、いろいろな整備が必要だというところで、次年度、期待しておりますけれども、確実に次年度、そして東京都が示しているまさにフルスペックでの実施かどうかの確認をお願いします。","respondent":"崎村子ども家庭支援センター長","answer":"こちらの補助金についても１０分の１０、都から補助が出るということで伺っておりますので、そちらの制度をそのまま活用する形で、区では検討を進めているところです。","voiceIndex":145,"id":"exchange-062"},{"speaker":"つる委員","kind":"提案","question":"ぜひ拡充を十分にしていただいて、周知も含めてしっかりと図っていただきたいと思います。その人材育成の仕組みについては、２０１６年にも提案させていただいたということでお伝えさせていただいているところでありますが、まさにドゥーラ協会との連携になると思います。区として人材育成をやっていただくにあたって、１年間で大体何名ぐらい育成の想定をされているのかも教えてください。","respondent":"崎村子ども家庭支援センター長","answer":"先ほどご紹介がありましたように、今、産後ドゥーラで登録されている区民の方というのは１０名弱といったところで、今後、産後家事育児支援を拡充していくにあたりましては、産後ドゥーラの方をやはり増やさなければいけないと認識しております。","voiceIndex":147,"id":"exchange-063"},{"speaker":"つる委員","kind":"提案","question":"これも２０１８年の決算特別委員会で、子どもたちの登下校、すまいるスクールでの入退室を管理でき、保護者に発信される仕組みをということで提案させていただいたものが、次年度末から試験運用、今年度から本格運用されているわけでありますが、ただ、新型コロナウイルス感染症の影響ですまいるスクールそのものの利用状況がいろいろあった中ではありますけれども、まず。","respondent":"廣田子ども育成課長","answer":"すまっぴ、すまいるスクール入退室管理システムのご質問です。２月より稼働を開始しまして、登録数が６万２,９５９件で、登録率９８.３％というところで、おおむね登録は頂いているところです。","voiceIndex":149,"id":"exchange-064"},{"speaker":"つる委員","kind":"提案","question":"まさに最初の年度というところで、いろいろ試行的なところもありますし、今、この非常時の中で、なかなか本来ある機能が十分に使えていないというのは非常に悩ましいところでありますけれども、すまっぴで入退室管理をすることで、保護者側も、ある意味、いい意味で心の余裕を持って、自分の子どもたちへの対応というか、自分のご予定の調整もできているというところで、非常に子どもにとっても安心ですし。","respondent":"廣田子ども育成課長","answer":"保守につきましては、１か所幾らという形では出ていないのですけれども、全箇所通信料で、月１０万円を１２月、システム利用料で月５０万円を１２月ということで、手元には全体の数字のみで、１か所ごとで割り返していなくて申し訳ございません。","voiceIndex":151,"id":"exchange-065"},{"speaker":"つる委員","kind":"質問","question":"最後、少し声が小さくなってしまって分からなかったのですが、３７か所で、単純に割ると１万円ぐらいなのかと、それこそ割り返してみたのですけれど、そこは分かりました。それと、今年度のところになってしまうのですが、すまっぴの操作説明会というところで４回実施する予定、もう行ったと思うのですが、８万円となっているのですけれど、この内訳を教えてください。","respondent":"廣田子ども育成課長","answer":"研修につきましては、まだこれから機能が拡充していくので、そこで行っていく予定になっているのですけれども、新型コロナウイルス感染症の関係で、今そんなに進んでいないのですが、あと研修で講師が来る開催費用になってあります。","voiceIndex":153,"id":"exchange-066"},{"speaker":"つる委員","kind":"確認","question":"そこは確認でした。次にいきます。福祉タクシー・自動車燃料費助成についてなのですが、これは視覚障害の団体の方が、「品川区、それから各会派の皆さんにも様々お声を届けました」と私も伺っているところでありますが、この中で、福祉タクシーの利用券なのですが、今現在、品川区は年間で、１冊３,５００円を１２冊支給されていて、その１冊の中身が、５００円券が６枚と１００円券が５枚と伺っております。","respondent":"松山障害者福祉課長","answer":"そのため、今後ともご意見を伺ってまいりまして、確かに２３区の中で様々それぞれの区の実情に合わせてありますので、実情に合った利便性を高めていきたいと考えています。","voiceIndex":155,"id":"exchange-067"},{"speaker":"つる委員","kind":"質問・要望","question":"いずれにしても、利用者目線に立った福祉サービスの提供ということが大事かと思いますので、お願いしたいと思います。残った時間で、これは何度か確認させていただいている、品川区役所第三庁舎にあるオアシスルームについてなのですが、駐車場の利用の考え方と同じで、ぜひ無料化に向けた検討をしていただきたいと思います。年度を１つ超えたので、今現在の検討状況を教えてください。","respondent":"若生保育支援課長","answer":"課題の洗い出し等を行いまして、やはりシステムの問題ですとか、改修が必要になるとか、あとは何をもって、行政目的で利用したかという確認を取るか。そういった課題が今、確認できたところです。今後、具体的な検討に向けて引き続き考えてまいりたいと思います。","voiceIndex":157,"id":"exchange-068"},{"speaker":"くにば委員","kind":"質問","question":"コロナ禍によって外出自粛が続き、特に高齢者にとって懸念されているのが、ひきこもりがちになって人と接する機会が減り、精神面・健康面ともに健全さが失われてしまうことです。こちら、健康づくり・生きがい活動事業について伺います。続きまして、いきいき健康マージャン広場。人気の輪投げ大会やグラウンドゴルフ大会の、現在、３月以降の実績であるとか、今後の利用の見通しをお聞かせください。","respondent":"菅野高齢者地域支援課長","answer":"次に高齢者輪投げ大会です。こちらは１１月１２日に総合体育館で実施を予定しておりますが、かなりの人数が集まるものですので、参加人数を半分にするために、例年は午前と午後で一日中なのですが、２部制としまして、午前の部・午後の部ということで実施しようと考えています。","voiceIndex":160,"id":"exchange-069"},{"speaker":"くにば委員","kind":"質問","question":"やはり、高齢者のほうがなかなかリスクが高いということで、その他の事業よりも、さらにリスクが高いから慎重にならざるを得ない。続きまして、ひとり親家庭学習支援事業の、ぐんぐんスクールについて伺います。品川地域未来塾のほうでは、ＩＣＴ機器やＡＩプログラムを活用して、放課後学習支援事業をしているのですけれども、ひとり親家庭の子たちに対して、この活用の予定はないのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"ぐんぐんスクールにつきましては、現在のところ、ＮＰＯ法人キッズドアに委託しておりまして、こちらはひとり親家庭の経済的・精神的不安の軽減や自立支援に向けた取組みとして、児童への個別学習などを実施しています。","voiceIndex":162,"id":"exchange-070"},{"speaker":"くにば委員","kind":"意見","question":"私が１つ思った部分が、ひとり親家庭の子たちのみを集めて行う事業ということで、これが行政や親にとって、そうしたほうがメリットがあるなどということはあるとは思うのですけれども、これが子どもたちにとって何かメリットがあるのか。子どもたちの目線に立ってメリットがあるか、お教えください。","respondent":"三ッ橋子育て応援課長","answer":"したがいまして、いろいろなご両親がいらっしゃる方、またひとり親の方、それぞれ様々な考え方があるとは思うのですけれども、所得の部分など、やはり切実に思われているところがあると捉えております。","voiceIndex":164,"id":"exchange-071"},{"speaker":"くにば委員","kind":"質問","question":"今おっしゃった形で、所得が一般の家庭より少ないというのはデータとしてあると思います。結局、ひとり親家庭だから特別視してほしいという方もいらっしゃると思いますし、その他、逆に、特段、特別視してほしくない。普通の人と同じように扱ってほしいといった、様々いると思うのですけれども、個人的な感覚では後者のほうが多い。","respondent":"三ッ橋子育て応援課長","answer":"区民の皆様にとっていろいろな選択肢があっていいと考えています。その中で、ぐんぐんスクールはひとり親家庭という部分でございまして、また委員ご指摘の地域未来塾というのは幅広いものと捉えております。","voiceIndex":166,"id":"exchange-072"},{"speaker":"くにば委員","kind":"質問","question":"少し割愛していきます。これは、対象がひとり親家庭、さらには生活保護家庭ですか、その辺のみに範囲が限定されておりまして、せっかくすばらしい制度なので、もう少し枠を広げて、所得制限という部分で、一定の所得を下回る世帯の子でしたら誰でも利用できるような制度にするといった検討というのはなさるのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"ドリームサポート事業ですけれども、こちらは、生活困窮者であるとか、またひとり親世帯から、ぐんぐんスクールを利用されている方を中心にご案内していますので、委員のご提案も踏まえながら様々なことを検討していきたいと考えています。","voiceIndex":168,"id":"exchange-073"},{"speaker":"くにば委員","kind":"質問・要望","question":"最後に１点だけ端的に触れます。債権回収業務等委託のほうが、これは２０１５年の議事録で確認したところ、シルバー人材センターの方に委託をしていると。債権回収業務にＮＨＫ集金人が適しているかどうかというのは区のご判断だと思いますけれども、私、一般質問でもろもろ問題について提起しましたので、そこについて、普通の職業の方でもいいのではないかと、そこは強く要望しまして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":170,"id":"exchange-074"},{"speaker":"おくの委員","kind":"質問・要望","question":"２１７ページ、入院中の紙おむつ代助成事業、そして２１９ページ、紙おむつ支給について伺います。より使いやすい制度への改善を求めまして質問します。入院中の紙おむつ代助成事業のことです。２年前に、伺ったお話として出したお話が、庭仕事をしていてはしごから落ちて、頭をブロックの角にぶつけて植物状態になってしまい、何年も入院されていた方のお話でした。伺います。この点を伺います。","respondent":"宮尾高齢者福祉課長","answer":"こちらは、在宅での生活を支援する、それと地域福祉といった観点から、社会福祉協議会の自主事業として実施しておりまして、それに対して区が事業費の助成を行っているという事業です〔同日後刻「区の事業で、社会福祉協議会に委託している」と答弁訂正あり〕。","voiceIndex":172,"id":"exchange-075"},{"speaker":"おくの委員","kind":"質問・要望","question":"それで、やはり病気療養、この方はけがですけれども、病気やけがをなさった方には、なるべく病気やけがの治療・療養に集中していただきたいわけです。それで治していただきたい。そういう羽目になるわけです。そういう意味で、変な線引きというか、やはり非課税というような要件は外して、なるべく多くの方がこういう制度の恩恵を受けられるようにすべきではないでしょうか。いかがでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"お尋ねの所得制限のところですけれども、繰り返しになりますが、入院されたときというのは、一時的には確かに治療費の負担、それからもろもろ、いろいろな出費が重なるということは認識しております。","voiceIndex":174,"id":"exchange-076"},{"speaker":"おくの委員","kind":"意見","question":"そういうことです。一般財源ではあるのですけれども、先ほど述べましたように、特別な人に特別な利益を与えるような事業ではない。それから、もう一つ、これは限度額が５,０００円になっているのです。隣の港区では１万円となっております。この点も含めて工夫ができるのではないかと思いますけれども、非課税の点と限度額の点と、併せてご答弁いただければと思います。","respondent":"宮尾高齢者福祉課長","answer":"こちらの入院中の紙おむつ代助成事業というのは、経済的な支援ということを目的としてやらせていただいております。当然、ほかの自治体の動向なども調査研究を進めてまいりますが、現時点ではこの対象要件につきまして変更する考えはございません。","voiceIndex":176,"id":"exchange-077"},{"speaker":"小芝委員","kind":"質問・要望","question":"私からは、２２７ページ、障害者理解・普及啓発事業に関連して、聴覚障害者のデフリンピックと手話言語条例について、また２６７ページ、法外援護費の被保護者自立促進事業について、最後に２２３ページ、高齢者社会参加促進事業についてお尋ねいたします。コロナ禍の中でも、そもそも全く見通しがつかないということもあるかもしれませんが、いかがお考えでしょうか。","respondent":"松山障害者福祉課長","answer":"委員お尋ねのデフリンピックについての今後の考え方です。デフリンピックにつきましては、やはり障害者団体からご要望は頂いております。ただし、区だけで何かできるものではなく、今後、国や都の動向を注視しながら、必要があれば区として検討に入りたいと考えています。","voiceIndex":179,"id":"exchange-078"},{"speaker":"小芝委員","kind":"質問・要望","question":"デフリンピックはまだまだ認知度が低い国際大会です。その前段階として、聴覚障害、そしてデフリンピック実現の出発点として、手話言語条例の制定を今回も求めていきたいと考えますが、昨年も同様の手話言語条例の条例化に向けての動きを質問させていただきましたが、その後の状況を改めて教えていただきたいと思います。","respondent":"松山障害者福祉課長","answer":"手話言語条例に向けての進捗状況についてのお尋ねです。昨年度から検討してまいりましたが、新型コロナウイルス感染症の影響で、手話に関わる当事者や支援関係者との話し合いを一時期中断しておりました。","voiceIndex":181,"id":"exchange-079"},{"speaker":"小芝委員","kind":"質問","question":"今年に入ってからは既に東京２３区でも新たに５区、江東区、中野区、台東区、北区、新宿区で手話言語条例が成立され、既に１３区で成立しております。続きまして２６７ページ、法外援護費の被保護者自立促進事業についてお尋ねいたします。前年度と比べて増えたわけですが、この増加をどのように捉えていますでしょうか。具体的に世代ごとにどのぐらいの人数の方が増えたのか、教えていただければと思います。","respondent":"櫻木生活福祉課長","answer":"増加の要因としまして、令和元年度につきましては、基本的には保護の世帯数としては減少しています。高齢者の方の医療費等の増加等の要因、様々な要因があったかと思います。世代ごとの構成人数は今、手元にございません。","voiceIndex":183,"id":"exchange-080"},{"speaker":"小芝委員","kind":"質問","question":"貧困の連鎖を断ち切るために、子どもがいる世代であれば、十分な教育環境を整えていくことが、長期的で発展的なプロセスと考えますが、品川区でも東京都の補助金を活用した被保護者自立促進事業が展開されております。主なものに塾代の支援があると伺っております。そこでお聞きしますが、令和元年度分において補助金を活用したお子さんは、中学、高校でそれぞれ何名ほどいらっしゃったのでしょうか。","respondent":"櫻木生活福祉課長","answer":"先ほどの扶助費の件ですが、平成３０年度から令和元年度につきましては、扶助費自体は減少しているです。それと、塾代の支援を利用された数ですが、今、確認しておりますが、後ほど答弁します。","voiceIndex":185,"id":"exchange-081"},{"speaker":"小芝委員","kind":"質問","question":"そうしましたら質問を変えます。２２３ページ、高齢者社会参加促進事業についてお伺いします。先ほど、くにば委員からも同じような質問があり、くにば委員の質問に対する答えで、徐々に活動再開の動きが出ていることは分かりました。感染防止を行った上で、少しずつ交流の再開ができてきて、高齢者の方が再び生き生きと幸せをかみしめるときが来ることを期待いたしますが、最後に区の考えを教えてください。","respondent":"菅野高齢者地域支援課長、櫻木生活福祉課長","answer":"区としましても、この間、フレイル予防ということで、運動、栄養、そして人との交流が大事だということで、そういったチラシを町会や高齢者クラブに配布したりするなどして、高齢者の方のフレイル予防に呼びかけをしてまいりました。大変失礼いたしました。塾代の支援の利用者ですが、小学校４年生から中学２年生までが１８名、中学３年生１１名、高校１年生６名、高校３年生６名です。","voiceIndex":187,"id":"exchange-082"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、２４３ページ、児童相談所移管推進事業、２３９ページ、児童センター運営費、２６７ページ、生活困窮者自立支援事業、４７９ページ、運動系介護予防事業についてお伺いいたします。１点目に歳入の続きなのですけれども、ペアレントトレーニングなどについてお伺いいたします。こうした都の研修等の機会を積極的に活用していただきたいと考えますが、いかがでしょうか。","respondent":"加島児童相談所移管担当課長、廣田子ども育成課長、崎村子ども家庭支援センター長","answer":"１点目の、児童虐待のペアレントトレーニングの実施についてですが、児童虐待の根本の解決と再発生予防にあたりましては。ただ、実施にあたりましては、プログラム実施のみでなく、日頃から相談支援など、寄り添い、伴走するような体制を整える必要があるのかなと考えております。区としても、そちらの研修に、相談員の派遣について要請を行いまして、今月から、福祉職、心理職、それぞれ１名、短期派遣研修に行く予定です。","voiceIndex":191,"id":"exchange-083"},{"speaker":"横山委員","kind":"質問","question":"児童相談所開設に向けての人材確保についてお伺いします。２点目に、運動系介護予防事業についてお伺いします。カラダ見える化トレーニングの応募と参加率について、参加へのモチベーションを高めた要因をどのように分析しておりますでしょうか。３点目に、生活困窮者自立支援事業についてお伺いいたします。リーマンショックのときと比較して、相談者の性別や年齢層などに変化は見られるのでしょうか。","respondent":"加島児童相談所移管担当課長、櫻木生活福祉課長、菅野高齢者地域支援課長","answer":"業務の過程において互いの主張がぶつかるということはあるかと思いますが、それぞれ互いの立場を尊重し、チームワークで業務上連携していけるよう。リーマンショック時と比較してですが、定量的には把握できておりませんが、職員の中で、リーマンショック時の頃から在籍している者の話を聞くと、若干。令和元年度は延べ参加者数２,９４６人ということで、なかなか人気の事業と認識しております。","voiceIndex":195,"id":"exchange-084"},{"speaker":"横山委員","kind":"質問・要望","question":"カラダ見える化トレーニングについてなのですけれども、こちらは倍率もすごく、二、三倍ということで、成果が上がっているのではないかと考えています。こちらは、応募したけれども、まだ受けられていない方というのもいらっしゃるかと思いますので、ぜひ引き続き効果を出していけるような形で進めていただきたいと思うのですけれども、一言お願いしたいと思います。","respondent":"菅野高齢者地域支援課長、櫻木生活福祉課長","answer":"１点目のカラダ見える化トレーニングにつきましては、大変人気ということですので、２回目のお申込みの方は、初めてのお申込みの方を優先するという形で抽選をさせていただいて。給付と相談ですが、相談を受けて、今回、様々な給付もしくは融資の制度がありますので、そちらについて丁寧にご案内していけるようにしたいと考えています。","voiceIndex":199,"id":"exchange-085"},{"speaker":"塚本委員","kind":"質問","question":"私からは、初めに２３３ページ、要医療的ケア者受入促進、次に２１９ページ、認知症高齢者支援事業、３番目に２５５ページの区内私立保育園経費ということでお伺いしたいと思います。最初に、要医療的ケア者受入促進ということで、旗の台の心身障害者福祉会館でこの事業が進められているわけですけれども、まず最初に、現状、進捗状況についてお知らせください。","respondent":"松山障害者福祉課長","answer":"ハード面におきまして、本年度、これから重度の方の居室の床暖房工事を行いますので、４月から週に５日、２名程度の、医療的ケアが必要な方の受入れを行う予定です。","voiceIndex":203,"id":"exchange-086"},{"speaker":"塚本委員","kind":"質問","question":"要医療的ケア者に対する施設の受入れというのは長年かかってきた、大変ご苦労されてきた事業かと思いますけれども、ようやく来年の４月から開始されるということで、非常に喜ばしいことと受け止めております。その辺についての、呼吸器というのは１つの例ですけれども、受入れ対象者に対する考え方についてお伺いします。","respondent":"松山障害者福祉課長","answer":"当然ながら、人工呼吸器をご利用している方の健康状態、それから日中過ごす環境に大きく左右されるものと考えています。ご本人の主治医、または、施設の嘱託医の判断によるところが大きいと認識しております。","voiceIndex":205,"id":"exchange-087"},{"speaker":"塚本委員","kind":"質問・要望","question":"認知症高齢者支援事業なのですけれども、これまでも何人かの委員から、この点について質問がありましたが、そういう意味では少し具体的に聞きたいのですけれども、コロナ禍で認知症高齢者事業というものが、今、かなり制限されているかと思います。事業を停止しているというか。どういった状況になっているのか、少し具体的にお聞かせください。","respondent":"宮尾高齢者福祉課長","answer":"ただ一方で、こういった状況を踏まえまして、例えば一部で事業をオンライン化できないかというような取組みも少しずつ始めする予定でおりまして、具体的には今年度、認知症の講演会というものを予定しているのですが、ここで、全てオンラインというのはなかなか難しいのですが。","voiceIndex":207,"id":"exchange-088"},{"speaker":"塚本委員","kind":"質問","question":"保育園事業者は、ご案内のとおり、１事業者が品川区内にだけいるわけではなくて、広域にいろいろなところで園を開いている。認可保育園をやっていたりする。そういった中で、なかなか実際にはそういうふうにならないという状況かと認識しておりますけれども、その辺の理由はどうしてなのかというところを、まずお伺いしたいと思います。","respondent":"若生保育支援課長","answer":"私立保育園の事務負担は、やはり私立保育園、民間企業等の運営事業者に対して補助金を、これはかなりの額を支払っておりまして、その補助金の様式というのが、やはり国や都が定めている様式でかっちりと決まっているものでして、その中の、例えば確認書類みたいなところは。","voiceIndex":209,"id":"exchange-089"},{"speaker":"木村委員","kind":"確認","question":"私からは、民生費の２２３ページ中ほどの上にあります高齢者社会参加促進事業の中の健康づくり・生きがい活動事業の、いきいき健康マージャン広場と、いきいきカラオケ広場から質問です。先ほどほかの委員からも同じような質問があったかと思います。確認ですが、コロナ禍での事業は現在も行っているのでしょうか。先ほどもこの質問がありましたけれども、どうぞお聞かせください。","respondent":"菅野高齢者地域支援課長","answer":"いきいき健康マージャン広場についてのご質問です。こちらは、９会場２９コースで実施しておりますが、現在のところ、新型コロナウイルス感染症の関係で、こちらの事業は休止している状態です。","voiceIndex":213,"id":"exchange-090"},{"speaker":"木村委員","kind":"質問","question":"表現は少し悪いのですけれども、年を重ねていくごとに、どうしても気になるのはぼけというものでありますけれども、ぼけを防止または予防するには、新しいことを覚えて脳に刺激を与えたり、頭脳をフル回転させて働かせる必要があります。行政として健康マージャンを高齢者に勧めてほしいと思いますけれども、新型コロナウイルス感染症が収まれば、またいかがでしょうか。","respondent":"菅野高齢者地域支援課長","answer":"マージャンを通じてコミュニケーション活動をすることによって、高齢者の方の認知機能の低下が防げるのではないかと思いますので、新型コロナウイルス感染症が収まりましたら、また事業を積極的に再開していきたいと考えています。","voiceIndex":215,"id":"exchange-091"},{"speaker":"木村委員","kind":"質問・要望","question":"本当に家庭で閉じ籠もっている高齢者たちに、これを使って少しでも頭を使うこと、そういう意味でもぼけを防いでいくということに、ぜひとも行政の皆さんのお力をまた貸していただきたいと思っています。次に、いきいきカラオケ広場についてお聞きいたします。この事業も、コロナ禍での活動は行っているのかどうか、最初にお聞かせください。","respondent":"菅野高齢者地域支援課長","answer":"東京都の休業要請が発動されたときには、カラオケ店がお店を閉めていたということで事業も休止しておりましたが、その後、６月中旬に休業要請が緩和されたことによってお店が再開いたしましたので、こちらは自主的に参加していただく方にはご利用できる状況なのですけれども。","voiceIndex":219,"id":"exchange-092"},{"speaker":"木村委員","kind":"質問","question":"先ほどのいきいき健康マージャン広場と、いきいきカラオケ広場、高齢者には本当に必要な事業でしょうか。そして、もし必要であるとお答えであれば、なぜそれが本当に必要なのか、高齢者にはこの２つの事業が必要なのかどうかということをお聞かせください。","respondent":"菅野高齢者地域支援課長","answer":"やはりシルバーセンター等でもカラオケは大人気ということもあります。そして、いきいき健康マージャン広場も８００人以上の登録者がいるということで、やはり高齢者の方が楽しく参加しているということがうかがえますので、必要な事業として認識しております。","voiceIndex":221,"id":"exchange-093"},{"speaker":"木村委員","kind":"質問","question":"日々を明るく元気に過ごすということですから、高齢者には絶対に必要なことだと私は思っています。そして、友人や同年代と笑顔で楽しめるわけですから、健康に適しているのではないかと私は思っています。そのいきいきカラオケ広場の決算額が１万９,１３４円ですけれども、この記載が間違っているのではないかと最初は思いました。このお金は何に充てた金額なのでしょうか。ご説明ください。","respondent":"菅野高齢者地域支援課長","answer":"こちらのいきいきカラオケ広場の決算額、１万９,１３４円につきましては、まず区の高齢者地域支援課に団体登録をしていただきまして、その登録証を持ってカラオケ店に行ってもらうという事業のスキームになっておりますので、こちらは登録証に要する紙の代金や。","voiceIndex":223,"id":"exchange-094"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、２２４ページの障害者福祉費から手話言語条例について伺いたいと思います。答弁を見ますと、聴覚障害者協会の方々や明晴学園の方々などと、要望等を聞きながら研究していくとか、先行自治体の条例の研究を進めていく等々、こうした答弁が繰り返しされているのですけれども、研究されてどういうことが得られているのか、そして条例制定に向けてどういう状況なのか、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"手話言語条例についてのお尋ねです。この間、研究してきたこととしましては、障害者福祉課といたしましても、手話に関わる当事者、それから支援者等と一緒に話し合いを持って、１つずつ歴史的なものを学んでいったです。","voiceIndex":228,"id":"exchange-095"},{"speaker":"石田（ち）委員","kind":"質問","question":"学ぶことも大事だと思うのですけれども、２０１４年の請願のときから聴覚障害者の方々から、私も学習会に参加しましたけれども、手話言語、これなのだということが呼びかけられてきて、そして３年前ぐらいからも答弁で、そうした研究をしてまいりますということがずっと言われてきているのですけれども、今、ようやくこういう状況だということなのか、それとも条例を制定するにあたっての。","respondent":"松山障害者福祉課長","answer":"必要性についてですけれども、やはり区内のこれだけ多くの異なる団体が意見を一致させて合意を生むということは非常に必要なものだと認識しております。","voiceIndex":230,"id":"exchange-096"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、各自治体の実情に合わせて、そして、思いを文言に表すので時間がかかるということで、確かに当事者の皆さん抜きにはつくれないと思いますので、そこは丁寧にやっていただきたいのですけれども、そうすると条例制定の見通しというのは立たれているのでしょうか。そういったところに目掛けて、目指して進んでいるという状況でしょうか。伺います。","respondent":"松山障害者福祉課長","answer":"条例制定の見通しについてのお尋ねです。中断しておりました話し合いに向けてようやく再開したところですので、まずはそれぞれの意見の合意形成というのが非常に大事になってまいりますので、まずは第一歩を踏み出したです。","voiceIndex":232,"id":"exchange-097"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"障害者福祉課には週２回、手話通訳の方が配置されていると思うのですけれども、人数や回数に変わりはないのか、伺いたいと思います。そして、手話通訳者も手話言語として重要な方々ですけれども、品川区は２３区でも少ないということで、当事者からも声が寄せられてきたのですけれども、現在何人いらっしゃるのか、経年的な数字も伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"それから２点目の、情報推進課が配置しているタブレットの件ですけれども、情報推進課とは連携して配置しているということで、昨年度から本格導入を行いまして、２台のタブレットを運用し。","voiceIndex":234,"id":"exchange-098"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"手話通訳者の方々も、聴覚障害の方にとっては、外で、また自分が出向く先で本当に必要になってくる方々ですので、一足飛びには増えない。そのためにも、やはり手話言語条例を制定して広くアピールといいますか、聴覚障害について、そして手話について、社会的に広めていくというところでも、力になるものだと思うのです。引き続き私たちも強く求めていきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-099"},{"speaker":"あべ委員","kind":"質問","question":"私からは、２２５ページ、障害者福祉費全般に関わってくると思います。児童養護施設にいる子どもたちの福祉サービスについてお伺いしたいと思います。それから２３５ページ、障害児者総合支援施設運営経費について、２４３ページの児童相談所移管推進事業について、そして２５７ページの保育園の定期利用保育事業についてお伺いしたいと思います。品川区は課題を認識し、実態を把握されていますでしょうか。","respondent":"松山障害者福祉課長、築山障害者施策推進担当課長","answer":"委員ご指摘のとおり、児童養護施設には多数の障害のあるお子さんがいらっしゃると思いますけれども、私どもの福祉サービスとシステム上の連携が取れていないということ。応援サイトの件ですが、存じております。こちらの感じているところということですけれども、運営事業者も非常に頑張っておりまして、利用者の視点で、きめ細かく対応してくださっているというところを実感しております。","voiceIndex":238,"id":"exchange-100"},{"speaker":"あべ委員","kind":"質問・要望","question":"次の質問に移ります。児童相談所の開設において、子どもの権利擁護の観点から、弁護士の配置ということをかねてから求めてきましたけれども、あわせて、現在の子ども家庭支援センターの段階から、子どもの権利擁護に詳しい弁護士との連携強化をしていただきたいと思いますけれども、いかがでしょうか。そのうち、認可園に申し込んで入れなかったお子さんの割合は何人となっているのか、教えてください。","respondent":"加島児童相談所移管担当課長、若生保育支援課長","answer":"準備段階よりこちらで求める人材が見つかりましたら、子ども家庭支援センターと協力いたしまして、配置を図ってまいりたいと考えております。定期利用保育の実績ですけれども、今年度の実績が手元にないので、令和元年度の実績で答えしますと、合計で４６４人が定期利用をしています。","voiceIndex":241,"id":"exchange-101"},{"speaker":"あべ委員","kind":"質問","question":"定期利用保育ですけれども、こちらの利用は所得にかかわらず月額４万５,０００円の利用となっております。今、０歳児から２歳児のお子さんたちが払っている保育料の平均というのはどの程度になるのでしょうか。月額４万５,０００円というのは、一定の収入以上のご家庭でないと、なかなか利用が厳しい金額設定。この利用料金についてのお考えと平均額をお聞かせください。","respondent":"若生保育支援課長","answer":"それに対して定期利用保育の金額の考え方なのですけれども、こちらは、この事業を開始するにあたりまして、１つは認可園に入れなかった方が対象になるのですけれども、これは認可園と同等にするかどうか、あるいは。","voiceIndex":244,"id":"exchange-102"},{"speaker":"あべ委員","kind":"質問","question":"一定の検討を経てこの金額になったというのは理解するのでありますけれども、しかしながら、結果的に就労を諦めてしまうような金額になっているというのは、やはり保育に責任を持つ自治体の役割としては、もう少し実態に合わせる必要があるだろうと考えています。その考え方で言えば、少なくとも認証保育所に対するのと同等の補助をつくることが適当かと思いますけれども、いかがでしょうか。","respondent":"若生保育支援課長","answer":"先ほどは言葉が足りませんで失礼いたしました。認証保育所の料金のうち、助成金の金額を差し引いた、実質負担額などと同等の金額ということで４万５,０００円に設定したものです。","voiceIndex":246,"id":"exchange-103"},{"speaker":"あべ委員","kind":"質問","question":"それは個々の家庭の経済状況に合わせたものでしょうか。それとも平均額で取っていますでしょうか。","respondent":"若生保育支援課長","answer":"ホームページ等で確認できた、全ての区内の認証保育所の平均額ということで出しています。","voiceIndex":248,"id":"exchange-104"},{"speaker":"あべ委員","kind":"意見","question":"支払い能力が十分にあるご家庭は、私はこの金額でも構わないと考えています。認可園でもそれなりの金額になっておりますけれども。しかしながら、利用している家庭のそれぞれの経済状況に応じた助成あるいは金額設定というのはやはり必要だと思いますが、改めてお願いします。","respondent":"若生保育支援課長","answer":"ただ、これはなかなか永続的にしていく事業ではございませんので、そういったものを考慮して設定したものです。","voiceIndex":250,"id":"exchange-105"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、２２５ページ、高齢者住宅生活支援サービス事業、２３７ページ、障害児者福祉計画基礎調査、２６１ページ、認可外居宅訪問型保育、２６３ページ、生活保護経費からお伺いしたいと思います。順不同でまいります。高齢者住宅生活支援サービス事業と生活保護経費を一括してお伺いしたいと思います。確認ですけれど、この事業を創設した背景と経緯、そして、この事業の目的をお知らせください。","respondent":"菅野高齢者地域支援課長、櫻木生活福祉課長","answer":"私からは、高齢者住宅生活支援サービス事業についてご説明します。この事業の、平成３０年８月に開始したときの背景というご質問だと思います。大家の方に安心してお貸しいただくためにですが、制度としまして家賃の代理納付という制度があり、区が受給者の方を経由せずに直接家賃を納付するという制度、それから撤去の際に必要な経費の中で保証料等がありますが。","voiceIndex":253,"id":"exchange-106"},{"speaker":"こんの委員","kind":"質問","question":"高齢者住宅生活支援サービス事業は状況が分かりまして、ちなみに民間住宅あっせん事業における実績を少し見させていただきましたところ、３年間の推移では、平成２９年度が６件、平成３０年度が１１件、令和元年度が１４件と、微増となっているわけです。一方、高齢者住宅の申請数です。いずれにしても、生活保護受給者の方も含めた住まいの確保のための施策が必要だと考えますが、いかがでしょうか。","respondent":"菅野高齢者地域支援課長、櫻木生活福祉課長","answer":"こちらは、例年、６０名程度の申込みがございまして、実際に入居される方はその年によって変動がありますが、２０名から３０名の間あたりと認識しております。今後も、他法他施策、高齢者施策等を確認しながら対応してまいりたいと考えています。","voiceIndex":256,"id":"exchange-107"},{"speaker":"こんの委員","kind":"質問・要望","question":"このように要望して終わります。次に、障害児者福祉計画基礎調査についてお伺いいたします。こうした調査を基に、障害団体の方からのいろいろな要望やニーズなどが届いている。こうしたものを含めて計画策定を進める基礎調査だと認識しておりますが、基礎調査の目的・内容などを簡単にご説明ください。","respondent":"築山障害者施策推進担当課長","answer":"基礎調査につきましては、令和３年から令和５年の第６期障害福祉計画および第２期障害児福祉計画策定のために実施した調査です。","voiceIndex":259,"id":"exchange-108"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうしたことも含めて策定されていくのだろうと思っているわけですが、例えば障害者団体の方々からのお声として、「障害者の高齢化に伴い、障害福祉サービスから介護保険サービスへの移行や、両サービスを併用する場合、相談支援専門員とケアマネジャーの引継ぎについて、両者の密な連携と利用者への丁寧な説明・対応についての仕組みづくりを求めている」。現在の検討の進捗状況をお知らせください。","respondent":"松山障害者福祉課長","answer":"障害者福祉制度と介護保険制度のギャップを埋めるために、在宅介護支援センターに障害者の計画相談専門員を配置して、２か月に１回ですけれども、区も一緒に入って検討を行っております。その中で、１事例ごとに丁寧に、今、事例を積み重ねているです。","voiceIndex":261,"id":"exchange-109"},{"speaker":"こんの委員","kind":"質問・要望","question":"現状を簡単にご説明いただきました。この要望について、さらにご検討を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":263,"id":"exchange-110"},{"speaker":"鈴木（真）委員","kind":"確認","question":"私からは、２１５ページ、福祉計画費、それから２４３ページ、児童福祉費の中で児童相談所移管推進事業、それから２５３ページ、児童福祉費の児童保育費で、ぷりすくーる西五反田経費について確認させてください。前回も聞いたと思うのですが、東大井三丁目の元芝都営住宅の跡地が高齢者施設にというお話が前にあったと思うのですが、現在の進捗状況はどうなっているか、その点をまず教えてください。","respondent":"寺嶋福祉計画課長","answer":"その際、品川区のほうは、高齢者福祉施設等を中心とした福祉施設整備について前向きな考えを持っているという意向を翌月回答したという状況で、今の段階では、まだここまでです。","voiceIndex":266,"id":"exchange-111"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"区の回答ということで、ぜひそうやってもらいたいと思います。あれは特別養護老人ホームで、ここはどうなるか分からないですけれど、区の方にとってメリットのあるような形を、区としてもこれから東京都と折衝してもらいたいと思うのですけれど、もう一回、その辺のお考えを教えてください。","respondent":"寺嶋福祉計画課長","answer":"品川区としましても、ぜひこの計画が前に進むように東京都と協議を進めていきたいと考えております。","voiceIndex":268,"id":"exchange-112"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"土地は、地形もいいですが、１つだけ難点があり、道路が狭いので、あそこの入り口はやはり交通の便が、今の工事も大変だったと思うのですが、これからもその辺があると思うので、最後の要望としては、都にもその辺の要望はしておいていただきたいと。これは要望で終わります。平成１５年１２月ですか、就学前乳幼児教育施設条例で設置して、これが平成１６年６月に開設になったと思います。","respondent":"吉田保育施設調整担当課長","answer":"保護者への周知につきましては、９月に１回、保護者説明会を、これは新型コロナウイルス感染症の関係もありまして、集合形式ではなくオンラインになりましたけれども、ぷりすくーる西五反田は保護者会で説明をしています。","voiceIndex":270,"id":"exchange-113"},{"speaker":"鈴木（真）委員","kind":"質問","question":"説明会がそういう状況で行われたということですけれど、今度、来年の４月に向けて、応募する方への説明というのは何か行われるのでしょうか。やはり要項に記載していないと、今までと少し違う形で、後になってから「変わっていたよ」というのではまずいと思うのですけれど、その辺はどういう形を取っていかれるのか、教えてください。","respondent":"吉田保育施設調整担当課長","answer":"今後の、来年度からの児童の募集につきましては、指定管理者が変更になるという形で周知を図ってまいるところです。","voiceIndex":272,"id":"exchange-114"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その後、ＮＰＯ法人子育て品川のほうですけれど、これは区直接ではないですけれど、今後は解散という形で進むということで、考え方はよろしいのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"現在の指定管理者であります子育て品川につきましては、発展的解散という形になります。","voiceIndex":274,"id":"exchange-115"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それと同時に、これは認定こども園になる予定で、今、進めていらっしゃいますよね。これは、最初は今のまま福栄会がやったとして、今後、認定こども園になるメリットというと何を考えたらいいのか。そこの点についても教えてください。","respondent":"吉田保育施設調整担当課長","answer":"現在のぷりすくーる西五反田というのは０歳から２歳が保育所、それから３歳から５歳が幼児教育施設。これは今現在、認可外保育施設になっております。","voiceIndex":276,"id":"exchange-116"},{"speaker":"鈴木（真）委員","kind":"質問","question":"現在、幼稚園の先生と保育士が両方いるわけですよね。認定こども園になった場合には、両方の免許を持った方が教員という形で関わっていくと思うのですが、その方たちは福栄会が採用する形になっているのですか。現在の先生方というのは、そこから先はどういう立場になっていくのか、教えてください。","respondent":"吉田保育施設調整担当課長","answer":"幼保連携型認定こども園につきましては、保育教諭といいまして、幼稚園教諭プラス保育士の資格を持った方たちが従事することになるのですけれども、来年の４月以降、新しい事業者に変更になった後、認定こども園の開設に向けて準備をしていく予定です。","voiceIndex":278,"id":"exchange-117"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今の方たちをそのまま採用していただけるということで、そこは十分大丈夫なのですが、今後についてやはりまたいろいろ検討が必要だと思うので、その辺をよろしくお願いしたいのと、それから今まで、ぷりすくーる西五反田として子育て品川が培ってきた教育と保育という思いが、福栄会にどのように伝わっていくのか。その点についても知りたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"区としては、画期的な施設である、ぷりすくーるの位置づけは変わらないところです。今後の強化につきましては、来年度、社会福祉法人に移行した後、認定こども園立ち上げの期間までの数年間の中で、新しい幼保連携型認定こども園に向けて十分な準備を進める予定です。","voiceIndex":280,"id":"exchange-118"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先々、ぷりすくーる西五反田の隣に西五反田保育園もあるし、老朽化してきたときに、今後、一体化というのも考えられるのではないかと、先々また検討しておいてもらえばいかがでしょうかという、これは要望で、検討する必要もあるのではないかと私は個人的に思うので、その辺をよろしくお願いします。こちらが長くなってしまったので、児童相談所の関係です。その点を教えてください。","respondent":"加島児童相談所移管担当課長","answer":"ただいまの法令基準を満たす職員数を配置できるよう、人事課と協議の上、採用を進めており、令和３年度以降は各年度当たり、福祉職を１０名程度、心理職を３名程度、採用によって確保してまいる計画です。","voiceIndex":282,"id":"exchange-119"},{"speaker":"鈴木（真）委員","kind":"質問","question":"既に区の中でも社会福祉士等の資格を持っている方がいらっしゃると思うのですが、この方たちは何人ぐらいいらっしゃって、そのうち、この施設にどの程度の配置というか、考えていらっしゃるのか、その点もお聞きしたいと思います。","respondent":"加島児童相談所移管担当課長","answer":"そのため、庁内福祉職の全体調整とあわせまして、関係部署と協議を行ってまいりたいと考えているところです。","voiceIndex":284,"id":"exchange-120"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ちょうど今朝の新聞に出ていたのですけれど、里親の育成という報道が入っていました。今、品川区の中で里親の家庭というのはどのぐらいあって、また、今現在、どの相談所の中でどのぐらい里親の要望があるのか、また今後、区として里親にどういうふうに接していくのか、その辺について教えてください。","respondent":"加島児童相談所移管担当課長","answer":"こちらの１７家庭につきましては、区が、東京都から児童相談所の業務を引き継ぎました際は、区の里親として登録されることになります。その際、区といたしまして里親支援の包括的な養育支援の体制を組み立ててまいりたいと考えております。","voiceIndex":286,"id":"exchange-121"},{"speaker":"西本委員","kind":"質問・要望","question":"これは昨年度の決算特別委員会でも私は要望させていただき、研究していただきたいということで強く要望させていただきました。先ほど午前中には検討するという答弁がありましたけれども、本気度を教えていただきたい。本気度です。公立、そして私立、認証保育園、幼保一体化、品川区は一体、保育行政をどういう方向に持っていくのでしょうかということです。それについてのお考えをお聞きします。","respondent":"三ッ橋子育て応援課長、立木保育課長、加島児童相談所移管担当課長、廣田子ども育成課長","answer":"養育費につきましては、他区、また東京都の補助金等々に鑑み、いろいろな状況を見ながら対応してまいります。まだしばらくは乳幼児人口も増えていき、保育園の需要も一定程度見込まれるという中では、そこはしっかり対応した上で。そういった関係機関に相談する際に困らないよう、相談窓口の整理についても検討してまいります。現在、老朽化しているものの建て替えを機に、児童センターは１８歳までしか来られないのですけれども、その後の。","voiceIndex":289,"id":"exchange-122"},{"speaker":"西本委員","kind":"質問・要望","question":"それから保育行政なのですが、かつてはやはり保育の質一番というのが品川区の保育行政でした。今はどうなのでしょうかというところを深く考えていただきたい。今、質の問題ですよね。どうしていくのかという。なので、保育行政という中で、品川区はこれぞというものをぜひつくっていただいて、考えて進めていただきたいと思いますので、その見解をもう一度お聞きしたいと思います。保育行政だけお願いします。","respondent":"立木保育課長","answer":"今後の面では、のびしなプロフェッショナルスクールという研修機関も立ち上げております。そうした中、今後は、公立・私立を含め連携のレベルを合わせ、やはり地域一丸となって子育てをしていくというところで質を上げていきたいと考えています。","voiceIndex":294,"id":"exchange-123"},{"speaker":"西本委員","kind":"意見","question":"保育については、なかなか私立保育園とか、いろいろな施設が入ってくると、直接関わりにくくなる可能性もあります。直接ではないので。ですので、そうなるのを、質をしっかり見ていただいて、先を見通した保育行政をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":296,"id":"exchange-124"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"改めてお伺いしたいのですけれども、２０１５年の選定のときに、これは品川区としても当初、品川区の障害者福祉を変えたいとの思いで、思い切って選定されたのではないかと思います。他の委員からも、多くの委員から、事業内容は、フリーユニティーの提案内容が優れているという意見が次々と出されておりました。このことについて、まずお聞かせいただきたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"平成２７年度の選定理由です。総合評価といたしましては、選定事業者は、品川区障害者計画・障害福祉計画の実現に向けた提案に加え、堅実な実績と高い専門性に裏づけされた運営力を備えており、本事業の運営事業者として最適であると総合的に判断したと、当時、評価したものです。","voiceIndex":298,"id":"exchange-125"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今言われたように、最適な事業者だと総合的に判断して選定したということです。にもかかわらず、１年も経たずして９月２４日の厚生委員会で公募の報告がありました。それと私たちのところにも、今の事業者を絶対に変えないでほしいという声がたくさん届いています。利用者から品川区に声が届いているか、また届いているとしたら、どんな声が届いているかについてもお聞かせください。","respondent":"築山障害者施策推進担当課長","answer":"私には特にそういった声は届いておりません。","voiceIndex":300,"id":"exchange-126"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして伺いたいのが、２０１５年１月の厚生委員会で、「障害児者総合支援施設整備運営事業者の公募について」ということで報告があったのですけれど、ここでは、事業者選定は客観的な判断をして、よりよい事業者を選定するため、審査の基準表をきちんと作るということで書かれているのですが、今回の基準表というのも先日の厚生委員会の資料の中に書かれておりましたけれど。","respondent":"築山障害者施策推進担当課長","answer":"利用者の声というところにおきましては、こちらとしても、ホームページ等のお声は聞いております。ただ、公募につきましては公正・公平にという形で実施する予定になっております。","voiceIndex":302,"id":"exchange-127"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"先ほど、声が届いていないということだったのですけれど、ではホームページに載せられているような声というのは届いているということなのでしょうか。それから、このときになぜ４事業者の共同になったのかという質問が委員会の中で出されたときに、かなり幅広いサービスを行うということで、１法人で担うのはなかなか難しいのではないかということが課題としてあった。そこで共同提案を受付けることにしたと。","respondent":"築山障害者施策推進担当課長","answer":"それから調査につきましては特に実施する予定はございませんが、日々、施設の中には区も入っておりますので、お声等を聞く機会等もありますので、何かありましたらご意見はお聞きしていきたいと考えております。","voiceIndex":304,"id":"exchange-128"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのところでしていただきたいということを強く要望しておきます。私たち議員に対しても公表されないということですけれど、私はこういうのもしっかりと公表するという方向で、今、指定管理者の在り方という点でも検討されていると思うのですけれど、ぜひ、こんな真っ黒塗りで、何が何だか分からないという中身ではなくて、この公表についてもぜひしていただきたいと思いますが、いかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"公正・公平の担保につきましては、外部の有識者の方を入れることによって、専門的見地からもご意見を頂きながら、公正・公平な審査としていきたいと考えております。それから情報公開の在り方につきましては、条例に基づいて対応しています。","voiceIndex":306,"id":"exchange-129"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これを黒塗りにするという判断は、各部署によって決められるということで聞いております。継続性、それから利用者・区民の声、それから現事業者の実績をしっかりと評価していただくように強く要望しておきます。それから次に移りたいと思います。それから、国民健康保険の法定外繰入れは７億２,７９４万円ということで、この資料に書かれているとおりでいいのかということの確認もお願いします。","respondent":"池田国保医療年金課長","answer":"国民健康保険料につきましては、９月現在です。およそ１,５００件の申請がございまして、現年度分、令和２年度分ですけれども、こちらのほうの保険料がおよそ２億円ほどの減額という形になります。","voiceIndex":308,"id":"exchange-130"},{"speaker":"鈴木（博）委員","kind":"質問","question":"高齢者施設における新型コロナウイルス感染症対策についてお伺いします。本年４月以降の品川区高齢者施設における新型コロナウイルス感染症の検査陽性者の発生件数をお示しください。","respondent":"宮尾高齢者福祉課長","answer":"高齢者施設はこれまでも感染防止対策を徹底してまいりましたが、７月の中旬に最初の陽性者が報告されました。以降、昨日時点ですが、累計で３４名の陽性者の報告が上がっております。３４名の内訳ですが、利用者・入所者が１５名、職員が１９名という状況です。","voiceIndex":311,"id":"exchange-131"},{"speaker":"鈴木（博）委員","kind":"意見","question":"今お話があった施設利用者と職員別々に、重症者数および陽性者の療養場所がどのように割り振られているのか、あるいはその人たちのその後の転帰はいかがだったのか、ご説明をお願いいたします。","respondent":"宮尾高齢者福祉課長","answer":"高齢者施設で陽性者が発生いたしますと、保健所の指示の下、連携を取りながら対応させていただいているところです。利用者１５名につきましては、療養場所としては全員、医療機関への入院ということになりました。経過です。既に退院・退所された方が９名いらっしゃいます。","voiceIndex":313,"id":"exchange-132"},{"speaker":"鈴木（博）委員","kind":"質問","question":"既に回復し、病院から退院してきた入所者に対して、施設ではどのような対応をされているのでしょうか。この間、新型コロナウイルス感染症の発生で閉鎖された施設はあるのでしょうか。あったとしたら、その間、どのような対応をされたのでしょうか。ご説明をお願いします。","respondent":"宮尾高齢者福祉課長","answer":"新型コロナウイルスの感染前に介護保険を利用していなかった方で、退院後の生活にご心配がある場合には、高齢者福祉課または在宅介護支援センターにご相談いただいて、適切に対応しています。","voiceIndex":315,"id":"exchange-133"},{"speaker":"鈴木（博）委員","kind":"意見","question":"新型コロナウイルス感染症は、若年者では軽症または無症状で経過するのに対し、高齢者は重症化しやすく、厚生労働省によれば、我が国での２０歳代までの致死率は０％であるのに対し、７０歳代では１０.９％、８０歳以上では２３％にも上ると報告されております。新型コロナウイルス感染症の流行がいまだに続く中で、高齢者施設の感染対策について、区の方針を大局的にご説明ください。","respondent":"宮尾高齢者福祉課長","answer":"こういった対策が何よりも大切かと認識しております。そのために、手洗い、アルコール消毒、マスクの着用、体温測定といったことを徹底しますとともに、施設内の消毒、それから定期的な換気等を徹底しております。","voiceIndex":317,"id":"exchange-134"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"１１月からいよいよアビガンも使用できるようになりますので、軽症から中等症の感染者に対しては、必要な場合に医療的ケアも併用して対応するなど、最もハイリスクな集団である高齢者をしっかりと守る施策の着実な実施を区に強く要望いたしまして、次の質問に移りたいと思います。次に、新型コロナウイルス感染症流行下での病児保育の現状についてお伺いいたします。","respondent":"吉田保育施設調整担当課長","answer":"２０２０年度の病児保育施設の実績についてお答えいたします。現在、病児保育施設につきましては、区内に４か所、内訳は、医療機関併設型が３か所、保育所併設型の病児保育施設が１か所あります。８月分までの実績数値を申し上げます。","voiceIndex":319,"id":"exchange-135"},{"speaker":"鈴木（博）委員","kind":"確認","question":"１か所を除き、ほぼ１割にも満たないという利用状況が、今、確認できました。ただ、この間、感染症そのものも流行していなかったので、それを反映しているとも考えられます。この間、病児保育所での新型コロナウイルス感染症のクラスターの発生の報告等はあったのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"区内の病児保育施設において、新型コロナウイルス感染症のクラスターは発生しておりません。","voiceIndex":321,"id":"exchange-136"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"今回の新型コロナウイルス感染症流行に対しまして、病児保育施設の側から、特に何か区に要望等はあったのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"区の委託事業で行っているところから、病児保育施設には定期的に一定数の配布を行ってきたところです。区に対する要望としましては、新型コロナウイルス感染症が拡大する中、病児保育を継続していくのかどうか、区の見解が欲しいというご意見も頂いたところです。","voiceIndex":323,"id":"exchange-137"},{"speaker":"鈴木（博）委員","kind":"意見","question":"新型コロナウイルス感染症の流行時は当然、病児保育の利用希望者の中に感染者が混じってくる可能性が十分想定されます。病児保育所は、医療機関と同じく、症状を持つ感染者が集まるため、クラスターが発生するリスクが非常に高い施設です。品川区として、新型コロナウイルス感染症流行下の病児保育事業の運用について、どのような点に注意して、どのような方針を立てて臨んでいるのか、ご説明ください。","respondent":"吉田保育施設調整担当課長","answer":"緊急事態宣言解除後におきましては、保育園に通園する園児も増えることが予想されたところでしたが、第一に保護者に自宅待機を要請しながらの通園再開になるため、利用者がすぐには戻らないこと、第二に新型コロナウイルス感染症が終息していないことから。","voiceIndex":325,"id":"exchange-138"},{"speaker":"鈴木（博）委員","kind":"意見","question":"ということは、逆に言うと、入所者が非常に少ないので経営上も非常に厳しいということになると思います。この事務連絡は９月３０日までということになっておりますが、１０月以降の取扱いについても併せてご説明をお願いいたします。","respondent":"吉田保育施設調整担当課長","answer":"令和３年１月以降の取扱いにつきましては、利用状況を踏まえつつ、特例措置の縮小も含め検討し、改めて示すとされているところです。","voiceIndex":327,"id":"exchange-139"},{"speaker":"鈴木（博）委員","kind":"意見","question":"新型コロナウイルス感染症が長期にわたるような場合、例えば病児保育所に、発熱・風邪症状の子どもを、新型コロナウイルス感染症の抗原検査を行った上で、１５分で結果が出ますから、積極的に預かるとか、さらに新型コロナウイルス感染症の検査陽性者の施設療養を逆に病児保育所が担うとか、様々な病児保育所の活用や利用ということも想定できると思いますので。","respondent":"吉田保育施設調整担当課長","answer":"そのため、地域バランスを考えまして、より積極的な支援に取り組んでいきたいと考えているところです。抗原検査等につきまして、利用者・関係者の安全・安心等の確保も考え、今後検討してまいりたいと考えています。","voiceIndex":329,"id":"exchange-140"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最後に、障害児家庭に対する在宅小児往診事業についてお伺いいたします。来年１月から、医療的ケア児等総合支援事業（地域生活支援促進事業）による医療的ケアが必要な親子に対する、遊び場、交流、集いの場の提供が始まります。これは大いに期待されるところであります。現在、高齢者の在宅医療は整備されてきましたが、小児の在宅医療は未整備のままです。その理由について簡単にご説明をお願いいたします。","respondent":"松山障害者福祉課長","answer":"第一に、全体を把握し統括するような医療関係のコーディネーターがいないということ、第二に、やはり在宅で障害のあるお子さんの数が少なく、重度の方であり、地域のかかりつけ医の方々よりも、生まれたときからの主治医の病院とのつながりを持っていることが挙げられます。","voiceIndex":331,"id":"exchange-141"},{"speaker":"鈴木（博）委員","kind":"提案","question":"私も参加して研修を受けました。そのために、まずできるところから手を挙げられないか、区としても考えていただきたいと思います。例えば１つの提案ですが、小児科医が往診して、障害児の自宅で予防接種を行うなどは、小児科医にとっても敷居が低く、比較的取り組みやすい事業だと考えます。このような事業も１つどうかと提案したいのですが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"予防接種の往診接種のご提案です。ご協力いただける医師の方がいらっしゃるのは非常にありがたいところですが、本人やご家族の意向、本人の障害の程度、医療的ケアの状態、個別性が高いので、一斉に実施する事業というのは難しいのではないかと考えています。","voiceIndex":333,"id":"exchange-142"},{"speaker":"若林委員","kind":"質問","question":"民生費全体と、４３９ページの後期高齢者歯科健診事業についてお聞きします。全体としては、今回の令和元年度の決算として、民生費の執行率が９５.４％、不用額が４０億円強ということで、区全体の不用額のうち、どうしても大きくなります４０.６％が、民生費で出ていると。この辺は１つ、少し課題かと思いますので、この辺のことについて、考え方、取り組み方をお聞きしたいと思います。","respondent":"品川財政課長","answer":"表現、それから説明のほうですけれども、昨年度から始めております予算編成過程を、また１２月ぐらいから、所管課の要求額等も出していって、２月頃にはどういう査定をしたかというところの査定額も出していきたいと思っています。","voiceIndex":336,"id":"exchange-143"},{"speaker":"若林委員","kind":"質問・要望","question":"予算書上で、そうなると事項別明細書も当然出てきます。もし追加するとしたら、記載する項目が多くなってしまうかもしれませんが、いずれにしても来年の予算の審議については、やはり１つの大きな焦点になると、これはもう確実に言えることだと思いますので、見せ方、説明の仕方、予算書の作り方、こういったところは十分に吟味していただきたいと思います。この不用額と内容についてお聞きしたいと思います。","respondent":"池田国保医療年金課長","answer":"こちらの検査の結果の検討状況ですけれども、８月に、両歯科医師会の代表の方と私ども事務局とで打合せを致しまして、昨年度の受診の内容について報告をさせていただいた後、実際の細かなものについても、内容について精査して。","voiceIndex":338,"id":"exchange-144"},{"speaker":"若林委員","kind":"質問・要望","question":"全国に先駆けてといいますか、本当に品川区独自に、国保医療年金課、また健康推進部としてこういうところに着目して、また専門家と協働してというところで、非常に敬意を表する事業の一つだと申し上げて、内容についてはまた来年度しっかりと検証していただいて、区内全体、高齢者の方々のフレイル予防、健康寿命に寄与していただきたい。","respondent":"池田国保医療年金課長","answer":"今、委員がおっしゃったように、これからは、医師の皆様のほかにも薬剤師の方も含めて広くご協力いただいて、高齢者の方の健康について頑張っていきたいと思ってあります。","voiceIndex":340,"id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"質問","question":"２３５ページの障害者福祉費、障害児者総合支援施設運営経費と、２５３ページ、ぷりすくーる西五反田経費。ほかの委員の方からもご質問がありましたけれども、まず障害児者総合支援施設のほうですけれども、児童発達支援、放課後等デイサービス、子ども発達相談室の業務についてお尋ねします。これは半年間です。今年度の指定管理料はお幾らになっているでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"１億３,４９５万９,２０２円となっております。","voiceIndex":343,"id":"exchange-146"},{"speaker":"高橋（し）委員","kind":"質問","question":"１億３,０００万円余ということですが、事項別明細書を見てみると、２億３３万円になっているのですが、その点の違いはどういった状況なのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"しかしながら、３月に職員体制について事業者に確認したところ、予算要求時の提案と乖離があったため、実態に合わせて指定管理料を支払うこととしたため、差異が出ているものです。","voiceIndex":345,"id":"exchange-147"},{"speaker":"高橋（し）委員","kind":"質問","question":"予算要求時の体制と乖離があったため精査したということです。その中の子ども発達相談室ですけれども、初回相談まで、つまり「面談・相談したいのですけど」というところから面談していただくまでの待機時間というのは何日ぐらいになっているでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"現時点で初回相談の申込みをしますと、来年の３月になるということで、今、およそ５か月ぐらいの待ちとなっております。","voiceIndex":347,"id":"exchange-148"},{"speaker":"高橋（し）委員","kind":"質問","question":"１０月に申し込んでも来年の３月になってしまうということです。そして今お尋ねしたご答弁で、現在も５か月待つということです。この５か月待ちという現状を区としてどう捉えているでしょうか。そして、このように時間がかかってしまうということは、児童福祉の専門的な見地から、その後の発達支援・療育を含め、どのような影響が出てくるか、あるいは出ているか、お尋ねします。","respondent":"築山障害者施策推進担当課長","answer":"委員のおっしゃるとおり、早期発見・早期療育というのは非常に大切なこととなっております。区といたしましても、初回相談までの期間を短くするよう、事業者には取り組んでいただきたいと思って、支援等をしています。","voiceIndex":349,"id":"exchange-149"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほどお話しした子ども発達相談室の初回相談までの時間が非常に長いということ、それから今の児童発達支援と放課後等デイサービスの利用数、稼働率が低い、このような課題に関して今も改善されていないことを、区は認識されているのでしょうか。そして、認識しているとすると、今、事業者に対して支援や指導というお話がありましたが、どのような形で支援をしたり指導をされてきたのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"課題としては認識しています。","voiceIndex":351,"id":"exchange-150"},{"speaker":"高橋（し）委員","kind":"質問","question":"そういう形で、事業者がサービスを厚くするために、区として指定管理料の支援をするというようなことも約束していただいています。しかし、残念ながら現状の、先ほどの５か月待ちや利用率が低いということに関しては、やはり区のほうの指導の側面がまだまだ足りないのではないかと思いますが、その辺はいかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"引き続き指導してまいりたいと考えています。","voiceIndex":353,"id":"exchange-151"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"引き続き指導されるということですが、先ほどの支援という、いろいろな面での支援も含め、ぜひお願いしたいと思います。というようなお話をさせていただき、先日も歳入の件でお話しさせていただきましたが、障害児者総合支援施設については、拠点というご答弁を、先日の厚生委員会で課長はお話しされました。拠点というところをもう少し具体的にお話ししていただきたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"拠点の説明になりますが、こちらは地域生活支援拠点の機能を持たせております。重症心身障害や高齢化といったことに対応できるような体制をつくること、それから親なき後の支援を見据えた支援をする施設として考えております。","voiceIndex":355,"id":"exchange-152"},{"speaker":"高橋（し）委員","kind":"質問","question":"親なき後の方の生活の場、支援を含め、拠点というお話を頂きました。最後になりますが、少し大きな視点になりますけれども、将来的な視点から見まして、区の障害児者福祉施策の全体から見て、この施設はどのような役割を担うのでしょうか。障害者福祉課としての今後のビジョンを、少し大きなくくりになるのですが、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"障害児者総合支援施設もそうですけれども、各施設ご利用者へのサービスの向上はもちろんのこと、区全体としては、区と一緒に意向を合わせて、事業者全体でニーズを把握すること、そしてそのニーズの情報が区に吸い上げられて。","voiceIndex":357,"id":"exchange-153"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"区民の方々のニーズに合わせた、体系立った福祉施策の中心の施設にしていきたいということですので、今後とも利用者の方たちにとってよりよい施設になるように、先ほどの支援、そして指導を、各事業者にとってしっかりと協議しながら進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":359,"id":"exchange-154"},{"speaker":"藤原委員","kind":"質問","question":"社会福祉協議会助成の中には、成年後見センターの助成はないという理解でいいのでしょうか。全国の最先端を行く品川区の成年後見センターについて、障害者の方についてはどのようになっているかをお伺いします。区内にはあるのでしょうか。８２人というのは、どこにある施設に入っているのでしょうか。待機者はどのぐらいいらっしゃるのですか。以上、４点お伺いします。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長、廣田子ども育成課長、松山障害者福祉課長、三ッ橋子育て応援課長","answer":"残りの１００万円につきましては、実際の成年後見の申立てのケースの中で、終わった後に。なかなかすぐに特効薬のようなことというのは難しいところではあるのですが、そうはいいましても、できるものから、できることから。２４１ページの多世代交流支援事業ですけれども、これにつきましては、児童センターとシルバーセンターであったり。やはり成年後見制度の利用を支援することによって、障害者の権利擁護を図るということが大事な目的となっております。","voiceIndex":361,"id":"exchange-155"},{"speaker":"藤原委員","kind":"質問","question":"養護老人ホームなのですけれど、待機者はどのぐらいいるのですかという質問もしました。今後、区としてどのように位置づけていくのかという質問もしました。今度、いろいろな臨時特別給付金が出ると思いますが、新しい制度がどんどん入ってくるわけで、所管課の方は本当に大変だと思いますが、よろしくお願いいたします。","respondent":"宮尾高齢者福祉課長","answer":"これからも引き続き、制度の趣旨をしっかりと踏まえて適切に対応してまいりたいと考えております。","voiceIndex":368,"id":"exchange-156"},{"speaker":"藤原委員","kind":"質問・要望","question":"それは、介護に携わっている方の思い。今日は秋晴れですけれども、台風が来ても雪が降っても雨がっぱを着て、求める人がいれば、お正月も連休も関係なく行くわけですから。９月に連休が４日間ありました。だから、介護保険で賄っているからということではなくて、品川区の福祉なのだから、根底を支えている方たちに、どうにかしていただきたいと思って訴えさせていただきましたが、いかがでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"今後も、どういったことで、介護に携わる方たちをしっかりとお支えできるかということは、しっかりと念頭に入れながら、これからも業務を遂行してまいりたいと考えています。","voiceIndex":370,"id":"exchange-157"},{"speaker":"藤原委員","kind":"質問・要望","question":"施策の中で、外国の方々、すばらしいと思います。外国の方たちに介護に携わっていただくというのも１つあると思う。でも、まず日本の、今この国で支えてくださっている方たちに応えましょう。あれだけ朝から晩までやってくださっているのですから。だから、その辺についても整理して、介護職の方たちが、誇りは持っていると思う。ぜひ、その辺も含めて、もっと力強い答弁を頂きたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"ですので、どちらかということではなくて、もちろん今頑張っていただいている方たちに対する尊敬の念というのは、それによって損なわれるとか、それがなくなるということは決してございません。そこだけはまずご理解いただきたいと考えています。","voiceIndex":372,"id":"exchange-158"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、２２７ページ、同行援護、２２９ページ、移動支援事業（ガイドヘルプ）について質問します。移動支援事業での対応を求める議論もされていますが、本来的には、視覚障害者のための自立支援給付である同行援護で対応すべきと考えます。あんま師がマッサージをしに行く際にも同行援護を利用できるようにすべきですが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"同行援護につきましては、障害者総合支援法の自立支援給付という、全国一律の制度です。制度上、通勤、経済活動に関わる外出を除くとされておりますので、こちらについて、重度の障害のある方を支援する同行援護のご利用は制度上難しいということになっております。","voiceIndex":375,"id":"exchange-159"},{"speaker":"のだて委員","kind":"質問・要望","question":"通勤などに使うことは難しいという話なのですが、障害者権利条約の第２０条には個人の移動を容易にすることという項目があります。もちろんこれは日本も批准しておりますけれども、働くことは生活をする上で必要なことですし、当事者自身の自立支援のためにも必要であり、その移動を保障することが求められます。区は、視覚障害者が通勤する上で、ガイドの必要性をどう考えているのか、伺います。","respondent":"松山障害者福祉課長","answer":"同行援護の対象の方は重度の視覚障害者であるということで国が規定しているものです。なかなか区で、一律の制度について、国にご意見を上げることはできても、変えるということは難しいのが現状です。","voiceIndex":377,"id":"exchange-160"},{"speaker":"のだて委員","kind":"質問・要望","question":"国に求めることはできるということですから、ぜひそこの拡充を区として求めていただきたいと思いますが、いかがでしょうか。一般的に、働いている人が多いわけですから、生活するために同行援護が必要なわけです。ですから、利用できるようにすべきだと思います。同行援護が仕事に利用できないのは合理的配慮に反するのではないかと思いますが、いかがでしょう。","respondent":"松山障害者福祉課長","answer":"例えば大井町駅のホームで電車の乗り降りをしたり、バスを借りて、そこの乗り降りを支援したり、あるいは食事の支援、エスカレーターの同行支援までカリキュラムに規定されております。そういった意味では、支援が必要な方に同行援護をサービスとして提供するものと考えています。","voiceIndex":379,"id":"exchange-161"},{"speaker":"のだて委員","kind":"質問・要望","question":"地方自治体で合理的配慮に反するかどうかという、解釈を論じる場ではないと言いますが、区としてやはり必要だと感じているのであれば、国に求めて改正をしてもらうということが必要なのではないかと思いますけれども、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"確かにいらっしゃるとは思いますが、人それぞれ異なる可能性が高いです。同行援護を使わずに、ご自身で通勤されている方も多くいらっしゃいます。","voiceIndex":381,"id":"exchange-162"},{"speaker":"のだて委員","kind":"質問・要望","question":"人それぞれというお話ですけれども、それをしっかり選択できるということが合理的配慮にもつながってくるということになりますので、ぜひそういった立場で拡充していっていただきたいと思いますし、国にも求めていっていただきたいと思います。移動支援事業でもよいというあんま師の方には、利用できるようにしていただきたいのですが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"国が実施する地域生活支援事業の中のものですけれども、ニーズとしてはまだ区にお声を頂戴していないというところですので、今後ニーズがあればまた検討していきたいと考えています。","voiceIndex":383,"id":"exchange-163"},{"speaker":"のだて委員","kind":"質問・要望","question":"通院の制限はもってのほかですが、趣味の活動を週１回やらなくてもいいのではないかと言われた方もいます。生活が制限されない同行援護の支給時間の設定を求めますが、いかがでしょうか。これまで利用を制限してきたことがガイドの養成を抑制してきたものと考えますけれども、同行援護のガイドを増やしていくために、ガイドを養成する講習会を定期的に行っていただきたいと思いますが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"同行援護の支給時間についてのお尋ねです。委員がおっしゃられるとおり、支給は制限しておりませんし、国の基準に基づいて行っております。今後、再度、相談員に、基準については周知を図り、きちんとアセスメントができるように指導していきたいと考えています。","voiceIndex":385,"id":"exchange-164"},{"speaker":"たけうち委員","kind":"確認","question":"２１５ページの高齢者安否確認事業で緊急通報システムを中心に、それから２１９ページの熱中症等予防対策、それから４１９ページの特定健康診査事業費を伺います。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長、池田国保医療年金課長","answer":"もう一つ大きな視点で、見守りということに関しましては、例えば高齢者相談員の見守りや。実績等につきましては、ほぼ例年並みの実績だと認識しています。国民健康保険特定健康診査についてです。やはりコロナ禍の影響がございまして、開始が若干遅れてあります。","voiceIndex":388,"id":"exchange-165"},{"speaker":"たけうち委員","kind":"確認","question":"高齢者の安否確認、また今、状況をお聞きいたしましたけれど、孤立死という、今、非常に、何年か前から大変クローズアップされていますけれど、以前にも一般質問させていただきましたが、孤立死、または孤独死という定義が明確ではないと。ですので、恐らく品川区としてどのように定義されて、例えば品川区の孤立死、孤独死は何名なのですかとお聞きしたときに、どのようにお答えするのかというのが１つ。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長、池田国保医療年金課長","answer":"うち、救急搬送された方は８５件ございました。残念ながら搬送後、死亡が確認された方が１件ございました。私からは、私ども高齢者福祉課、そして在宅介護支援センターが緊急対応させていただいて、そのうち残念ながらお亡くなりになった方の数です。国としましても、目標の数値は、品川区の目標の数値もかなり高いところがありますけれども、それを目標に今後も努力していきたいと考えるところです。","voiceIndex":392,"id":"exchange-166"},{"speaker":"たけうち委員","kind":"意見","question":"それで、高齢者の孤立死という話の中で、いろいろ件数を頂いて、８５件の方は救急搬送されて、１件の方は残念ながらお亡くなりになったということなのですけれども、ただ８４人の方が何らかの形で命が救われたということで、人の見守りや地域の見守りももちろん大事な要素なのですけれど、こうしたコロナ禍の中で言えば。","respondent":"寺嶋福祉計画課長","answer":"もう一つ考えられるのは、やはり電話の仕組みが、携帯電話、スマートフォンというふうにだんだん変わってきまして、警備会社もそういった対応ができるように、今、変更もしていただいておりまして、今その利用も増えていますので、今後またそういった機器の普及に伴って。","voiceIndex":396,"id":"exchange-167"},{"speaker":"大倉委員","kind":"質問・要望","question":"福祉団体に対する助成金で、７団体あって、今までもこうした方たちから障害者福祉の施策について、平時からいろいろとご意見を聞いているかと思うのですが、今回の新型コロナウイルス感染症拡大に伴って、緊急事態宣言が発せられ、その後、新しい生活様式というのも求められてきた中で、その状況下においての団体からのニーズ把握をどのようにされたのか、教えてください。","respondent":"松山障害者福祉課長","answer":"私どもは団体というよりは個人の方、日頃のケースワークを通じた、あるいは相談支援を通じて、あとは施設、通所施設あるいは入所施設からのお声というのが入ってきている。そのほうが迅速に把握でき、その声に対応しています。","voiceIndex":399,"id":"exchange-168"},{"speaker":"大倉委員","kind":"質問","question":"個人や入所施設の方からのほうが迅速だというお話で、こうした団体からのヒアリングは、私たちも会派で受けたり、何度もいろいろしていますが、行政として、そうしたニーズの把握というのはしていってもいいのかなと思ったのですが、その点について伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"１点目の、団体からのお声を聞くヒアリングについてです。例えば今回、計画策定にあたりましても、ヒアリングは行っておりますし、またヒアリングの機会はなくとも団体からご要望を頂戴しておりますので、日常的にコミュニケーションを取っている形になります。","voiceIndex":401,"id":"exchange-169"},{"speaker":"大倉委員","kind":"質問・要望","question":"フェイスシールド。様々工夫して情報発信についても取り組んでいただきたいと思いますので、よろしくお願いいたします。現在４年経ちましたが、登録数はどのようになっているのでしょうか。教えてください。","respondent":"廣田子ども育成課長","answer":"登録数ですけれども、令和元年の新規ダウンロード者が２,７３７件、累計で１万６,０００件余となっています。","voiceIndex":403,"id":"exchange-170"},{"speaker":"大倉委員","kind":"質問・要望","question":"そうした中、１万６,０００件ということで、４年経って１万６,０００件、４で割り返すと年間４,０００人ずつ登録というかダウンロードがあるのかというところで、今後さらにしながわパパママ応援アプリを、区としても情報発信で使っていかれると思うのですが、そうしたときの数をどのように捉えているのか、考えを教えていただきたいと思います。","respondent":"廣田子ども育成課長","answer":"累計のダウンロードはその数なのですが、アクセス数は月３万件から６万件という形で、かなり使われているということなので、ここをブラッシュアップしながらという形で進めていこうと考えています。","voiceIndex":405,"id":"exchange-171"},{"speaker":"大倉委員","kind":"質問","question":"そうしたアプリの中身の、さらに使いやすくしていくというところの取組みについては、様々、意見を聞く場を設けてもいいのかなというところで、そういった意見が言えるような場所であったり、聞き取りみたいなものが行われたりされているのか、教えてください。","respondent":"廣田子ども育成課長","answer":"公園の部分につきましては、大学との連携で、大学のほうでいろいろ研究して取り組んでもらったものです。アプリを稼働してから５年経ちますので、今後の使い方については見直しを考えているところです。そのときにいろいろな意見を聞いて進めていこうと思ってあります。","voiceIndex":407,"id":"exchange-172"},{"speaker":"大倉委員","kind":"意見","question":"見直しの際、ぜひ様々な意見を、使ってくださるパパママの方たちからヒアリングしていただいて、より使いやすくて、さらに利用してもらえるようなアプリにしていただければと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":409,"id":"exchange-173"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、２１９ページ、特別養護老人ホーム運営費と、２３９ページ、子育て支援推進費について伺います。八潮南特別養護老人ホームについて伺います。ここは当初、旧八潮南中学校の校舎を有効活用するため、区立特別養護老人ホームの改築を行ったということであります。大変ご苦労もあったかと考えていますが、これまでの状況をどのように考えておられたのかということを、まず伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"今後の計画ということですけれども、今現在、敷地の中に、まだ活用していない、いわゆるデッドスペースという部分が存在していることから、その辺りも広く活用しまして、今、野球のグラウンド等に使っている校庭もありますけれども、その辺りをうまく活用して。","voiceIndex":411,"id":"exchange-174"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほど、定員増ということもありましたが、建て方にもよるのでしょうけれど、約七、八十床とか１００床ぐらい増えるような気がしてなりません。そうすると、もう一個考えられるのは、Ｌ形の１つのほうは、使わなくなるということであると思います。そういう利用分けもできているわけでありますので、その辺のところも含めてしっかり考えていただきたいと思いますが、もう一回お願いしたいと思います。","respondent":"寺嶋福祉計画課長","answer":"新しく増築する部分につきましては、全く制約なしで造れる施設ということになりますので、今のスタンダードのユニット型の個室特別養護老人ホームという形を基本に進めていくことになろうかというところも、検討段階ではありますが、１つの案として所管課で考えているところです。","voiceIndex":413,"id":"exchange-175"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひそれはよろしくお願いします。よろしくお願いします。それから子育て支援推進費のほうに移らせていただきたいと思います。それで、その部分で在宅子育てをこれから強化していく。私が確認したいのは、まず出てきたときに、いろいろ見直した、では結果、在宅子育ての予算はマイナスになりましたということはないですよねというところから入りたいんだ。そこだけは先に確認したいと思います。","respondent":"廣田子ども育成課長","answer":"年少人口が増えて乳幼児の課題が増えているというところで、様々な部門・分野から見直しをかけているところですので、具体的な形は今お示しできませんけれども、取り組み始めているということを申し上げておきたいと思います。","voiceIndex":415,"id":"exchange-176"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"既に２年も３年も前から、我々としたら、そういう意味では、形、仮称みたいなものをつけて政策要望も出しているのだけど、ママランチカフェみたいなことをやってください、在宅で子育てをしているママたちの居場所をいろいろなところにつくっていってほしいということはさんざん言っているわけで、その辺のところは９日にやった後でいいので、どういう形で具現化していくかということを。","respondent":"廣田子ども育成課長","answer":"一度には少人数しか集めることができませんが、間を開けて何回か話し合いを重ねていくということで、具現化するということに努めてまいります。","voiceIndex":417,"id":"exchange-177"},{"speaker":"石田（秀）委員","kind":"確認","question":"これは多分、具現化していくときには、場所もありますし、その前は位置づけをしていただいて、助成金が入って、来られる方々のアンケートも２年ぐらい全部取った。これが事実なのかどうかというのを確認したいのが１つと、今みたいな具現化はいろいろな資料がもう出ているので、その辺を踏まえて、一歩前へ進んでいただく。回数を重ねるよりも前へ進んでいくということを、改めてもう一回伺いたいと思います。","respondent":"廣田子ども育成課長","answer":"ただ、町会会館を貸していただけるというところのお声がかかっているので、そこの調整がつけば回数が増えてというところで、戻すことができるかもしれないのですけれども、現在調整中です。","voiceIndex":419,"id":"exchange-178"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1488#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":126950,"voices":421}}]);
